/* ══ PER-USER PERSISTENCE LAYER ══
   All business data is scoped to the logged-in account id and stored under a
   per-user key. Uses the sandbox-safe artifact storage API when present, and
   degrades gracefully to in-session-only when it is not. No data ever crosses
   between accounts: each account reads/writes only its own key, and the working
   state is fully reset on sign-out. */
const APP_VERSION="1.0.0";
const MM_BRAND="data:image/png;base64,";
