function mmHasStore(){try{return typeof window!=="undefined"&&window.storage&&typeof window.storage.get==="function"&&typeof window.storage.set==="function";}catch(e){return false;}}
function mmSave(key,val){
  try{
    if(mmHasStore()){
      var p=window.storage.set(key,JSON.stringify(val),false);
      if(p&&typeof p.then==="function")return p.then(function(){return true;}).catch(function(){return false;});
      return Promise.resolve(true);
    }
  }catch(e){}
  return Promise.resolve(false);
}
function mmLoad(key){
  try{
    if(mmHasStore()){
      var p=window.storage.get(key,false);
      if(p&&typeof p.then==="function"){
        return p.then(function(r){
          if(r&&r.value){try{return JSON.parse(r.value);}catch(e2){return null;}}
          return null;
        }).catch(function(){return null;});
      }
    }
  }catch(e){}
  return Promise.resolve(null);
}
function mmHash(s){
  // SHA-256 via WebCrypto when available; resolves null if unavailable so callers can fall back.
  try{
    if(typeof window!=="undefined"&&window.crypto&&window.crypto.subtle&&typeof TextEncoder!=="undefined"){
      return window.crypto.subtle.digest("SHA-256",new TextEncoder().encode("mm.v1:"+s)).then(function(buf){
        var a=new Uint8Array(buf);var out="";
        for(var i=0;i<a.length;i++){out+=("0"+a[i].toString(16)).slice(-2);}
        return "sha256:"+out;
      }).catch(function(){return null;});
    }
  }catch(e){}
  return Promise.resolve(null);
}
function mmCheckPw(input,stored){
  if(typeof stored!=="string"||!stored)return Promise.resolve(false);
  if(stored.indexOf("sha256:")===0){return mmHash(input).then(function(h){return !!h&&h===stored;});}
  return Promise.resolve(input===stored); // legacy plaintext accounts; upgraded on next sign-in
}

