// ── Navigation links (no API key needed — plain Google Maps URLs) ──
const mapsUrl=function(addr){return "https://www.google.com/maps/dir/?api=1&destination="+encodeURIComponent(addr||"");};
const routeUrl=function(stops){
  var s=(stops||[]).filter(function(x){return x&&String(x).trim();});
  if(s.length>10)s=s.slice(0,10); // Google Maps directions URLs support ~10 stops
  if(s.length===0)return null;
  if(s.length===1)return mapsUrl(s[0]);
  var dest=s[s.length-1];var ways=s.slice(0,s.length-1);
  return "https://www.google.com/maps/dir/?api=1&destination="+encodeURIComponent(dest)+"&waypoints="+ways.map(function(w){return encodeURIComponent(w);}).join("%7C")+"&travelmode=driving";
};
const validateEmail = v => (!v||/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v))?null:"Enter a valid email";
const validateZip   = v => (!v||/^\d{5}(-\d{4})?$/.test(v))?null:"Enter a valid ZIP";

const genCustId = (firstName, lastName, allCustomers, phone, phoneType) => {
  const seq=String(allCustomers.length+1).padStart(4,"0");
  const ini=((firstName||"X")[0]).toUpperCase()+((lastName||"X")[0]).toUpperCase();
  let suffix;
  const digits=(phone||"").replace(/[^0-9]/g,"");
  if(phoneType==="landline"){const n=allCustomers.filter(c=>c.phoneType==="landline").length+1;suffix="LL"+String(n).padStart(2,"0");}
  else if(phoneType==="international"||digits.length<3){const n=allCustomers.filter(c=>c.phoneType==="international"||!c.phone).length+1;suffix="IN"+String(n).padStart(2,"0");}
  else{
    // Last 3 digits of phone, reversed — works regardless of formatting
    suffix=digits.slice(-3).split("").reverse().join("");
  }
  // Full internal ID: seq is hidden from display but kept for uniqueness
  return seq+ini+suffix;
};
// Display helpers — strip the hidden 4-digit sequence prefix from IDs
const dispCustId=function(id){return id?id.slice(4):id;};
const dispVehId=function(vid){
  // V01-0001DB765 -> V01-DB765
  if(!vid)return vid;
  return vid.replace(/-(\d{4})([A-Z]{2})/,"-$2");
};
const dispJobId=function(jid){
  // J001-V01-0001DB765 -> J001-V01-DB765
  if(!jid)return jid;
  return jid.replace(/-(\d{4})([A-Z]{2})/,"-$2");
};
const genVehicleId=(customerId,allVehicles)=>{
  // Uses the highest existing sequence number (not array length) so archived/restored
  // vehicles can never cause a duplicate ID — deleting from the active list must not
  // free up a number that's still in use by an archived record.
  var nums=allVehicles.filter(function(v){return v.customerId===customerId;}).map(function(v){var m=/^V(\d+)-/.exec(v.vehicleId||"");return m?parseInt(m[1],10):0;});
  var next=(nums.length?Math.max.apply(null,nums):0)+1;
  return "V"+String(next).padStart(2,"0")+"-"+customerId;
};
const genJobId=(vehicleId,allJobs)=>{
  // Same principle as genVehicleId: derive the next number from the highest one seen,
  // not from how many are currently active, so archived jobs can't be overwritten.
  var nums=allJobs.filter(function(j){return j.vehicleId===vehicleId;}).map(function(j){var m=/^J(\d+)-/.exec(j.jobId||"");return m?parseInt(m[1],10):0;});
  var next=(nums.length?Math.max.apply(null,nums):0)+1;
  return "J"+String(next).padStart(3,"0")+"-"+vehicleId;
};

