const modelsForMakeType=function(make,t){
  var auto=AUTO_MODELS[make];
  if((t==="Car"||t==="Truck"||t==="SUV"||t==="Van")&&auto)return auto;
  return [];
};
const svcWarranty=function(name){
  var n=(name||"").toLowerCase();
  if(n.indexOf("oil")>=0)return{dur:"90 days / 3,000 miles",term:"This shop warrants all labor associated with this service for a period of 90 days or 3,000 miles, whichever occurs first, against defects in workmanship."};
  if(n.indexOf("brake")>=0||n.indexOf("pad")>=0||n.indexOf("rotor")>=0)return{dur:"12 months / 12,000 miles",term:"This shop warrants all labor associated with brake service for 12 months or 12,000 miles, whichever occurs first. Warranty is void if the vehicle is used in racing, off-road, or other extreme-duty applications."};
  if(n.indexOf("align")>=0)return{dur:"6 months / 6,000 miles",term:"Labor and alignment specifications are warranted for 6 months or 6,000 miles, provided no subsequent suspension impact or modification has occurred."};
  if(n.indexOf("tune")>=0||n.indexOf("spark")>=0||n.indexOf("plug")>=0)return{dur:"6 months / 6,000 miles",term:"Labor is warranted for 6 months or 6,000 miles against improper installation. Performance outcomes are dependent on overall engine condition."};
  if(n.indexOf("battery")>=0)return{dur:"30 days",term:"Installation labor is warranted for 30 days. Battery performance is subject to manufacturer warranty only."};
  if(n.indexOf("rotation")>=0||n.indexOf("tire")>=0)return{dur:"30 days",term:"Labor is warranted for 30 days. Tread wear, sidewall damage, and tire integrity are subject to manufacturer warranty only."};
  if(n.indexOf("coolant")>=0||n.indexOf("flush")>=0)return{dur:"6 months / 6,000 miles",term:"Labor is warranted for 6 months or 6,000 miles. Warranty is void if overheating occurs due to pre-existing conditions not disclosed prior to service."};
  if(n.indexOf("transmission")>=0)return{dur:"12 months / 12,000 miles",term:"Labor is warranted for 12 months or 12,000 miles against workmanship defects. Warranty is void if the vehicle is operated while fluid levels are knowingly depleted."};
  if(n.indexOf("filter")>=0)return{dur:"30 days",term:"Labor is warranted for 30 days against improper installation."};
  if(n.indexOf("diagnos")>=0)return{dur:"30 days",term:"Diagnostic labor is warranted for 30 days with respect to accuracy of fault identification at time of service. Subsequent or unrelated faults are not covered."};
  return{dur:"90 days / 3,000 miles",term:"All labor is warranted against defects in workmanship for 90 days or 3,000 miles, whichever occurs first."};
};
const SHOP_WARRANTY_FOOTER="This warranty applies solely to the labor and workmanship performed by this shop on the date of service. It does not cover parts, consumables, pre-existing conditions, damage caused by misuse, neglect, accidents, unauthorized repairs, acts of nature, or normal wear and tear. This warranty is non-transferable and applies only to the original vehicle owner. To make a warranty claim, the vehicle must be returned to this shop for inspection. We reserve the right to inspect and verify the defect prior to performing any warranty repair. This warranty gives you specific legal rights; you may also have other rights that vary by jurisdiction.";
const REMIND_RULES=[
  {key:"oil",days:90,label:"Oil Change due"},
  {key:"rotation",days:180,label:"Tire Rotation due"},
  {key:"brake",days:365,label:"Brake Inspection recommended"},
  {key:"coolant",days:365,label:"Coolant Service check"},
  {key:"align",days:365,label:"Alignment check recommended"},
];
const fmtDT=function(iso){if(!iso)return"";var d=new Date(iso);return d.toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"})+" "+d.toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit"});};
const genInvId=function(custId,invoices){var n=invoices.length+1;return"INV-"+String(n).padStart(3,"0")+"-"+dispCustId(custId);};
const genEstId=function(custId,estimates){var n=estimates.length+1;return"EST-"+String(n).padStart(3,"0")+"-"+dispCustId(custId);};
const genWarId=function(invId,idx){return"W"+String(idx+1).padStart(2,"0")+"-"+invId;};
const invTotals=function(inv){
  var lab=(inv.laborItems||[]).reduce(function(s,li){return s+li.hours*li.rate;},0);
  var parts=(inv.partItems||[]).reduce(function(s,p){return s+p.qty*p.sell;},0);
  var tax=parts*(inv.taxRate||0.075);
  var paid=(inv.payments||[]).reduce(function(s,p){return s+p.amount;},0);
  var total=lab+parts+tax;
  return{lab:lab,parts:parts,tax:tax,total:total,paid:paid,due:total-paid};
};

const calcJob=job=>{const labRev=(job.services||[]).reduce((s,v)=>s+v.laborHours*v.laborRate,0);const partsRev=(job.parts||[]).reduce((s,p)=>s+p.qty*p.sell,0);const partsCost=(job.parts||[]).reduce((s,p)=>s+p.qty*p.cost,0);const total=labRev+partsRev;return{labRev,partsRev,partsCost,total,profit:total-partsCost};};
const sColor=s=>({completed:"var(--grn)","in-progress":"var(--acc)",upcoming:"var(--blu)"}[s]||"var(--txt2)");
const sLabel=s=>({completed:"Done","in-progress":"⚙ In Progress",upcoming:"◷ Upcoming"}[s]||s);
const srcIcon=s=>({call:"📞",email:"📧",manual:"✏️"}[s]||"✏️");

/* ── UI PRIMITIVES ──────────────────────────────────────────────────────── */
const Chip=({label,color="var(--txt3)",small=false})=>(
  <span style={{display:"inline-block",padding:small?"1px 7px":"3px 10px",borderRadius:20,fontSize:small?10:12,fontFamily:"var(--fd)",fontWeight:700,letterSpacing:".06em",background:`${color}18`,color,border:`1px solid ${color}44`}}>{label}</span>
);
const Btn=({children,onClick,v="ghost",sz="md",full=false,style:sx={},disabled=false,...p})=>{
  const base={fontFamily:"var(--fd)",fontWeight:800,letterSpacing:".07em",borderRadius:"var(--r)",cursor:disabled?"not-allowed":"pointer",border:"none",transition:"all .15s",opacity:disabled?0.5:1,display:"inline-flex",alignItems:"center",gap:5};
  const sizes={sm:{padding:"4px 11px",fontSize:12},md:{padding:"7px 16px",fontSize:13},lg:{padding:"10px 22px",fontSize:15}};
  const variants={primary:{background:"var(--acc)",color:"#fff"},danger:{background:"var(--red)",color:"#fff"},ghost:{background:"transparent",color:"var(--txt2)",border:"1px solid var(--bdr)"},outline:{background:"transparent",color:"var(--acc)",border:"1px solid var(--acc)"},subtle:{background:"var(--s3)",color:"var(--txt2)",border:"1px solid var(--bdr)"},archive:{background:"transparent",color:"var(--txt3)",border:"1px solid var(--bdr2)"},ai:{background:"linear-gradient(135deg,var(--pur),var(--blu))",color:"#fff"}};
  return <button disabled={disabled} style={{...base,...sizes[sz],...variants[v||"ghost"],width:full?"100%":"auto",...sx}} onClick={onClick} {...p}>{children}</button>;
};
const Card=({children,style:sx={}})=>(<div style={{background:"var(--s2)",border:"1px solid var(--bdr)",borderRadius:"var(--r2)",padding:"16px 18px",...sx}}>{children}</div>);
const Lbl=({children,required=false})=>(<div style={{fontSize:10,fontFamily:"var(--fd)",fontWeight:700,letterSpacing:".1em",textTransform:"uppercase",color:"var(--txt3)",marginBottom:4}}>{children}{required&&<span style={{color:"var(--red)",marginLeft:2}}>*</span>}</div>);
const Divider=({m="12px 0"})=><div style={{height:1,background:"var(--bdr)",margin:m}}/>;
const FG=({label,children,required=false,span=1,err=null})=>(<div style={{gridColumn:`span ${span}`}}><Lbl required={required}>{label}</Lbl>{children}{err&&<div className="err-msg">⚠ {err}</div>}</div>);
const Modal=({title,subtitle,onClose,children,wide=false,maxW=620})=>{
  useEffect(function(){
    var h=function(e){if(e.key==="Escape")onClose();};
    window.addEventListener("keydown",h);
    return function(){window.removeEventListener("keydown",h);};
  },[onClose]);
  return(
  <div style={{position:"fixed",inset:0,background:"#000b",zIndex:1000,display:"flex",alignItems:"flex-start",justifyContent:"center",padding:"12px 8px",overflowY:"auto"}} onClick={e=>{if(e.target===e.currentTarget)onClose()}}>
    <div className="pop" role="dialog" aria-modal="true" style={{background:"var(--s1)",border:"1px solid var(--bdr)",borderRadius:14,width:"100%",maxWidth:wide?920:maxW,padding:"22px 24px",marginTop:8,boxShadow:"0 24px 80px #000c"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:18}}>
        <div><div style={{fontFamily:"var(--fd)",fontSize:20,fontWeight:900}}>{title}</div>{subtitle&&<div style={{fontSize:12,color:"var(--txt3)",marginTop:2}}>{subtitle}</div>}</div>
        <button onClick={onClose} aria-label="Close" title="Close (Esc)" style={{background:"none",border:"none",color:"var(--txt3)",fontSize:16,cursor:"pointer",marginLeft:16,padding:"4px 10px",borderRadius:8}}>{"\u2715"}</button>
      </div>
      {children}
    </div>
  </div>
  );
};
const AccordionSection=({title,defaultOpen=false,children,badge=null,accent=false})=>{
  const[open,setOpen]=useState(defaultOpen);
  return(
    <div style={{border:`1px solid ${accent?"var(--acc)33":"var(--bdr)"}`,borderRadius:"var(--r2)",marginBottom:8,overflow:"hidden"}}>
      <button onClick={()=>setOpen(o=>!o)} style={{width:"100%",display:"flex",justifyContent:"space-between",alignItems:"center",padding:"11px 16px",background:open?"var(--s3)":"var(--s2)",border:"none",cursor:"pointer",textAlign:"left"}}>
        <span style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:800,letterSpacing:".04em",color:accent?"var(--acc)":"var(--txt)"}}>{title}</span>
        <span style={{display:"flex",gap:8,alignItems:"center"}}>
          {badge&&<span style={{background:"var(--s4)",color:"var(--txt3)",fontSize:11,fontFamily:"var(--fm)",padding:"1px 7px",borderRadius:8}}>{badge}</span>}
          <span style={{color:"var(--txt3)",fontSize:12,transition:".2s",transform:open?"rotate(180deg)":"none",display:"inline-block"}}>▼</span>
        </span>
      </button>
      {open&&<div style={{padding:"14px 16px",background:"var(--s2)",borderTop:"1px solid var(--bdr)"}} className="fade">{children}</div>}
    </div>
  );
};

