const HexAvatar=({src,name,size=80,glow=true})=>{
  const ini=(name||"M")[0].toUpperCase();
  return(
    <div className={glow?"hex-glow":""} style={{width:size,height:size,flexShrink:0,position:"relative"}}>
      <div style={{position:"absolute",inset:0,clipPath:"polygon(50% 0%,100% 25%,100% 75%,50% 100%,0% 75%,0% 25%)",background:"linear-gradient(145deg,#8a9aaa 0%,#4a5568 18%,#2d3748 40%,#1a2332 55%,#2d3a4a 72%,#5a6a7a 88%,#7c8a98 100%)"}}/>
      <div style={{position:"absolute",inset:"8%",clipPath:"polygon(50% 0%,100% 25%,100% 75%,50% 100%,0% 75%,0% 25%)",background:"linear-gradient(145deg,#1e2a36,#263342,#1a2230)"}}/>
      <div style={{position:"absolute",width:"58%",height:"58%",top:"50%",left:"50%",transform:"translate(-50%,-50%)",borderRadius:"50%",overflow:"hidden",background:src?"transparent":"var(--acc)",display:"flex",alignItems:"center",justifyContent:"center",boxShadow:"inset 0 2px 8px #0009,0 0 0 1.5px #ffffff18"}}>
        {src?<img src={src} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}/>:<span style={{fontFamily:"var(--fd)",fontWeight:900,fontSize:size*0.22,color:"#fff",lineHeight:1}}>{ini}</span>}
      </div>
    </div>
  );
};

const HexSpinner=({size=36,label=""})=>(
  <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:8}}>
    <div className="hex-spin" style={{width:size,height:size,position:"relative"}}>
      <div style={{position:"absolute",inset:0,clipPath:"polygon(50% 0%,100% 25%,100% 75%,50% 100%,0% 75%,0% 25%)",background:"linear-gradient(145deg,#8a9aaa,#4a5568,#2d3748,#1a2332,#2d3a4a,#7c8a98)"}}/>
      <div style={{position:"absolute",inset:"8%",clipPath:"polygon(50% 0%,100% 25%,100% 75%,50% 100%,0% 75%,0% 25%)",background:"linear-gradient(145deg,#1e2a36,#263342)"}}/>
      <div style={{position:"absolute",width:"50%",height:"50%",top:"50%",left:"50%",transform:"translate(-50%,-50%)",borderRadius:"50%",background:"var(--acc)",boxShadow:"0 0 8px var(--acc)"}}/>
    </div>
    {label&&<div style={{fontSize:11,color:"var(--txt3)",fontFamily:"var(--fd)",fontWeight:700,letterSpacing:".08em"}}>{label}</div>}
  </div>
);
