/* ══════════════════════════════════════════════════════════════════════════
   AI REPAIR PLANNER MODAL
══════════════════════════════════════════════════════════════════════════ */
const AIRepairPlannerModal=({onClose,onApply,vehicles,customers})=>{
  const[desc,setDesc]=useState("");
  const[selCustId,setSelCustId]=useState("");
  const[selVehId,setSelVehId]=useState("");
  const[loading,setLoading]=useState(false);
  const[result,setResult]=useState(null);
  const[err,setErr]=useState("");
  const custVehs=vehicles.filter(v=>v.customerId===selCustId);
  const selVeh=vehicles.find(v=>v.id===selVehId);
  const generate=async()=>{
    if(!desc.trim())return;
    setLoading(true);setErr("");setResult(null);
    var apiKey="";try{if(typeof window!=="undefined"&&window.MM_ANTHROPIC_KEY)apiKey=window.MM_ANTHROPIC_KEY;}catch(eK){}
    var hdrs={"Content-Type":"application/json"};
    if(apiKey){hdrs["x-api-key"]=apiKey;hdrs["anthropic-version"]="2023-06-01";hdrs["anthropic-dangerous-direct-browser-access"]="true";}
    try{
      const vInfo=selVeh?`\nVehicle: ${selVeh.year} ${selVeh.make} ${selVeh.model}${selVeh.engine?" ("+selVeh.engine+")":""}. Fuel: ${selVeh.fuelType||"unknown"}. Drive: ${selVeh.driveType||"unknown"}.`:"";
      const resp=await fetch("https://api.anthropic.com/v1/messages",{
        method:"POST",
        headers:hdrs,
        body:JSON.stringify({
          model:"claude-sonnet-4-20250514",
          max_tokens:1500,
          system:`You are an expert mobile automotive mechanic assistant with 20+ years of experience. Generate detailed repair plans as structured JSON only. No markdown, no preamble, no explanation outside the JSON. Return ONLY valid JSON.\n\nAlways include:\n1. Services listed in the correct ORDER OF OPERATIONS (e.g., diagnose first, then disassemble, then replace parts, then reassemble, then test)\n2. Realistic labor hours for a single mobile mechanic\n3. All parts typically needed with part numbers where known\n4. A notes field with important warnings, technical tips, or sequencing advice`,
          messages:[{role:"user",content:`Repair description: "${desc}"${vInfo}\n\nGenerate a JSON repair plan in this exact format:\n{\n  "templateName": "brief professional name",\n  "category": "repair category",\n  "orderOfOperations": ["Step 1: ...", "Step 2: ...", "Step 3: ..."],\n  "services": [{"name": "service name", "laborHours": 1.0, "laborRate": 95, "order": 1}],\n  "parts": [{"name": "part name", "partNumber": "PN if known", "qty": 1, "cost": 0, "sell": 0}],\n  "notes": "important technical notes, warnings, sequencing tips"\n}\n\nOrder services by logical repair sequence. Be specific and use real part numbers when possible.`}]
        })
      });
      const data=await resp.json();
      if(data.error){setErr("API Error: "+data.error.message);setLoading(false);return;}
      const blocks=data.content||[];
      const raw=blocks.filter(function(c){return c.type==="text";}).map(function(c){return c.text;}).join("");
      const start=raw.indexOf("{");
      const end=raw.lastIndexOf("}");
      const jsonStr=start>=0&&end>start?raw.slice(start,end+1):raw;
      const parsed=JSON.parse(jsonStr);
      setResult(parsed);
    }catch(e){var hint=apiKey?"":"  Tip: if you are running the downloaded app on your own device, add an Anthropic API key in Settings to enable the AI planner.";setErr("Could not generate plan. "+e.message+hint);}
    setLoading(false);
  };
  return(
    <Modal title="AI REPAIR PLANNER" subtitle="Describe the repair in plain language — AI drafts a plan for your review" onClose={onClose} wide maxW={640}>
      <div style={{padding:"8px 12px",background:"var(--ylw)10",border:"1px solid var(--ylw)33",borderRadius:"var(--r2)",marginBottom:12,fontSize:11,color:"var(--txt2)",lineHeight:1.5}}><span style={{color:"var(--ylw)",fontFamily:"var(--fd)",fontWeight:800}}>DRAFT ONLY {"\u2014"} </span>AI plans can be wrong or incomplete. Verify every part, procedure, and spec before any work {"\u2014"} you remain fully responsible for all repairs and figures presented to clients.</div>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginBottom:14}}>
        <FG label="Client (optional)">
          <select value={selCustId} onChange={e=>{setSelCustId(e.target.value);setSelVehId("");}}>
            <option value="">— Select client —</option>
            {customers.map(c=><option key={dispCustId(c.id)} value={dispCustId(c.id)}>{fullName(c)}</option>)}
          </select>
        </FG>
        <FG label="Vehicle (optional)">
          <select value={selVehId} onChange={e=>setSelVehId(e.target.value)} disabled={!selCustId}>
            <option value="">— Select vehicle —</option>
            {custVehs.map(v=><option key={v.id} value={v.id}>{v.year} {v.make} {v.model}</option>)}
          </select>
        </FG>
      </div>
      <FG label="Describe the repair in plain language">
        <textarea value={desc} onChange={e=>setDesc(e.target.value)} placeholder="e.g. broken manifold stud needs repair, both front wheel bearings, oil change, rear differential service..." style={{minHeight:100,fontSize:14}}/>
      </FG>
      <div style={{marginTop:12,marginBottom:16}}>
        <Btn v="ai" sz="lg" full disabled={!desc.trim()||loading} onClick={generate}>
          {loading?"Generating Repair Plan...":"Generate Repair Plan with AI"}
        </Btn>
      </div>
      {loading&&<div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:12,padding:"20px 0"}}><HexSpinner size={48} label="ANALYZING REPAIR…"/></div>}
      {err&&<div style={{padding:"10px 14px",background:"var(--red)18",border:"1px solid var(--red)44",borderRadius:"var(--r)",fontSize:13,color:"var(--red)",marginBottom:12}}>{err}</div>}
      {result&&<div className="fade">
        <Divider/>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
          <div>
            <div style={{fontFamily:"var(--fd)",fontSize:16,fontWeight:900,color:"var(--acc)"}}>{result.templateName}</div>
            {result.category&&<div style={{fontSize:11,color:"var(--txt3)",marginTop:2}}>{result.category}</div>}
          </div>
          <Btn v="primary" onClick={()=>{onApply(result);onClose();}}>Use This Plan &gt;</Btn>
        </div>
        {/* Order of Operations */}
        {(result.orderOfOperations||[]).length>0&&<div style={{marginBottom:14,padding:"10px 14px",background:"var(--blu)0e",border:"1px solid var(--blu)44",borderRadius:"var(--r2)"}}>
          <div style={{fontFamily:"var(--fd)",fontSize:11,fontWeight:800,color:"var(--blu)",letterSpacing:".1em",marginBottom:8}}>ORDER OF OPERATIONS</div>
          {result.orderOfOperations.map((step,i)=>(
            <div key={i} style={{display:"flex",gap:10,alignItems:"flex-start",marginBottom:5,fontSize:12}}>
              <span style={{background:"var(--blu)",color:"#fff",borderRadius:"50%",width:18,height:18,display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:10,fontWeight:900,flexShrink:0,fontFamily:"var(--fd)"}}>{i+1}</span>
              <span style={{color:"var(--txt2)",lineHeight:1.5}}>{step.split(":").slice(1).join(":").trim()||step}</span>
            </div>
          ))}
        </div>}
        {result.notes&&<div style={{padding:"8px 12px",background:"var(--ylw)14",border:"1px solid var(--ylw)33",borderRadius:"var(--r)",fontSize:12,color:"var(--ylw)",marginBottom:12,borderLeft:"3px solid var(--ylw)"}}>{result.notes}</div>}
        <div style={{marginBottom:10}}>
          <div style={{fontFamily:"var(--fd)",fontSize:12,fontWeight:800,color:"var(--txt3)",letterSpacing:".1em",marginBottom:7}}>SERVICES</div>
          {(result.services||[]).sort((a,b)=>(a.order||0)-(b.order||0)).map((s,i)=>(
            <div key={i} style={{display:"flex",justifyContent:"space-between",padding:"7px 12px",background:"var(--s3)",borderRadius:"var(--r)",marginBottom:5,fontSize:13}}>
              <span>{s.name}</span>
              <span className="mono" style={{color:"var(--txt3)"}}>{s.laborHours}h @ {fmt$(s.laborRate)}/hr = <span style={{color:"var(--acc)",fontWeight:700}}>{fmt$(s.laborHours*s.laborRate)}</span></span>
            </div>
          ))}
        </div>
        {(result.parts||[]).length>0&&<div>
          <div style={{fontFamily:"var(--fd)",fontSize:12,fontWeight:800,color:"var(--txt3)",letterSpacing:".1em",marginBottom:7}}>PARTS</div>
          {result.parts.map((p,i)=>(
            <div key={i} style={{display:"flex",justifyContent:"space-between",padding:"7px 12px",background:"var(--s3)",borderRadius:"var(--r)",marginBottom:5,fontSize:13}}>
              <span>{p.name} {p.partNumber&&<span className="mono" style={{color:"var(--txt3)",fontSize:11}}>({p.partNumber})</span>}</span>
              <span className="mono" style={{color:"var(--txt3)"}}>qty {p.qty}</span>
            </div>
          ))}
        </div>}
      </div>}
    </Modal>
  );
};

/* ══════════════════════════════════════════════════════════════════════════
   VEHICLE REPORT PAGE
══════════════════════════════════════════════════════════════════════════ */
const VehicleReport=({vehicle,jobs,onBack,onSelectJob,onNewJob})=>{
  const vtc=VT[vehicle.type]||VT.Car;
  const vJobs=[...jobs.filter(j=>j.vehicleId===vehicle.id)].sort((a,b)=>b.scheduledDate>a.scheduledDate?1:-1);
  const totalRev=vJobs.reduce((s,j)=>s+calcJob(j).total,0);
  const totalProfit=vJobs.reduce((s,j)=>s+calcJob(j).profit,0);
  const totalHrs=vJobs.reduce((s,j)=>s+(j.services||[]).reduce((a,sv)=>a+sv.laborHours,0),0);
  const allServices=vJobs.flatMap(j=>(j.services||[]).map(s=>s.name));
  const svcFreq=allServices.reduce((m,s)=>{m[s]=(m[s]||0)+1;return m;},{});
  const topSvcs=Object.entries(svcFreq).sort((a,b)=>b[1]-a[1]).slice(0,4);
  return(
    <div className="fade" style={{paddingBottom:40}}>
      <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:16}}>
        <Btn v="ghost" sz="sm" onClick={onBack}>« Back</Btn>
        <span style={{color:"var(--txt3)",fontSize:12}}>Vehicle Report</span>
      </div>
      {/* Header */}
      <div style={{background:"var(--s2)",border:"1px solid var(--bdr)",borderRadius:12,overflow:"hidden",marginBottom:14}}>
        <div style={{height:3,background:`linear-gradient(90deg,${vtc.color},transparent)`}}/>
        <div style={{padding:"18px 20px"}}>
          <div style={{display:"flex",gap:12,alignItems:"flex-start",flexWrap:"wrap",justifyContent:"space-between"}}>
            <div>
              <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:8}}>
                <span style={{fontSize:28}}>{vtc.icon}</span>
                <div>
                  <div style={{fontFamily:"var(--fd)",fontSize:26,fontWeight:900,lineHeight:1}}>{vehicle.year} <span style={{color:vtc.color}}>{vehicle.make}</span> {vehicle.model}</div>
                  <div style={{display:"flex",gap:8,marginTop:4,flexWrap:"wrap"}}>
                    <Chip label={vehicle.type} color={vtc.color} small/>
                    {vehicle.vehicleId&&<span className="mono" style={{fontSize:10,color:"var(--acc)"}}>{dispVehId(vehicle.vehicleId)}</span>}
                  </div>
                </div>
              </div>
              <div style={{fontSize:12,color:"var(--txt2)",display:"flex",flexDirection:"column",gap:3}}>
                {vehicle.engine&&<span>⚙️ {vehicle.engine}</span>}
                {vehicle.driveType&&<span>🔄 {vehicle.driveType}</span>}
                {vehicle.fuelType&&<span>⛽ {vehicle.fuelType}</span>}
                {vehicle.vin&&<span className="mono" style={{fontSize:10,color:"var(--txt3)"}}>{vtc.idLabel}: {vehicle.vin}</span>}
                {vehicle.plate&&<span>🪪 {vehicle.plate}</span>}
              </div>
            </div>
            <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
              {[["Total Revenue",fmt$(totalRev),"var(--grn)"],["Net Profit",fmt$(totalProfit),totalProfit>=0?"var(--grn)":"var(--red)"],["Labor Hours",totalHrs.toFixed(1)+"h","var(--acc)"],["Service Records",vJobs.length,"var(--blu)"]].map(([l,v,c])=>(
                <div key={l} style={{background:"var(--s3)",border:"1px solid var(--bdr)",borderRadius:"var(--r2)",padding:"10px 14px",minWidth:88,textAlign:"center"}}>
                  <div style={{fontSize:9,fontFamily:"var(--fd)",fontWeight:700,letterSpacing:".1em",color:"var(--txt3)",textTransform:"uppercase",marginBottom:3}}>{l}</div>
                  <div className="mono" style={{fontSize:17,fontWeight:700,color:c}}>{v}</div>
                </div>
              ))}
            </div>
          </div>
          {topSvcs.length>0&&<div style={{marginTop:12,display:"flex",gap:6,flexWrap:"wrap"}}>
            <span style={{fontSize:11,color:"var(--txt3)",fontFamily:"var(--fd)",fontWeight:700,marginRight:4}}>TOP SERVICES:</span>
            {topSvcs.map(([s,n])=><Chip key={s} label={`${s} ×${n}`} color="var(--cyn)" small/>)}
          </div>}
        </div>
      </div>
      {/* Log Job shortcut */}
      <div style={{display:"flex",justifyContent:"flex-end",marginBottom:12}}>
        <Btn v="primary" onClick={onNewJob}>+ Log Job for This Vehicle</Btn>
      </div>
      {/* Chronological jobs */}
      <Card>
        <div style={{fontFamily:"var(--fd)",fontSize:15,fontWeight:900,marginBottom:14}}>CHRONOLOGICAL SERVICE RECORD ({vJobs.length})</div>
        {vJobs.length===0&&<div style={{color:"var(--txt3)",fontSize:13,padding:"12px 0",textAlign:"center"}}>No service records for this vehicle yet.</div>}
        {vJobs.map((j,idx)=>{
          const{labRev,partsRev,total,profit}=calcJob(j);
          return(
            <div key={j.id} onClick={()=>onSelectJob(j.id)}
              style={{display:"flex",gap:12,alignItems:"flex-start",padding:"14px 16px",background:"var(--s3)",borderRadius:"var(--r2)",marginBottom:8,cursor:"pointer",border:"1px solid var(--bdr)",position:"relative"}}
              onMouseEnter={e=>{e.currentTarget.style.borderColor="var(--acc)44";e.currentTarget.style.background="var(--s4)"}}
              onMouseLeave={e=>{e.currentTarget.style.borderColor="var(--bdr)";e.currentTarget.style.background="var(--s3)"}}>
              <div style={{fontFamily:"var(--fm)",fontSize:13,fontWeight:700,color:"var(--acc)",minWidth:30,textAlign:"center",paddingTop:2}}>#{vJobs.length-idx}</div>
              <div style={{flex:1}}>
                <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:5,flexWrap:"wrap"}}>
                  <Chip label={sLabel(j.status)} color={sColor(j.status)} small/>
                  <span className="mono" style={{fontSize:10,color:"var(--txt3)"}}>{fmtD(j.scheduledDate)} {fmtT(j.scheduledTime)}</span>
                  {j.jobId&&<span className="mono" style={{fontSize:9,color:"var(--txt3)"}}>{dispJobId(j.jobId)}</span>}
                </div>
                <div style={{fontSize:13,fontWeight:500,marginBottom:4}}>{(j.services||[]).map(s=>s.name).join(" · ")||"No services"}</div>
                {(j.notes&&j.notes.length)>0&&<div style={{fontSize:11,color:"var(--ylw)"}}>📝 {j.notes.length} note{j.notes.length!==1?"s":""}</div>}
                {/* Photos thumbnails */}
                {(j.photos&&j.photos.length)>0&&<div style={{display:"flex",gap:6,marginTop:6}}>
                  {j.photos.slice(0,3).map(p=><img key={p.id} src={p.url} alt="" className="photo-thumb" style={{width:48,height:48}}/>)}
                  {j.photos.length>3&&<div style={{width:48,height:48,background:"var(--s4)",borderRadius:"var(--r)",border:"1px solid var(--bdr)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:11,color:"var(--txt3)",fontFamily:"var(--fd)",fontWeight:700}}>+{j.photos.length-3}</div>}
                </div>}
              </div>
              <div style={{textAlign:"right",flexShrink:0}}>
                <div className="mono acc" style={{fontSize:14,fontWeight:700}}>{fmt$(total)}</div>
                <div className="mono" style={{fontSize:11,color:profit>=0?"var(--grn)":"var(--red)"}}>{fmt$(profit)}</div>
              </div>
            </div>
          );
        })}
      </Card>
    </div>
  );
};

/* ══════════════════════════════════════════════════════════════════════════
   JOB DETAIL
══════════════════════════════════════════════════════════════════════════ */
const JobDetail=({job,customers,vehicles,onBack,onUpdate,onArchive,onCreateInvoice,hasInvoice,settings={}})=>{
  const[j,setJ]=useState({...job});
  const save=patch=>{const updated={...j,...patch};setJ(updated);onUpdate(updated);};
  const set=k=>e=>save({[k]:e.target.value});
  const c=customers.find(x=>x.id===j.customerId)||{};
  const v=vehicles.find(x=>x.id===j.vehicleId)||{};
  const vtc=VT[v.type]||VT.Car;
  const{labRev,partsRev,partsCost,total,profit}=calcJob(j);
  const setSvc=(id,k,val)=>save({services:j.services.map(s=>s.id===id?{...s,[k]:k==="laborHours"||k==="laborRate"?+val:val}:s)});
  const delSvc=id=>save({services:j.services.filter(s=>s.id!==id)});
  const addSvc=()=>save({services:[...(j.services||[]),{id:uid(),name:"New Service",laborHours:1,laborRate:+settings.laborRate||95}]});
  const setPrt=(id,k,val)=>save({parts:j.parts.map(p=>p.id===id?{...p,[k]:k==="qty"||k==="cost"||k==="sell"?+val:val}:p)});
  const delPrt=id=>save({parts:j.parts.filter(p=>p.id!==id)});
  const addPrt=()=>save({parts:[...(j.parts||[]),{id:uid(),name:"New Part",partNumber:"",qty:1,cost:0,sell:0}]});
  const[note,setNote]=useState("");
  const addNote=()=>{if(!note.trim())return;save({notes:[...(j.notes||[]),{id:uid(),text:note.trim(),ts:new Date().toISOString()}]});setNote("");};
  const EF=({label,value,onChange,type="text",opts=null,mono=false})=>(<div style={{marginBottom:10}}><Lbl>{label}</Lbl>{opts?<select value={value} onChange={onChange}><option value="">—</option>{opts.map(o=><option key={o} value={o}>{o}</option>)}</select>:<input type={type} value={value||""} onChange={onChange} style={{fontSize:13,fontFamily:mono?"var(--fm)":"var(--fb)"}}/> }</div>);
  return(
    <div className="fade" style={{paddingBottom:80}}>
      <div style={{background:"var(--s2)",border:"1px solid var(--bdr)",borderRadius:12,overflow:"hidden",marginBottom:14}}>
        <div style={{height:3,background:`linear-gradient(90deg,${vtc.color},transparent)`}}/>
        <div style={{padding:"14px 16px"}}>
          <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:10}}>
            <Btn v="ghost" sz="sm" onClick={onBack}>« Back</Btn>
            <Chip label={sLabel(j.status)} color={sColor(j.status)}/>
            <div style={{flex:1}}/>
            <span className="mono" style={{fontSize:10,color:"var(--acc)",background:"var(--acc)14",border:"1px solid var(--acc)44",padding:"2px 9px",borderRadius:5,fontWeight:700}}>{dispCustId(c.id)}</span>
            {j.jobId&&<span className="mono" style={{fontSize:10,color:"var(--txt3)",background:"var(--s3)",border:"1px solid var(--bdr)",padding:"2px 9px",borderRadius:5}}>{dispJobId(j.jobId)}</span>}
          </div>
          <div style={{display:"flex",gap:10,alignItems:"center"}}>
            <span style={{fontSize:26,flexShrink:0}}>{vtc.icon}</span>
            <div>
              <div style={{fontFamily:"var(--fd)",fontSize:22,fontWeight:900,lineHeight:1.1}}>{v.year} <span style={{color:vtc.color}}>{v.make}</span> {v.model}</div>
              <div style={{fontSize:13,color:"var(--txt2)",marginTop:3,display:"flex",gap:12,alignItems:"center",flexWrap:"wrap"}}>
                <span style={{fontFamily:"var(--fd)",fontWeight:700,fontSize:14}}>{fullName(c)}</span>
                {c.phone&&<span className="mono" style={{fontSize:12,color:"var(--txt3)"}}>{c.phone}</span>}
                <Chip label={v.type||"—"} color={vtc.color} small/>
              </div>
            </div>
          </div>
        </div>
      </div>
      <AccordionSection title="📅 SCHEDULE & STATUS" defaultOpen>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
          <EF label="Service Date" value={j.scheduledDate} onChange={set("scheduledDate")} type="date"/>
          <EF label="Odometer (mi)" value={j.odometer||""} onChange={set("odometer")} type="number" min="0"/>
          <EF label="Scheduled Time" value={j.scheduledTime} onChange={set("scheduledTime")} type="time"/>
          <EF label="Job Status" value={j.status} onChange={set("status")} opts={["upcoming","in-progress","completed"]}/>
          <EF label="Logged Via" value={j.loggedVia} onChange={set("loggedVia")} opts={["manual","call","email"]}/>
          <div style={{gridColumn:"span 2"}}><EF label="Job Location / Address" value={j.location} onChange={set("location")}/></div>
        </div>
      </AccordionSection>
      <AccordionSection title="⚙ SERVICES RENDERED" defaultOpen badge={`${(j.services&&j.services.length)||0} · ${fmt$(labRev)}`}>
        {(j.services||[]).map(s=>(
          <div key={s.id} style={{display:"grid",gridTemplateColumns:"3fr 1fr 1fr auto",gap:8,marginBottom:8,padding:"10px 12px",background:"var(--s3)",borderRadius:"var(--r)"}}>
            <div><Lbl>Service Name</Lbl><input value={s.name} onChange={e=>setSvc(s.id,"name",e.target.value)} style={{fontSize:12}}/></div>
            <div><Lbl>Hrs</Lbl><input type="number" value={s.laborHours} min="0" step=".25" onChange={e=>setSvc(s.id,"laborHours",e.target.value)} style={{fontSize:12}}/></div>
            <div><Lbl>$/hr</Lbl><input type="number" value={s.laborRate} min="0" onChange={e=>setSvc(s.id,"laborRate",e.target.value)} style={{fontSize:12}}/></div>
            <div style={{display:"flex",flexDirection:"column",justifyContent:"flex-end",paddingBottom:2}}>
              <div className="mono acc" style={{fontSize:12,textAlign:"right",marginBottom:4}}>{fmt$(s.laborHours*s.laborRate)}</div>
              <button aria-label="Remove" title="Remove" onClick={()=>delSvc(s.id)} style={{background:"none",border:"none",color:"var(--red)",cursor:"pointer",fontSize:14,padding:0}}>x</button>
            </div>
          </div>
        ))}
        <Btn v="outline" sz="sm" onClick={addSvc}>+ Add Service</Btn>
        {labRev>0&&<div className="mono acc" style={{fontSize:13,fontWeight:700,textAlign:"right",marginTop:8}}>Labor subtotal: {fmt$(labRev)}</div>}
      </AccordionSection>
      <AccordionSection title="🔩 PARTS USED" badge={`${(j.parts&&j.parts.length)||0} · ${fmt$(partsRev)}`}>
        {(j.parts||[]).map(p=>{const m=p.sell>0?((p.sell-p.cost)/p.sell*100).toFixed(0):0;return(
          <div key={p.id} style={{marginBottom:10,padding:"12px",background:"var(--s3)",borderRadius:"var(--r2)",position:"relative"}}>
            <button aria-label="Remove" title="Remove" onClick={()=>delPrt(p.id)} style={{position:"absolute",top:8,right:8,background:"none",border:"none",color:"var(--red)",cursor:"pointer",fontSize:14,padding:0}}>x</button>
            <div style={{marginBottom:8}}><Lbl>Part Name</Lbl><input value={p.name} onChange={e=>setPrt(p.id,"name",e.target.value)} style={{fontSize:12}}/></div>
            <div style={{marginBottom:8}}><Lbl>Part Number</Lbl><input value={p.partNumber||""} onChange={e=>setPrt(p.id,"partNumber",e.target.value)} style={{fontSize:11,fontFamily:"var(--fm)"}}/></div>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:8}}>
              <div><Lbl>Quantity</Lbl><input type="number" value={p.qty} min="1" onChange={e=>setPrt(p.id,"qty",e.target.value)} style={{fontSize:12}}/></div>
              <div><Lbl>Sell Price ($)</Lbl><div style={{position:"relative"}}><input type="number" value={p.sell} min="0" onChange={e=>setPrt(p.id,"sell",e.target.value)} style={{fontSize:12}}/><span className="mono" style={{position:"absolute",right:8,top:"50%",transform:"translateY(-50%)",fontSize:10,color:+m>35?"var(--grn)":"var(--ylw)",pointerEvents:"none"}}>{m}%</span></div></div>
            </div>
            <div style={{borderTop:"1px dashed var(--bdr)",paddingTop:8}}><Lbl>Shop Cost ($) — internal only · not shown on client invoice</Lbl><input type="number" value={p.cost} min="0" onChange={e=>setPrt(p.id,"cost",e.target.value)} style={{fontSize:12,borderColor:"var(--bdr2)",background:"var(--s4)"}}/></div>
          </div>
        );})}
        <Btn v="outline" sz="sm" onClick={addPrt}>+ Add Part</Btn>
      </AccordionSection>
      <AccordionSection title="💰 PROFIT & LOSS" accent defaultOpen>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:10}}>
          {[["Labor Revenue",labRev,"var(--grn)"],["Parts Revenue",partsRev,"var(--grn)"],["Parts Cost",-partsCost,"var(--red)"],["Total Invoice",total,"var(--acc)"]].map(([l,v2,c2])=>(<div key={l} style={{padding:"8px 12px",background:"var(--s3)",borderRadius:"var(--r)"}}><div style={{fontSize:10,fontFamily:"var(--fd)",fontWeight:700,letterSpacing:".1em",color:"var(--txt3)",textTransform:"uppercase",marginBottom:2}}>{l}</div><div className="mono" style={{fontSize:16,fontWeight:700,color:c2}}>{fmt$(v2)}</div></div>))}
        </div>
        <div style={{padding:"12px 16px",background:"var(--s3)",borderRadius:"var(--r2)",border:`1px solid ${profit>=0?"var(--grn)44":"var(--red)44"}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
          <span style={{fontFamily:"var(--fd)",fontSize:16,fontWeight:900}}>NET PROFIT</span>
          <span className="mono" style={{fontSize:24,fontWeight:700,color:profit>=0?"var(--grn)":"var(--red)"}}>{fmt$(profit)}</span>
        </div>
        <div style={{height:4,borderRadius:3,background:"var(--s4)",overflow:"hidden",marginTop:8}}><div style={{height:"100%",width:`${Math.min(100,Math.max(0,(profit/(total||1))*100))}%`,background:profit>=0?"var(--grn)":"var(--red)",transition:"width .6s"}}/></div>
        <div className="mono" style={{fontSize:10,color:"var(--txt3)",marginTop:4,textAlign:"right"}}>{total>0?(profit/total*100).toFixed(1):0}% margin</div>
      </AccordionSection>
      <AccordionSection title="👤 CLIENT & VEHICLE">
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
          <div><div style={{fontFamily:"var(--fd)",fontSize:13,fontWeight:800,marginBottom:6,color:"var(--txt3)",letterSpacing:".08em"}}>CLIENT</div><div style={{fontFamily:"var(--fd)",fontSize:16,fontWeight:800}}>{fullName(c)}</div><div className="mono" style={{fontSize:11,color:"var(--acc)",marginBottom:5}}>{dispCustId(c.id)}</div>{c.phone&&<div style={{fontSize:12,color:"var(--txt2)"}}>📱 {c.phone}</div>}{c.email&&<div style={{fontSize:12,color:"var(--txt2)"}}>📧 {c.email}</div>}</div>
          <div><div style={{display:"flex",gap:6,alignItems:"center",marginBottom:6}}><span style={{fontSize:18}}>{vtc.icon}</span><div style={{fontFamily:"var(--fd)",fontSize:13,fontWeight:800,color:"var(--txt3)"}}>VEHICLE</div><Chip label={v.type||"—"} color={vtc.color} small/></div><div style={{fontFamily:"var(--fd)",fontSize:15,fontWeight:800}}>{v.year} {v.make} {v.model}</div>{v.engine&&<div style={{fontSize:12,color:"var(--txt2)",marginTop:2}}>⚙️ {v.engine}</div>}{v.driveType&&<div style={{fontSize:12,color:"var(--txt2)"}}>🔄 {v.driveType}</div>}{v.fuelType&&<div style={{fontSize:12,color:"var(--txt2)"}}>⛽ {v.fuelType}</div>}</div>
        </div>
      </AccordionSection>
      {/* Photos accordion */}
      <AccordionSection title="📷 JOB PHOTOS" badge={`${(j.photos&&j.photos.length)||0}`}>
        {(j.photos||[]).length===0&&<div style={{color:"var(--txt3)",fontSize:13,marginBottom:10}}>No photos attached.</div>}
        <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:10}}>
          {(j.photos||[]).map(p=><img key={p.id} src={p.url} alt={p.name} className="photo-thumb"/>)}
        </div>
        {(j.photos||[]).length<5&&<div>
          <input type="file" accept="image/*" multiple id={`photo-jd-${j.id}`} style={{display:"none"}} onChange={e=>{const files=Array.from(e.target.files).slice(0,5-(j.photos||[]).length);files.forEach(file=>{const r=new FileReader();r.onload=ev=>save({photos:[...(j.photos||[]),{id:uid(),name:file.name,url:ev.target.result}]});r.readAsDataURL(file);});}}/>
          <label htmlFor={`photo-jd-${j.id}`} style={{cursor:"pointer"}}><Btn v="subtle" sz="sm" onClick={e=>e.preventDefault()}>+ Add Photos ({5-(j.photos||[]).length} remaining)</Btn></label>
        </div>}
      </AccordionSection>
      <AccordionSection title="📝 JOB NOTES" badge={`${(j.notes&&j.notes.length)||0}`}>
        {(j.notes||[]).length===0&&<div style={{color:"var(--txt3)",fontSize:13,marginBottom:10}}>No notes yet.</div>}
        {(j.notes||[]).map(n=>(<div key={n.id} style={{background:"var(--s3)",borderRadius:"var(--r)",padding:"9px 12px",marginBottom:7,borderLeft:"3px solid var(--ylw)"}}><div style={{fontSize:13,lineHeight:1.5}}>{n.text}</div><div className="mono" style={{fontSize:10,color:"var(--txt3)",marginTop:3}}>{new Date(n.ts).toLocaleString()}</div></div>))}
        <div style={{display:"flex",gap:7,marginTop:8}}><textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="Add timestamped note…" style={{flex:1,minHeight:52}}/><Btn v="primary" onClick={addNote} style={{alignSelf:"flex-end"}}>Add</Btn></div>
      </AccordionSection>
      <div className="floating-actions" style={{position:"fixed",zIndex:100}}>
        {j.location&&<Btn v="subtle" sz="sm" onClick={function(){window.open(mapsUrl(j.location),"_blank","noopener,noreferrer");}}>Navigate</Btn>}
        {onCreateInvoice&&!hasInvoice&&<Btn v="primary" sz="sm" onClick={()=>onCreateInvoice(j.id)}>Create Invoice</Btn>}
        {hasInvoice&&<span style={{fontSize:10,fontFamily:"var(--fd)",fontWeight:800,color:"var(--grn)",alignSelf:"center"}}>INVOICED</span>}
        <Btn v="archive" sz="sm" onClick={()=>{if(window.confirm("Archive this job?"))onArchive(j.id);}}>🗄 Archive Job</Btn>
      </div>
    </div>
  );
};

/* -- EDIT CLIENT MODAL (preserves stable client ID) -- */
const EditClientModal=function(props){
  var customer=props.customer, onClose=props.onClose, onSave=props.onSave;
  var init={firstName:customer.firstName||"",lastName:customer.lastName||"",street:customer.street||"",city:customer.city||"",state:customer.state||"",zip:customer.zip||"",phone:customer.phone||"",phoneType:customer.phoneType||"standard",email:customer.email||"",notes:customer.notes||""};
  var st=useState(init); var f=st[0], setF=st[1];
  var tt=useState({}); var touched=tt[0], setTouch=tt[1];
  var touch=function(k){setTouch(function(p){var n=Object.assign({},p);n[k]=true;return n;});};
  var set=function(k){return function(e){var v=e.target.value;if(k==="phone"&&f.phoneType==="standard")v=fmtPhone(v);setF(function(p){var n=Object.assign({},p);n[k]=v;return n;});};};
  var setPhoneType=function(t){setF(function(p){var n=Object.assign({},p);n.phoneType=t;return n;});};
  var emailErr=touched.email?validateEmail(f.email):null;
  var phoneErr=touched.phone?(!f.phone.trim()?"Phone number is required":validatePhone(f.phone,f.phoneType==="international")):null;
  var zipErr=touched.zip?validateZip(f.zip):null;
  var firstErr=touched.firstName&&!f.firstName.trim()?"Required":null;
  var lastErr=touched.lastName&&!f.lastName.trim()?"Required":null;
  var canSave=f.firstName.trim()&&f.lastName.trim()&&f.phone.trim()&&!emailErr&&!phoneErr&&!zipErr;
  var handleSave=function(){setTouch({firstName:true,lastName:true,email:true,phone:true,zip:true});if(!canSave)return;onSave(Object.assign({},customer,f,{name:(f.firstName+" "+f.lastName).trim(),updatedAt:new Date().toISOString()}));onClose();};
  return(
    <Modal title="EDIT CLIENT DETAILS" subtitle={"Client ID "+dispCustId(customer.id)+" stays the same"} onClose={onClose}>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
        <FG label="First Name" required err={firstErr}><input value={f.firstName} onChange={set("firstName")} onBlur={function(){touch("firstName");}} placeholder="First name" autoFocus className={firstErr?"err":f.firstName.trim()?"ok":""}/></FG>
        <FG label="Last Name" required err={lastErr}><input value={f.lastName} onChange={set("lastName")} onBlur={function(){touch("lastName");}} placeholder="Last name" className={lastErr?"err":f.lastName.trim()?"ok":""}/></FG>
        <FG label="Street Address" span={2}><input value={f.street} onChange={set("street")} placeholder="123 Main Street"/></FG>
        <FG label="City"><input value={f.city} onChange={set("city")} placeholder="Conway"/></FG>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
          <FG label="State"><select value={f.state} onChange={set("state")}><option value="">-- State --</option>{US_STATES.map(function(s){return <option key={s} value={s}>{s}</option>;})}</select></FG>
          <FG label="ZIP" err={zipErr}><input value={f.zip} onChange={set("zip")} onBlur={function(){touch("zip");}} placeholder="29526" maxLength={10} className={zipErr?"err":f.zip&&!zipErr?"ok":""}/></FG>
        </div>
        <FG label="Contact Number" required span={2} err={phoneErr}>
          <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
            <input value={f.phone} onChange={set("phone")} onBlur={function(){touch("phone");}} placeholder={f.phoneType==="international"?"e.g. +44 20 7946 0958":"xxx-xxx-xxxx"} maxLength={f.phoneType==="international"?30:12} className={phoneErr?"err":f.phone&&!phoneErr?"ok":""} style={{flex:1,minWidth:140}}/>
            <div style={{display:"flex",gap:10,padding:"6px 0"}}>
              <label className="cb"><input type="checkbox" checked={f.phoneType==="landline"} onChange={function(e){setPhoneType(e.target.checked?"landline":"standard");}}/>Landline</label>
              <label className="cb"><input type="checkbox" checked={f.phoneType==="international"} onChange={function(e){setPhoneType(e.target.checked?"international":"standard");}}/>Intl</label>
            </div>
          </div>
        </FG>
        <FG label="Email Address" span={2} err={emailErr}><input value={f.email} onChange={set("email")} onBlur={function(){touch("email");}} placeholder="client@domain.com" type="email" className={emailErr?"err":f.email&&!emailErr?"ok":""}/></FG>
        <FG label="Internal Notes" span={2}><textarea value={f.notes} onChange={set("notes")} placeholder="Fleet account, preferred schedule, referral source..."/></FG>
      </div>
      <div style={{display:"flex",justifyContent:"flex-end",gap:8,marginTop:18,borderTop:"1px solid var(--bdr)",paddingTop:14}}>
        <Btn v="ghost" onClick={onClose}>Cancel</Btn>
        <Btn v="primary" sz="lg" onClick={handleSave}>Save Changes</Btn>
      </div>
    </Modal>
  );
};

/* ── CLIENT PROFILE ──────────────────────────────────────────────────────── */
const ClientProfile=({customer,vehicles,jobs,archVehicles=[],onBack,onSelectJob,onAddVehicle,onArchive,onNewJob,onViewVehicleReport,settings={},onUpdateClient,comms=[],onAddComm,onUpdateComm,onDeleteComm})=>{
  const[showAddV,setAddV]=useState(false);
  const[showEdit,setShowEdit]=useState(false);
  const[cf,setCf]=useState({date:TODAY,channel:"Call",direction:"out",summary:"",vehicleId:"",followUp:false,followUpDate:""});
  const setCfK=function(k){return function(e){var val=e.target.value;setCf(function(p){var n=Object.assign({},p);n[k]=val;return n;});};};
  const saveComm=function(){if(!cf.summary.trim()||!onAddComm)return;onAddComm({id:uid(),customerId:customer.id,vehicleId:cf.vehicleId||null,date:cf.date||TODAY,channel:cf.channel,direction:cf.direction,summary:cf.summary.trim(),followUp:!!cf.followUp,followUpDate:cf.followUp?(cf.followUpDate||TODAY):"",done:false,createdAt:new Date().toISOString()});setCf(function(p){return Object.assign({},p,{summary:"",followUp:false,followUpDate:""});});};
  var clientComms=(comms||[]).filter(function(cm){return cm.customerId===customer.id;}).slice().sort(function(a,b){return (a.date||"")<(b.date||"")?1:-1;});
  const[jobSort,setJobSort]=useState({col:"scheduledDate",dir:"desc"});
  const[jobFilter,setJobFilter]=useState("all");
  const cveh=vehicles.filter(v=>v.customerId===customer.id);
  const cjobs=jobs.filter(j=>j.customerId===customer.id);
  const displayJobs=useMemo(()=>{
    let list=[...cjobs];if(jobFilter!=="all")list=list.filter(j=>j.status===jobFilter);
    list.sort((a,b)=>{let av=a[jobSort.col],bv=b[jobSort.col];if(["total","profit","labor"].includes(jobSort.col)){const ca=calcJob(a),cb=calcJob(b);av=jobSort.col==="total"?ca.total:jobSort.col==="profit"?ca.profit:ca.labRev;bv=jobSort.col==="total"?cb.total:jobSort.col==="profit"?cb.profit:cb.labRev;}if(av<bv)return jobSort.dir==="asc"?-1:1;if(av>bv)return jobSort.dir==="asc"?1:-1;return 0;});return list;
  },[cjobs,jobSort,jobFilter]);
  const sortBy=col=>setJobSort(s=>s.col===col?{col,dir:s.dir==="asc"?"desc":"asc"}:{col,dir:"desc"});
  const si=col=>jobSort.col===col?(jobSort.dir==="asc"?"^":"v"):"~";
  const lifetimeRev=cjobs.reduce((s,j)=>s+calcJob(j).total,0);
  const lifetimeProf=cjobs.reduce((s,j)=>s+calcJob(j).profit,0);
  const addrLine=[customer.street,[customer.city,customer.state].filter(Boolean).join(", "),customer.zip].filter(Boolean).join(" · ");
  const esc=function(s){return String(s==null?"":s).split("&").join("&amp;").split("<").join("&lt;").split(">").join("&gt;");};
  const downloadSummary=function(){
    var shopName=(settings&&settings.shopName)?settings.shopName:"Mobile Mechanic";
    var shopLine=[(settings&&settings.address)||"",(settings&&settings.phone)||"",(settings&&settings.email)||""].filter(Boolean).map(esc).join(" &bull; ");
    var visits=cjobs.length;
    var sorted=cjobs.slice().sort(function(a,b){return a.scheduledDate>b.scheduledDate?-1:1;});
    var lastSvc=sorted.length?fmtD(sorted[0].scheduledDate):"None on file";
    var completed=cjobs.filter(function(j){return j.status==="completed";}).length;
    var vehRows=cveh.map(function(v){
      var vj=jobs.filter(function(j){return j.vehicleId===v.id;}).length;
      return "<tr><td>"+esc((v.year||"")+" "+(v.make||"")+" "+(v.model||""))+"</td><td class='mono'>"+esc(dispVehId(v.vehicleId)||"")+"</td><td>"+esc(v.type||"")+"</td><td class='mono'>"+esc(v.vin||"-")+"</td><td class='mono'>"+esc(v.plate||"-")+"</td><td style='text-align:center'>"+vj+"</td></tr>";
    }).join("");
    if(!vehRows)vehRows="<tr><td colspan='6' style='text-align:center;color:#888'>No vehicles on file</td></tr>";
    var jobRows=sorted.slice(0,12).map(function(j){
      var veh=vehicles.find(function(x){return x.id===j.vehicleId;})||{};
      var svc=(j.services||[]).map(function(s){return s.name;}).join(", ")||"-";
      var tot=calcJob(j).total;
      return "<tr><td class='mono'>"+esc(fmtD(j.scheduledDate))+"</td><td>"+esc((veh.year||"")+" "+(veh.make||"")+" "+(veh.model||""))+"</td><td>"+esc(svc)+"</td><td>"+esc(sLabel(j.status))+"</td><td class='mono' style='text-align:right'>"+esc(fmt$(tot))+"</td></tr>";
    }).join("");
    if(!jobRows)jobRows="<tr><td colspan='5' style='text-align:center;color:#888'>No service history yet</td></tr>";
    var html="<!doctype html><html><head><meta charset='utf-8'><title>Client Summary - "+esc(fullName(customer))+"</title><style>"
      +"*{box-sizing:border-box;margin:0;padding:0}body{font-family:Arial,Helvetica,sans-serif;color:#1a1a1a;background:#f4f4f5;padding:28px;line-height:1.5}"
      +".doc{max-width:800px;margin:0 auto;background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 2px 16px rgba(0,0,0,.08)}.bar{height:6px;background:linear-gradient(90deg,#f97316,#ea6800)}.pad{padding:30px 34px}"
      +".head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid #f97316;padding-bottom:16px;margin-bottom:20px}.shop{font-size:20px;font-weight:800;color:#111}.shopline{font-size:11px;color:#666;margin-top:3px}"
      +".tag{font-size:13px;font-weight:800;color:#f97316;letter-spacing:.12em;text-transform:uppercase}.cid{font-family:'Courier New',monospace;font-size:13px;color:#f97316;font-weight:700;margin-top:4px}"
      +".name{font-size:26px;font-weight:800;margin-bottom:6px}.meta{font-size:13px;color:#444;margin-bottom:2px}.note{margin-top:10px;padding:8px 12px;background:#fff7ed;border-left:3px solid #f97316;font-size:12px;color:#7c2d12;border-radius:4px}"
      +".stats{display:flex;gap:12px;margin:22px 0}.stat{flex:1;background:#fafafa;border:1px solid #e5e5e5;border-radius:8px;padding:12px;text-align:center}.stat .l{font-size:9px;font-weight:700;letter-spacing:.1em;color:#888;text-transform:uppercase}.stat .v{font-size:20px;font-weight:800;margin-top:4px;color:#111}"
      +"h2{font-size:13px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:#333;margin:22px 0 10px;padding-bottom:6px;border-bottom:1px solid #e5e5e5}table{width:100%;border-collapse:collapse;font-size:12px}"
      +"th{text-align:left;font-size:9px;letter-spacing:.06em;text-transform:uppercase;color:#888;padding:6px 8px;border-bottom:1px solid #ddd}td{padding:7px 8px;border-bottom:1px solid #f0f0f0;color:#333}.mono{font-family:'Courier New',monospace}"
      +".foot{margin-top:24px;padding-top:14px;border-top:1px solid #e5e5e5;font-size:10px;color:#999;text-align:center}@media print{body{background:#fff;padding:0}.doc{box-shadow:none;border-radius:0}}"
      +"</style></head><body><div class='doc'><div class='bar'></div><div class='pad'>"
      +"<div class='head'><div><div class='shop'>"+esc(shopName)+"</div><div class='shopline'>"+shopLine+"</div></div><div style='text-align:right'><div class='tag'>Client Summary</div><div class='cid'>"+esc(dispCustId(customer.id))+"</div><div class='shopline'>Generated "+esc(fmtD(TODAY))+"</div></div></div>"
      +"<div class='name'>"+esc(fullName(customer))+"</div>"
      +(customer.phone?"<div class='meta'>Phone: "+esc(customer.phone)+"</div>":"")
      +(customer.email?"<div class='meta'>Email: "+esc(customer.email)+"</div>":"")
      +(addrLine?"<div class='meta'>Address: "+esc(addrLine)+"</div>":"")
      +(customer.notes?"<div class='note'>"+esc(customer.notes)+"</div>":"")
      +"<div class='stats'><div class='stat'><div class='l'>Vehicles</div><div class='v'>"+cveh.length+"</div></div><div class='stat'><div class='l'>Total Visits</div><div class='v'>"+visits+"</div></div><div class='stat'><div class='l'>Completed</div><div class='v'>"+completed+"</div></div><div class='stat'><div class='l'>Total Billed</div><div class='v'>"+esc(fmt$(lifetimeRev))+"</div></div></div>"
      +"<h2>Vehicles on File</h2><table><thead><tr><th>Vehicle</th><th>ID</th><th>Type</th><th>VIN / Serial</th><th>Plate</th><th style='text-align:center'>Jobs</th></tr></thead><tbody>"+vehRows+"</tbody></table>"
      +"<h2>Recent Service History</h2><table><thead><tr><th>Date</th><th>Vehicle</th><th>Services</th><th>Status</th><th style='text-align:right'>Invoice</th></tr></thead><tbody>"+jobRows+"</tbody></table>"
      +"<div class='foot'>Last service: "+esc(lastSvc)+" &bull; This summary reflects records on file as of "+esc(fmtD(TODAY))+".</div>"
      +"</div></div></body></html>";
    var a=document.createElement("a");
    a.href="data:text/html;charset=utf-8,"+encodeURIComponent(html);
    a.download="client-summary-"+dispCustId(customer.id)+".html";
    document.body.appendChild(a);a.click();document.body.removeChild(a);
  };
  return(
    <div className="fade" style={{paddingBottom:80}}>
      <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:16}}>
        <Btn v="ghost" sz="sm" onClick={onBack}>Back</Btn>
        <span style={{color:"var(--txt3)",fontSize:12}}>Client Profile</span>
        <div style={{marginLeft:"auto",display:"flex",gap:8}}>
          <Btn v="subtle" sz="sm" onClick={downloadSummary}>Download Summary</Btn>
          {onUpdateClient&&<Btn v="outline" sz="sm" onClick={function(){setShowEdit(true);}}>Edit Details</Btn>}
        </div>
      </div>
      <div style={{background:"var(--s2)",border:"1px solid var(--bdr)",borderRadius:12,overflow:"hidden",marginBottom:14}}>
        <div style={{height:3,background:"linear-gradient(90deg,var(--acc),var(--acc2),transparent)"}}/>
        <div style={{padding:"18px 22px"}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",flexWrap:"wrap",gap:14}}>
            <div>
              <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:7}}>
                <span className="mono" style={{fontSize:12,color:"var(--acc)",background:"var(--acc)14",border:"1px solid var(--acc)44",padding:"2px 10px",borderRadius:5,fontWeight:700}}>{dispCustId(customer.id)}</span>
                <Chip label={`${cveh.length} veh`} color="var(--blu)" small/><Chip label={`${cjobs.length} job${cjobs.length!==1?"s":""}`} color="var(--pur)" small/>
              </div>
              <div style={{fontFamily:"var(--fd)",fontSize:30,fontWeight:900,lineHeight:1,marginBottom:8}}>{customer.firstName} <span style={{color:"var(--acc)"}}>{customer.lastName}</span></div>
              <div style={{fontSize:13,color:"var(--txt2)",display:"flex",flexDirection:"column",gap:3}}>
                {customer.phone&&<span>{customer.phoneType==="landline"?"☎️":customer.phoneType==="international"?"🌐":"📱"} <span className="mono">{customer.phone}</span></span>}
                {customer.email&&<span>📧 {customer.email}</span>}
                {addrLine&&<span style={{fontSize:12,color:"var(--txt3)"}}>📍 {addrLine}</span>}
              </div>
              {customer.notes&&<div style={{marginTop:8,padding:"6px 10px",background:"var(--s3)",borderRadius:"var(--r)",fontSize:12,color:"var(--ylw)",borderLeft:"3px solid var(--ylw)",maxWidth:420}}>{customer.notes}</div>}
            </div>
            <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
              {[["Revenue",fmt$(lifetimeRev),"var(--grn)"],["Net Profit",fmt$(lifetimeProf),lifetimeProf>=0?"var(--grn)":"var(--red)"],["Jobs",cjobs.length,"var(--acc)"]].map(([l,v,col])=>(
                <div key={l} style={{background:"var(--s3)",border:"1px solid var(--bdr)",borderRadius:"var(--r2)",padding:"10px 14px",minWidth:90,textAlign:"center"}}>
                  <div style={{fontSize:9,fontFamily:"var(--fd)",fontWeight:700,letterSpacing:".1em",color:"var(--txt3)",textTransform:"uppercase",marginBottom:3}}>{l}</div>
                  <div className="mono" style={{fontSize:18,fontWeight:700,color:col}}>{v}</div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
      {/* Vehicles */}
      <Card style={{marginBottom:14}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
          <div style={{fontFamily:"var(--fd)",fontSize:15,fontWeight:900}}>VEHICLES <span style={{color:"var(--txt3)",fontWeight:600,fontSize:12}}>({cveh.length})</span></div>
          <Btn v="outline" sz="sm" onClick={()=>setAddV(true)}>+ ADD VEHICLE</Btn>
        </div>
        {cveh.length===0&&<div style={{color:"var(--txt3)",fontSize:13,padding:"10px 0",textAlign:"center"}}><div style={{marginBottom:8}}>No vehicles on file.</div><Btn v="subtle" sz="sm" onClick={()=>setAddV(true)}>+ Add First Vehicle</Btn></div>}
        {cveh.length>0&&<div style={{overflowX:"auto"}}><table>
          <thead><tr><th>Type</th><th>Vehicle ID</th><th>Year</th><th>Make</th><th>Model</th><th>Engine</th><th>Drive</th><th>Fuel</th><th>Color</th><th>VIN / ID</th><th>Plate</th><th>Odometer</th><th>Jobs</th><th></th></tr></thead>
          <tbody>{cveh.map(v=>{const vtc=VT[v.type]||VT.Car;const vj=jobs.filter(j=>j.vehicleId===v.id).length;return(
            <tr key={v.id} style={{cursor:"pointer"}} onClick={()=>onViewVehicleReport(v.id)}>
              <td><span style={{fontSize:14}}>{vtc.icon}</span> <span style={{fontFamily:"var(--fd)",fontSize:11,color:vtc.color,fontWeight:700}}>{v.type}</span></td>
              <td><span className="mono" style={{fontSize:11,color:"var(--acc)"}}>{dispVehId(v.vehicleId)||"—"}</span></td>
              <td className="mono">{v.year||"—"}</td><td>{v.make||"—"}</td><td>{v.model||"—"}</td>
              <td style={{color:"var(--txt2)",fontSize:11}}>{v.engine||"—"}</td>
              <td style={{fontSize:11,color:"var(--txt2)"}}>{v.driveType||"—"}</td>
              <td style={{fontSize:11,color:"var(--txt2)"}}>{v.fuelType||"—"}</td>
              <td style={{fontSize:11}}>{v.color||"—"}</td>
              <td><span className="mono" style={{fontSize:10,color:"var(--txt3)"}}>{v.vin||"—"}</span></td>
              <td className="mono" style={{fontSize:11}}>{v.plate||"—"}</td>
              <td className="mono" style={{fontSize:11}}>{v.dist?Number(v.dist).toLocaleString()+"mi":"—"}</td>
              <td><Chip label={vj+" job"+(vj!==1?"s":"")} color={vj>0?"var(--acc)":"var(--txt3)"} small/></td>
              <td><Btn v="ghost" sz="sm">Report &gt;</Btn></td>
            </tr>
          );})}</tbody>
        </table></div>}
      </Card>
      {/* Job History */}
      <Card>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12,flexWrap:"wrap",gap:8}}>
          <div style={{fontFamily:"var(--fd)",fontSize:15,fontWeight:900}}>JOB HISTORY <span style={{color:"var(--txt3)",fontWeight:600,fontSize:12}}>({cjobs.length})</span></div>
          <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
            <Btn v="primary" sz="sm" onClick={onNewJob}>+ Log New Job</Btn>
            <div style={{display:"flex",gap:0,borderBottom:"1px solid var(--bdr)"}}>
              {["all","upcoming","in-progress","completed"].map(fv=>(
                <button key={fv} onClick={()=>setJobFilter(fv)} style={{background:"none",border:"none",borderBottom:jobFilter===fv?"2px solid var(--acc)":"2px solid transparent",padding:"4px 10px",fontFamily:"var(--fd)",fontSize:11,fontWeight:800,cursor:"pointer",color:jobFilter===fv?"var(--acc)":"var(--txt3)"}}>
                  {fv==="all"?"All":fv==="in-progress"?"In Progress":fv.charAt(0).toUpperCase()+fv.slice(1)} <span style={{fontSize:9,background:"var(--s3)",padding:"0 4px",borderRadius:6}}>{fv==="all"?cjobs.length:cjobs.filter(j=>j.status===fv).length}</span>
                </button>
              ))}
            </div>
          </div>
        </div>
        {displayJobs.length===0&&<div style={{color:"var(--txt3)",fontSize:13,padding:"10px 0",textAlign:"center"}}>No jobs match this filter.</div>}
        {displayJobs.length>0&&<div style={{overflowX:"auto"}}><table>
          <thead><tr>
            <th className="sort" onClick={()=>sortBy("scheduledDate")}>Date {si("scheduledDate")}</th>
            <th>Vehicle</th><th>Services</th>
            <th className="sort" onClick={()=>sortBy("status")}>Status {si("status")}</th>
            <th>Via</th>
            <th className="sort" onClick={()=>sortBy("labor")}>Labor {si("labor")}</th>
            <th className="sort" onClick={()=>sortBy("total")}>Invoice {si("total")}</th>
            <th className="sort" onClick={()=>sortBy("profit")}>Profit {si("profit")}</th>
            <th>Notes</th><th></th>
          </tr></thead>
          <tbody>{displayJobs.map(j=>{const{labRev,total,profit}=calcJob(j);const veh=vehicles.find(v=>v.id===j.vehicleId)||{};const vtc=VT[veh.type]||VT.Car;return(
            <tr key={j.id} style={{cursor:"pointer"}} onClick={()=>onSelectJob(j.id)}>
              <td className="mono" style={{fontSize:11,whiteSpace:"nowrap"}}>{fmtD(j.scheduledDate)}</td>
              <td><span>{vtc.icon}</span> <span style={{fontSize:11,color:"var(--txt2)"}}>{veh.year} {veh.make} {veh.model}</span></td>
              <td style={{maxWidth:160}}><div style={{fontSize:11,color:"var(--txt2)",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{(j.services||[]).map(s=>s.name).join(", ")||"—"}</div></td>
              <td><Chip label={sLabel(j.status)} color={sColor(j.status)} small/></td>
              <td style={{fontSize:11,color:"var(--txt3)"}}>{srcIcon(j.loggedVia)} {j.loggedVia}</td>
              <td className="mono" style={{color:"var(--txt2)"}}>{fmt$(labRev)}</td>
              <td className="mono acc" style={{fontWeight:700}}>{fmt$(total)}</td>
              <td className="mono" style={{color:profit>=0?"var(--grn)":"var(--red)",fontWeight:700}}>{fmt$(profit)}</td>
              <td style={{color:"var(--ylw)",fontSize:12}}>{(j.notes||[]).length>0?`📝 ${j.notes.length}`:"—"}</td>
              <td><Btn v="ghost" sz="sm">View &gt;</Btn></td>
            </tr>
          );})}</tbody>
        </table></div>}
      </Card>
      {/* ── COMMUNICATION LOG ── */}
      {onAddComm&&<Card style={{marginBottom:70}}>
        <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:10}}>
          <div style={{fontFamily:"var(--fd)",fontSize:15,fontWeight:900}}>COMMUNICATION <span style={{color:"var(--acc)"}}>LOG</span></div>
          <span style={{fontSize:11,color:"var(--txt3)"}}>({clientComms.length})</span>
          <div style={{flex:1}}/>
          <span style={{fontSize:10,color:"var(--txt3)"}}>Calls, texts, quotes discussed &mdash; so nothing slips</span>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"120px 1fr 1fr",gap:8,marginBottom:8}}>
          <FG label="Date"><input type="date" value={cf.date} onChange={setCfK("date")}/></FG>
          <FG label="Channel"><select value={cf.channel} onChange={setCfK("channel")}>{["Call","Text","Email","In-Person"].map(function(c2){return <option key={c2} value={c2}>{c2}</option>;})}</select></FG>
          <FG label="Direction"><select value={cf.direction} onChange={setCfK("direction")}><option value="out">Outbound</option><option value="in">Inbound</option></select></FG>
        </div>
        <div style={{display:"grid",gridTemplateColumns:cveh.length>0?"1fr 200px":"1fr",gap:8,marginBottom:8}}>
          <FG label="What was discussed"><input value={cf.summary} onChange={setCfK("summary")} placeholder="e.g. Quoted front brakes $412, will confirm Friday" onKeyDown={function(e){if(e.key==="Enter")saveComm();}}/></FG>
          {cveh.length>0&&<FG label="Vehicle (optional)"><select value={cf.vehicleId} onChange={setCfK("vehicleId")}><option value="">General</option>{cveh.map(function(v){return <option key={v.id} value={v.id}>{(v.year||"")+" "+(v.make||"")+" "+(v.model||"")}</option>;})}</select></FG>}
        </div>
        <div style={{display:"flex",alignItems:"center",gap:10,flexWrap:"wrap"}}>
          <label className="cb"><input type="checkbox" checked={cf.followUp} onChange={function(e){var ck=e.target.checked;setCf(function(p){var n=Object.assign({},p);n.followUp=ck;if(ck&&!n.followUpDate)n.followUpDate=TODAY;return n;});}}/>Needs follow-up</label>
          {cf.followUp&&<input type="date" value={cf.followUpDate} onChange={setCfK("followUpDate")} style={{width:150}}/>}
          <div style={{flex:1}}/>
          <Btn v="primary" sz="sm" onClick={saveComm} disabled={!cf.summary.trim()}>Log It</Btn>
        </div>
        {clientComms.length>0&&<div style={{marginTop:12,borderTop:"1px solid var(--bdr)",paddingTop:10,display:"flex",flexDirection:"column",gap:6,maxHeight:320,overflowY:"auto"}}>
          {clientComms.map(function(cm){
            var ch=COMM_CH[cm.channel]||COMM_CH.Call;
            var cvh=cveh.find(function(v){return v.id===cm.vehicleId;});
            var overdue=cm.followUp&&!cm.done&&cm.followUpDate&&cm.followUpDate<=TODAY;
            return(
              <div key={cm.id} style={{display:"flex",gap:9,alignItems:"flex-start",padding:"8px 10px",background:"var(--s3)",borderRadius:"var(--r2)",borderLeft:"3px solid "+ch.col}}>
                <span className="mono" style={{fontSize:10,color:"var(--txt3)",flexShrink:0,paddingTop:2}}>{fmtD(cm.date)}</span>
                <span style={{background:ch.col+"22",border:"1px solid "+ch.col+"55",color:ch.col,fontSize:9,fontFamily:"var(--fd)",fontWeight:800,padding:"1px 7px",borderRadius:10,flexShrink:0}}>{cm.channel.toUpperCase()}{cm.direction==="in"?" IN":" OUT"}</span>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{fontSize:12,color:"var(--txt)",lineHeight:1.45}}>{cm.summary}</div>
                  {cvh&&<div style={{fontSize:10,color:"var(--txt3)",marginTop:2}}>{(cvh.year||"")+" "+(cvh.make||"")+" "+(cvh.model||"")}</div>}
                  {cm.followUp&&!cm.done&&<div style={{fontSize:10,fontFamily:"var(--fd)",fontWeight:800,marginTop:3,color:overdue?"var(--red)":"var(--ylw)"}}>{overdue?"FOLLOW-UP DUE — ":"Follow-up "}{fmtD(cm.followUpDate)}</div>}
                  {cm.followUp&&cm.done&&<div style={{fontSize:10,fontFamily:"var(--fd)",fontWeight:700,marginTop:3,color:"var(--grn)"}}>Followed up</div>}
                </div>
                {cm.followUp&&!cm.done&&onUpdateComm&&<Btn v="outline" sz="sm" onClick={function(){onUpdateComm(cm.id,{done:true});}}>Done</Btn>}
                {onDeleteComm&&<button aria-label="Remove" title="Remove" onClick={function(){if(window.confirm("Delete this log entry?"))onDeleteComm(cm.id);}} style={{background:"none",border:"none",color:"var(--txt3)",cursor:"pointer",fontSize:14,padding:"4px 9px",flexShrink:0}}>x</button>}
              </div>
            );
          })}
        </div>}
      </Card>}
      <div className="floating-actions" style={{position:"fixed",zIndex:100}}>
        {customer.street&&<Btn v="subtle" sz="sm" onClick={function(){window.open(mapsUrl([customer.street,customer.city,customer.state,customer.zip].filter(Boolean).join(", ")),"_blank","noopener,noreferrer");}}>Navigate</Btn>}
        <Btn v="archive" sz="sm" onClick={()=>{if(window.confirm(`Archive ${fullName(customer)}?`))onArchive(customer.id);}}>🗄 Archive Client</Btn>
      </div>
      {showAddV&&<AddVehicleModal customer={customer} onClose={()=>setAddV(false)} allVehicles={vehicles.concat(archVehicles)} onSave={v=>{onAddVehicle(v);setAddV(false);}}/>}
      {showEdit&&onUpdateClient&&<EditClientModal customer={customer} onClose={function(){setShowEdit(false);}} onSave={onUpdateClient}/>}
    </div>
  );
};

/* ── CUSTOMERS PAGE ──────────────────────────────────────────────────────── */
const CustomersPage=({customers,vehicles,jobs,archVehicles=[],setCust,setVeh,onSelectJob,onArchiveClient,onNewJob,settings,onUpdateClient,comms,onAddComm,onUpdateComm,onDeleteComm})=>{
  const[view,setView]=useState({type:"roster"});
  const[showAddC,setAddC]=useState(false);
  const[search,setSearch]=useState("");
  if(view.type==="profile"){const cust=customers.find(c=>c.id===view.custId);if(cust)return(<ClientProfile customer={cust} vehicles={vehicles} jobs={jobs} archVehicles={archVehicles} settings={settings} onUpdateClient={onUpdateClient} comms={comms} onAddComm={onAddComm} onUpdateComm={onUpdateComm} onDeleteComm={onDeleteComm} onBack={()=>setView({type:"roster"})} onSelectJob={onSelectJob} onAddVehicle={v=>setVeh(prev=>[...prev,v])} onArchive={id=>{onArchiveClient(id);setView({type:"roster"});}} onNewJob={()=>onNewJob({customerId:cust.id})} onViewVehicleReport={vId=>setView({type:"vehicle",vehicleId:vId,custId:cust.id})}/>);}
  if(view.type==="vehicle"){const veh=vehicles.find(v=>v.id===view.vehicleId);if(veh)return(<VehicleReport vehicle={veh} jobs={jobs} onBack={()=>setView({type:"profile",custId:view.custId})} onSelectJob={onSelectJob} onNewJob={()=>onNewJob({vehicleId:veh.id,customerId:veh.customerId})}/>);}
  const filtered=customers.filter(c=>{const q=search.toLowerCase();return fullName(c).toLowerCase().includes(q)||(c.id&&c.id.toLowerCase()).includes(q)||(c.phone&&c.phone.includes(search))||(c.email&&c.email.toLowerCase()).includes(q)});
  return(
    <div className="fade" style={{height:"100%",display:"flex",flexDirection:"column"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12,flexShrink:0}}>
        <div><div style={{fontFamily:"var(--fd)",fontSize:26,fontWeight:900}}>CLIENT <span style={{color:"var(--acc)"}}>ROSTER</span></div><div style={{fontSize:12,color:"var(--txt3)"}}>{customers.length} client{customers.length!==1?"s":""} · {vehicles.length} vehicle{vehicles.length!==1?"s":""}</div></div>
        <Btn v="primary" sz="lg" onClick={()=>setAddC(true)}>+ ADD CLIENT</Btn>
      </div>
      <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="🔍  Search by name, ID, phone, or email…" style={{marginBottom:12,flexShrink:0}}/>
      {customers.length===0&&<div style={{flex:1,display:"flex",alignItems:"center",justifyContent:"center",flexDirection:"column",gap:10,color:"var(--txt3)"}}><div style={{fontSize:44}}>👤</div><div style={{fontFamily:"var(--fd)",fontSize:16,fontWeight:700}}>NO CLIENTS YET</div><Btn v="primary" sz="lg" onClick={()=>setAddC(true)}>+ ADD FIRST CLIENT</Btn></div>}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(270px,1fr))",gap:10,overflowY:"auto",flex:1}}>
        {filtered.map(c=>{const cv=vehicles.filter(v=>v.customerId===c.id);const cj=jobs.filter(j=>j.customerId===c.id);const rev=cj.reduce((s,j)=>s+calcJob(j).total,0);const last=[...cj].sort((a,b)=>b.scheduledDate>a.scheduledDate?1:-1)[0];const addrLine=[c.city,c.state].filter(Boolean).join(", ");return(
          <div key={dispCustId(c.id)} onClick={()=>setView({type:"profile",custId:c.id})} style={{background:"var(--s2)",border:"1px solid var(--bdr)",borderRadius:12,padding:"14px 16px",cursor:"pointer",transition:"all .18s",position:"relative",overflow:"hidden"}} onMouseEnter={e=>{e.currentTarget.style.borderColor="var(--acc)";e.currentTarget.style.background="var(--s3)"}} onMouseLeave={e=>{e.currentTarget.style.borderColor="var(--bdr)";e.currentTarget.style.background="var(--s2)"}}>
            <div style={{position:"absolute",top:0,left:0,right:0,height:3,background:"linear-gradient(90deg,var(--acc),transparent)"}}/>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:8}}>
              <div><div style={{fontFamily:"var(--fd)",fontSize:18,fontWeight:900,lineHeight:1.1,marginBottom:2}}>{fullName(c)}</div>{addrLine&&<div style={{fontSize:11,color:"var(--txt3)"}}>📍 {addrLine}</div>}</div>
              <span className="mono" style={{fontSize:10,color:"var(--acc)",background:"var(--acc)14",border:"1px solid var(--acc)44",padding:"2px 7px",borderRadius:4,fontWeight:700,marginLeft:6,flexShrink:0}}>{dispCustId(c.id)}</span>
            </div>
            <div style={{fontSize:12,color:"var(--txt2)",display:"flex",flexDirection:"column",gap:3,marginBottom:10}}>
              {c.phone&&<span>{c.phoneType==="landline"?"☎️":c.phoneType==="international"?"🌐":"📱"} <span className="mono">{c.phone}</span></span>}
              {c.email&&<span style={{overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>📧 {c.email}</span>}
            </div>
            <Divider m="8px 0"/>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",fontSize:11}}>
              <div style={{display:"flex",gap:10,color:"var(--txt3)"}}><span>🚗 {cv.length}</span><span>🔧 {cj.length}</span></div>
              {rev>0&&<span className="mono" style={{color:"var(--grn)",fontWeight:700}}>{fmt$(rev)}</span>}
            </div>
            {last&&<div style={{marginTop:4,fontSize:10,color:"var(--txt3)"}}>Last service: {fmtD(last.scheduledDate)}</div>}
            <div style={{position:"absolute",bottom:12,right:14,fontSize:10,color:"var(--acc)",fontFamily:"var(--fd)",fontWeight:800,opacity:.6}}>VIEW PROFILE &gt;</div>
          </div>
        );})}
        {filtered.length===0&&customers.length>0&&<div style={{gridColumn:"1/-1",padding:"24px",textAlign:"center",color:"var(--txt3)",fontSize:13}}>No results for "{search}"</div>}
      </div>
      {showAddC&&<AddClientModal onClose={()=>setAddC(false)} customers={customers} onSave={c=>setCust(prev=>[...prev,c])}/>}
    </div>
  );
};

/* ── JOBS BOARD ──────────────────────────────────────────────────────────── */
const JobsBoard=({jobs,customers,vehicles,onSelectJob,onNewJob,onArchiveJob})=>{
  const[filter,setFilter]=useState("all");
  const filtered=[...jobs.filter(j=>filter==="all"||j.status===filter)].sort((a,b)=>b.scheduledDate>a.scheduledDate?1:-1);
  const cnt=s=>jobs.filter(j=>j.status===s).length;
  const tabs=[["all","All",jobs.length],["upcoming","Upcoming",cnt("upcoming")],["in-progress","In Progress",cnt("in-progress")],["completed","Completed",cnt("completed")]];
  return(
    <div className="fade">
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}><div style={{fontFamily:"var(--fd)",fontSize:26,fontWeight:900}}>JOBS <span style={{color:"var(--acc)"}}>BOARD</span></div><Btn v="primary" onClick={onNewJob}>+ LOG NEW JOB</Btn></div>
      <div style={{display:"flex",gap:0,marginBottom:14,borderBottom:"1px solid var(--bdr)"}}>
        {tabs.map(([val,lbl,c2])=><button key={val} onClick={()=>setFilter(val)} style={{background:"none",border:"none",borderBottom:filter===val?"2px solid var(--acc)":"2px solid transparent",padding:"6px 14px",fontFamily:"var(--fd)",fontSize:13,fontWeight:800,cursor:"pointer",color:filter===val?"var(--acc)":"var(--txt3)"}}>{lbl} <span style={{fontSize:10,background:"var(--s3)",padding:"1px 6px",borderRadius:8}}>{c2}</span></button>)}
      </div>
      {filtered.length===0&&<div style={{textAlign:"center",padding:"36px 0",color:"var(--txt3)"}}>{jobs.length===0?<><div style={{fontSize:13,marginBottom:10}}>No jobs logged yet.</div><Btn v="primary" onClick={onNewJob}>Log First Job</Btn></>:"No jobs match this filter."}</div>}
      {filtered.map(j=>{
        const c=customers.find(x=>x.id===j.customerId)||{};const v=vehicles.find(x=>x.id===j.vehicleId)||{};const vtc=VT[v.type]||VT.Car;const{total,profit}=calcJob(j);
        return(
          <div key={j.id} className="fade" style={{background:"var(--s2)",border:"1px solid var(--bdr)",borderRadius:"var(--r2)",padding:"12px 14px",marginBottom:7,display:"flex",alignItems:"center",gap:10,transition:".15s"}} onMouseEnter={e=>e.currentTarget.style.borderColor="var(--acc)66"} onMouseLeave={e=>e.currentTarget.style.borderColor="var(--bdr)"}>
            <div onClick={()=>onSelectJob(j.id)} style={{display:"flex",gap:10,alignItems:"center",flex:1,cursor:"pointer",minWidth:0}}>
              <div style={{fontSize:22,flexShrink:0}}>{vtc.icon}</div>
              <div style={{flex:1,minWidth:0}}>
                <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap",marginBottom:3}}>
                  <span style={{fontFamily:"var(--fd)",fontSize:15,fontWeight:800}}>{fullName(c)||"Unknown"}</span>
                  <Chip label={sLabel(j.status)} color={sColor(j.status)} small/>
                  {j.jobId&&<span className="mono" style={{fontSize:9,color:"var(--txt3)"}}>{dispJobId(j.jobId)}</span>}
                </div>
                <div style={{fontSize:12,color:"var(--txt2)",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{v.year} {v.make} {v.model} · {(j.services||[]).map(s=>s.name).join(" · ")||"No services"}</div>
              </div>
            </div>
            <div style={{display:"flex",gap:12,alignItems:"center",flexShrink:0}}>
              <div style={{textAlign:"right",cursor:"pointer"}} onClick={()=>onSelectJob(j.id)}><div className="mono acc" style={{fontSize:13,fontWeight:700}}>{fmt$(total)}</div><div className="mono" style={{fontSize:11,color:profit>=0?"var(--grn)":"var(--red)"}}>{fmt$(profit)}</div></div>
              <div style={{fontSize:11,color:"var(--txt3)",cursor:"pointer"}} onClick={()=>onSelectJob(j.id)}>{fmtD(j.scheduledDate)}</div>
              <button onClick={e=>{e.stopPropagation();if(window.confirm("Archive this job?"))onArchiveJob(j.id);}} title="Archive job" style={{background:"none",border:"1px solid var(--bdr2)",borderRadius:"var(--r)",padding:"4px 8px",color:"var(--txt3)",fontSize:11,cursor:"pointer",flexShrink:0,fontFamily:"var(--fd)",fontWeight:700,transition:".15s"}} onMouseEnter={e=>{e.currentTarget.style.borderColor="var(--red)66";e.currentTarget.style.color="var(--red)"}} onMouseLeave={e=>{e.currentTarget.style.borderColor="var(--bdr2)";e.currentTarget.style.color="var(--txt3)"}}>🗄</button>
            </div>
          </div>
        );
      })}
    </div>
  );
};

/* ── ARCHIVE PAGE ──────────────────────────────────────────────────────────── */
const ArchivePage=({archivedClients,archivedVehicles,archivedJobs,onRestore})=>{
  const[tab,setTab]=useState("clients");
  const[selC,setSelC]=useState(new Set());const[selV,setSelV]=useState(new Set());const[selJ,setSelJ]=useState(new Set());
  const toggleC=id=>setSelC(s=>{const n=new Set(s);n.has(id)?n.delete(id):n.add(id);return n;});
  const toggleV=id=>setSelV(s=>{const n=new Set(s);n.has(id)?n.delete(id):n.add(id);return n;});
  const toggleJ=id=>setSelJ(s=>{const n=new Set(s);n.has(id)?n.delete(id):n.add(id);return n;});
  const CBRow=({checked,onChange,children})=>(<div style={{display:"flex",gap:10,alignItems:"center",padding:"10px 14px",background:"var(--s2)",border:"1px solid var(--bdr)",borderRadius:"var(--r2)",marginBottom:7}}><input type="checkbox" checked={checked} onChange={onChange} style={{width:16,height:16,accentColor:"var(--acc)",cursor:"pointer",flexShrink:0}}/><div style={{flex:1}}>{children}</div><span className="arch-tag">ARCHIVED</span></div>);
  const tabs=[["clients","👤 Clients",archivedClients.length],["vehicles","🚗 Vehicles",archivedVehicles.length],["jobs","🔧 Jobs",archivedJobs.length]];
  return(
    <div className="fade">
      <div style={{fontFamily:"var(--fd)",fontSize:26,fontWeight:900,marginBottom:4}}>ARCHIVE <span style={{color:"var(--ylw)"}}>VAULT</span></div>
      <div style={{fontSize:12,color:"var(--txt3)",marginBottom:16}}>Select items and click Restore to move them back to active records.</div>
      <div style={{display:"flex",gap:0,marginBottom:16,borderBottom:"1px solid var(--bdr)"}}>
        {tabs.map(([val,lbl,cnt])=>(<button key={val} onClick={()=>setTab(val)} style={{background:"none",border:"none",borderBottom:tab===val?"2px solid var(--ylw)":"2px solid transparent",padding:"7px 16px",fontFamily:"var(--fd)",fontSize:13,fontWeight:800,cursor:"pointer",color:tab===val?"var(--ylw)":"var(--txt3)"}}>{lbl} <span style={{fontSize:10,background:"var(--s3)",padding:"1px 6px",borderRadius:8}}>{cnt}</span></button>))}
      </div>
      {tab==="clients"&&<>{archivedClients.length===0&&<div style={{color:"var(--txt3)",fontSize:13,padding:"20px 0",textAlign:"center"}}>No archived clients.</div>}{archivedClients.map(c=>(<CBRow key={dispCustId(c.id)} checked={selC.has(c.id)} onChange={()=>toggleC(c.id)}><div style={{fontFamily:"var(--fd)",fontSize:15,fontWeight:800}}>{fullName(c)}</div><div style={{fontSize:12,color:"var(--txt3)",display:"flex",gap:10,marginTop:2}}><span className="mono" style={{color:"var(--acc)"}}>{dispCustId(c.id)}</span>{c.phone&&<span>📱 {c.phone}</span>}{c.email&&<span>📧 {c.email}</span>}</div></CBRow>))}{selC.size>0&&<Btn v="primary" sz="lg" onClick={()=>{onRestore("clients",[...selC]);setSelC(new Set());}}>↩ RESTORE {selC.size} CLIENT{selC.size!==1?"S":""}</Btn>}</>}
      {tab==="vehicles"&&<>{archivedVehicles.length===0&&<div style={{color:"var(--txt3)",fontSize:13,padding:"20px 0",textAlign:"center"}}>No archived vehicles.</div>}{archivedVehicles.map(v=>{const vtc=VT[v.type]||VT.Car;return(<CBRow key={v.id} checked={selV.has(v.id)} onChange={()=>toggleV(v.id)}><div style={{display:"flex",gap:8,alignItems:"center"}}><span style={{fontSize:18}}>{vtc.icon}</span><div><div style={{fontFamily:"var(--fd)",fontSize:15,fontWeight:800}}>{v.year} {v.make} {v.model}</div><div style={{fontSize:11,color:"var(--txt3)"}}>{v.type} · {v.vehicleId||v.vin||"No ID"}</div></div></div></CBRow>);})}{selV.size>0&&<Btn v="primary" sz="lg" onClick={()=>{onRestore("vehicles",[...selV]);setSelV(new Set());}}>↩ RESTORE {selV.size} VEHICLE{selV.size!==1?"S":""}</Btn>}</>}
      {tab==="jobs"&&<>{archivedJobs.length===0&&<div style={{color:"var(--txt3)",fontSize:13,padding:"20px 0",textAlign:"center"}}>No archived jobs.</div>}{archivedJobs.map(j=>{const{total,profit}=calcJob(j);return(<CBRow key={j.id} checked={selJ.has(j.id)} onChange={()=>toggleJ(j.id)}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:6}}><div><div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:800}}>{(j.services||[]).map(s=>s.name).join(", ")||"No services"}</div><div style={{fontSize:11,color:"var(--txt3)"}}>{fmtD(j.scheduledDate)} · {sLabel(j.status)}</div></div><div style={{textAlign:"right"}}><div className="mono acc" style={{fontSize:13,fontWeight:700}}>{fmt$(total)}</div><div className="mono" style={{fontSize:11,color:profit>=0?"var(--grn)":"var(--red)"}}>{fmt$(profit)}</div></div></div></CBRow>);})}{selJ.size>0&&<Btn v="primary" sz="lg" onClick={()=>{onRestore("jobs",[...selJ]);setSelJ(new Set());}}>↩ RESTORE {selJ.size} JOB{selJ.size!==1?"S":""}</Btn>}</>}
    </div>
  );
};

/* ── DASHBOARD ───────────────────────────────────────────────────────────── */
const Dashboard=({jobs,customers,vehicles,onSelectJob,onNewJob,goClients,goVehicles,user,settings={},goSettings,goPlaybook})=>{
  const tj=jobs.filter(function(j){return j.scheduledDate===TODAY;});
  const done=tj.filter(function(j){return j.status==="completed";});
  const rev=done.reduce(function(s,j){return s+calcJob(j).total;},0);
  const prof=done.reduce(function(s,j){return s+calcJob(j).profit;},0);
  const allRev=jobs.filter(function(j){return j.status==="completed";}).reduce(function(s,j){return s+calcJob(j).total;},0);
  const upcoming5=[...jobs].filter(function(j){return j.scheduledDate>=TODAY&&j.status!=="completed";}).sort(function(a,b){if(a.scheduledDate!==b.scheduledDate)return a.scheduledDate>b.scheduledDate?1:-1;return (a.scheduledTime||"")>(b.scheduledTime||"")?1:-1;}).slice(0,5);
  const Stat=function(p){return <Card style={{flex:1,minWidth:80}}><Lbl>{p.l}</Lbl><div style={{fontFamily:"var(--fd)",fontSize:20,fontWeight:900,color:p.color||"var(--acc)",lineHeight:1.1}}>{p.v}</div>{p.sub&&<div style={{fontSize:10,color:"var(--txt3)"}}>{p.sub}</div>}</Card>;};
  if(jobs.length===0)return(
    <div className="fade" style={{maxWidth:640,margin:"0 auto",paddingTop:8}}>
      <div style={{textAlign:"center",marginBottom:18}}>
        <div style={{fontFamily:"var(--fd)",fontSize:26,fontWeight:900,lineHeight:1.2}}>WELCOME TO <span style={{color:"var(--acc)"}}>MOBILE MECHANIC</span></div>
        <div style={{fontSize:12,color:"var(--txt3)",marginTop:4}}>Three quick steps and your shop is rolling. Everything saves to this device automatically.</div>
      </div>
      <Card>
        <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900,marginBottom:10,letterSpacing:".04em"}}>GET ROLLING</div>
        {[
          {done:!!(settings&&(settings.address||settings.phone||settings.logo)),label:"Complete your shop profile",sub:"Address, phone, and logo print on every invoice you send.",btn:"Open Settings",act:goSettings},
          {done:customers.length>0,label:"Add your first client",sub:"A name and phone number is all it takes to start.",btn:"Add Client",act:goClients},
          {done:false,label:"Schedule your first job",sub:"It lands on the calendar and the day's route.",btn:"New Job",act:onNewJob}
        ].map(function(s,i){
          return(
            <div key={i} style={{display:"flex",alignItems:"center",gap:12,padding:"11px 4px",borderBottom:i<2?"1px solid var(--bdr)":"none"}}>
              <span style={{width:26,height:26,borderRadius:"50%",flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"var(--fd)",fontWeight:900,fontSize:13,background:s.done?"var(--grn)":"var(--s3)",color:s.done?"#fff":"var(--txt3)",border:"1px solid "+(s.done?"var(--grn)":"var(--bdr)")}}>{s.done?"\u2713":i+1}</span>
              <div style={{flex:1,minWidth:0}}>
                <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:800,color:s.done?"var(--txt3)":"var(--txt)"}}>{s.label}</div>
                <div style={{fontSize:11,color:"var(--txt3)"}}>{s.sub}</div>
              </div>
              {!s.done&&s.act&&<Btn v="primary" sz="sm" onClick={s.act}>{s.btn}</Btn>}
              {s.done&&<span style={{fontSize:10,fontFamily:"var(--fd)",fontWeight:800,color:"var(--grn)"}}>DONE</span>}
            </div>
          );
        })}
      </Card>
      <div style={{display:"flex",alignItems:"center",gap:10,marginTop:12,padding:"12px 14px",background:"var(--s2)",border:"1px solid var(--bdr)",borderRadius:12}}>
        <span style={{fontSize:18}}>📖</span>
        <div style={{flex:1,fontSize:12,color:"var(--txt2)",minWidth:0}}><span style={{fontFamily:"var(--fd)",fontWeight:800}}>Worth five minutes:</span> the Playbook has field-tested plays for reviews, fleet accounts, and pricing.</div>
        {goPlaybook&&<Btn v="outline" sz="sm" onClick={goPlaybook}>Open Playbook</Btn>}
      </div>
    </div>
  );

  return(
    <div className="fade">
      <div style={{marginBottom:12}}>
        <div style={{fontFamily:"var(--fd)",fontSize:24,fontWeight:900}}>WORKDAY <span style={{color:"var(--acc)"}}>DASHBOARD</span></div>
        <div style={{fontSize:11,color:"var(--txt3)"}}>{new Date().toLocaleDateString("en-US",{weekday:"long",month:"long",day:"numeric",year:"numeric"})}</div>
      </div>
      <div style={{display:"flex",gap:8,marginBottom:12}}>
        <Btn v="primary" sz="sm" style={{flex:1}} onClick={goClients}>+ New Client</Btn>
        <Btn v="subtle" sz="sm" style={{flex:1}} onClick={goVehicles}>+ New Vehicle</Btn>
        <Btn v="outline" sz="sm" style={{flex:1}} onClick={onNewJob}>+ New Job</Btn>
      </div>
      <div style={{display:"flex",gap:7,marginBottom:14,flexWrap:"wrap"}}>
        <Stat l="Today" v={tj.length} sub={done.length+" done"}/>
        <Stat l="Revenue" v={fmt$(rev)} color="var(--grn)"/>
        <Stat l="Profit" v={fmt$(prof)} color={prof>=0?"var(--grn)":"var(--red)"}/>
        <Stat l="All-Time" v={fmt$(allRev)} color="var(--cyn)" sub={customers.length+" clients"}/>
      </div>
      <Card>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
          <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900}}>UPCOMING SCHEDULE</div>
          <div style={{fontSize:10,color:"var(--txt3)",fontFamily:"var(--fd)",fontWeight:700}}>{jobs.filter(function(j){return j.status!=="completed";}).length} open jobs</div>
        </div>
        {upcoming5.length===0&&<div style={{color:"var(--txt3)",fontSize:13,padding:"16px 0",textAlign:"center"}}>No upcoming jobs.</div>}
        {upcoming5.map(function(j,idx){
          const c=customers.find(function(x){return x.id===j.customerId;})||{};
          const v=vehicles.find(function(x){return x.id===j.vehicleId;})||{};
          const vtc=VT[(v.type)]||VT.Car;
          const calc=calcJob(j);
          const isToday=j.scheduledDate===TODAY;
          return(
            <div key={j.id} onClick={function(){onSelectJob(j.id);}}
              style={{display:"flex",gap:10,alignItems:"center",padding:"10px 12px",borderRadius:"var(--r2)",background:"var(--s3)",marginBottom:6,cursor:"pointer",borderLeft:"3px solid "+(isToday?"var(--acc)":"var(--bdr2)"),transition:".15s"}}
              onMouseEnter={function(e){e.currentTarget.style.background="var(--s4)";}}
              onMouseLeave={function(e){e.currentTarget.style.background="var(--s3)";}}>
              <div style={{width:22,height:22,borderRadius:"50%",background:isToday?"var(--acc)":"var(--s4)",color:isToday?"#fff":"var(--txt3)",display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"var(--fd)",fontWeight:900,fontSize:10,flexShrink:0}}>{idx+1}</div>
              <span style={{fontSize:17,flexShrink:0}}>{vtc.icon}</span>
              <div style={{flex:1,minWidth:0}}>
                <div style={{display:"flex",alignItems:"center",gap:5,marginBottom:2,flexWrap:"wrap"}}>
                  <span style={{fontFamily:"var(--fd)",fontWeight:800,fontSize:13}}>{fullName(c)||"—"}</span>
                  {isToday&&<Chip label="TODAY" color="var(--acc)" small/>}
                  <Chip label={sLabel(j.status)} color={sColor(j.status)} small/>
                </div>
                <div style={{fontSize:11,color:"var(--txt2)",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{v.year&&v.make?v.year+" "+v.make+" "+v.model+" - ":""}{(j.services||[]).map(function(s){return s.name;}).join(", ")||"No services"}</div>
                <div style={{fontSize:10,color:"var(--txt3)",marginTop:1,fontFamily:"var(--fm)"}}>{fmtD(j.scheduledDate)}{j.scheduledTime?" at "+fmtT(j.scheduledTime):""}{j.location?" - "+j.location:""}</div>
              </div>
              <div style={{textAlign:"right",flexShrink:0}}>
                <div className="mono acc" style={{fontWeight:700,fontSize:13}}>{fmt$(calc.total)}</div>
                <div style={{fontSize:9,color:"var(--txt3)",marginTop:1}}>{(j.services||[]).reduce(function(s,sv){return s+sv.laborHours;},0).toFixed(1)+"h"}</div>
              </div>
            </div>
          );
        })}
        {jobs.filter(function(j){return j.status!=="completed";}).length>5&&<div style={{textAlign:"center",fontSize:11,color:"var(--txt3)",padding:"6px 0",fontFamily:"var(--fd)",fontWeight:700,letterSpacing:".06em"}}>+{jobs.filter(function(j){return j.status!=="completed";}).length-5} MORE</div>}
      </Card>
    </div>
  );
};

/* ══════════════════════════════════════════════════════════════════════════
   NEW JOB MODAL — 5 steps, gated Save Job, photo upload
══════════════════════════════════════════════════════════════════════════ */
const NewJobModal=({onClose,onSave,customers,vehicles,allJobs=[],archJobs=[],prefill={},settings={}})=>{
  const[step,setStep]=useState(1);
  const[f,setF]=useState({customerId:prefill.customerId||"",vehicleId:prefill.vehicleId||"",scheduledDate:prefill.scheduledDate||TODAY,scheduledTime:prefill.scheduledTime||"09:00",location:"",loggedVia:"manual",status:"upcoming",services:[],parts:[],notes:[],photos:[]});
  const defaultRate=String(+settings.laborRate||95);
  const[svc,setSvc]=useState({name:"",laborHours:"1",laborRate:defaultRate});
  const[prt,setPrt]=useState({name:"",partNumber:"",qty:"1",cost:"",sell:""});
  const[nt,setNt]=useState("");
  const photoRef=useRef();
  const[isPersonal,setIsPersonal]=useState(false);
  const set=k=>e=>setF(p=>({...p,[k]:e.target.value}));
  const cveh=vehicles.filter(v=>v.customerId===f.customerId);
  const selV=vehicles.find(v=>v.id===f.vehicleId);const vtc=VT[(selV&&selV.type)]||VT.Car;
  const addSvc=()=>{if(!svc.name.trim())return;setF(p=>({...p,services:[...p.services,{...svc,id:uid(),laborHours:+svc.laborHours,laborRate:+svc.laborRate}]}));setSvc({name:"",laborHours:"1",laborRate:defaultRate})};
  const addPrt=()=>{if(!prt.name.trim())return;setF(p=>({...p,parts:[...p.parts,{...prt,id:uid(),qty:+prt.qty,cost:+prt.cost,sell:+prt.sell}]}));setPrt({name:"",partNumber:"",qty:"1",cost:"",sell:""})};
  const addNt=()=>{if(!nt.trim())return;setF(p=>({...p,notes:[...p.notes,{id:uid(),text:nt.trim(),ts:new Date().toISOString()}]}));setNt("")};
  const handlePhotos=e=>{const files=Array.from(e.target.files).slice(0,5-f.photos.length);files.forEach(file=>{const r=new FileReader();r.onload=ev=>setF(p=>({...p,photos:[...p.photos,{id:uid(),name:file.name,url:ev.target.result}]}));r.readAsDataURL(file);});};
  const est=calcJob(f);
  const step1OK=isPersonal||!!(f.customerId&&f.vehicleId);
  const step2OK=!!(f.scheduledDate);
  const step3OK=f.services.length>0;
  const allOK=step1OK&&step2OK&&step3OK;
  const Tab=({n,l,ok})=><button onClick={()=>setStep(n)} style={{background:"none",border:"none",borderBottom:step===n?"2px solid var(--acc)":"2px solid transparent",padding:"6px 10px",fontFamily:"var(--fd)",fontSize:11,fontWeight:800,cursor:"pointer",color:step===n?"var(--acc)":"var(--txt3)",letterSpacing:".07em",position:"relative"}}><span style={{background:step===n?"var(--acc)":ok?"var(--grn)":"var(--s3)",color:step===n||ok?"#fff":"var(--txt3)",borderRadius:"50%",width:15,height:15,display:"inline-flex",alignItems:"center",justifyContent:"center",fontSize:8,marginRight:3}}>{ok&&step!==n?"v":n}</span>{l}</button>;
  const BottomNav=()=>(<div style={{display:"grid",gridTemplateColumns:"1fr auto 1fr",alignItems:"center",gap:8,marginTop:16,borderTop:"1px solid var(--bdr)",paddingTop:12}}>
    <div>{step>1&&<Btn v="ghost" onClick={()=>setStep(s=>s-1)}>« Back</Btn>}</div>
    {allOK&&<Btn v="primary" sz="lg" onClick={()=>{const jid=isPersonal?"PERSONAL":genJobId(f.vehicleId,allJobs.concat(archJobs));onSave({...f,id:uid(),jobId:jid,isPersonal});onClose();}}>SAVE JOB</Btn>}
    {!allOK&&<div style={{fontSize:11,color:"var(--txt3)",textAlign:"center",fontFamily:"var(--fd)"}}>Complete steps 1–3 to save</div>}
    <div style={{textAlign:"right"}}>{step<5&&<Btn v="outline" onClick={()=>setStep(s=>s+1)}>Next &gt;</Btn>}</div>
  </div>);
  return(
    <Modal title="LOG NEW JOB" wide onClose={onClose}>
      <div style={{display:"flex",borderBottom:"1px solid var(--bdr)",marginBottom:14}}>
        <Tab n={1} l="Client & Vehicle" ok={step1OK}/>
        <Tab n={2} l="Schedule" ok={step2OK}/>
        <Tab n={3} l="Services & Parts" ok={step3OK}/>
        <Tab n={4} l="Notes" ok={f.notes.length>0}/>
        <Tab n={5} l="Photos" ok={f.photos.length>0}/>
      </div>
      {step===1&&<div className="fade" style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
        {/* Personal scheduling toggle */}
        <div style={{gridColumn:"1/-1",padding:"10px 14px",background:isPersonal?"var(--pur)14":"var(--s3)",border:`1px solid ${isPersonal?"var(--pur)66":"var(--bdr)"}`,borderRadius:"var(--r2)",transition:".2s"}}>
          <label className="cb" style={{gap:10,cursor:"pointer"}}>
            <input type="checkbox" checked={isPersonal} onChange={e=>{setIsPersonal(e.target.checked);if(e.target.checked)setF(p=>({...p,customerId:"",vehicleId:""}));}} style={{width:16,height:16,accentColor:"var(--pur)"}}/>
            <div>
              <div style={{fontFamily:"var(--fd)",fontSize:13,fontWeight:800,color:isPersonal?"var(--pur)":"var(--txt2)"}}>Personal / No Client</div>
              <div style={{fontSize:11,color:"var(--txt3)"}}>Marks as personal time on calendar — no client or vehicle required</div>
            </div>
          </label>
        </div>
        {!isPersonal&&<><FG label="Client" required span={2}><select value={f.customerId} onChange={set("customerId")}><option value="">— Select client —</option>{customers.map(c=><option key={dispCustId(c.id)} value={dispCustId(c.id)}>{fullName(c)} · {dispCustId(c.id)}</option>)}</select></FG>
        {f.customerId&&<FG label="Vehicle" required span={2}><select value={f.vehicleId} onChange={set("vehicleId")}><option value="">— Select vehicle —</option>{cveh.map(v=><option key={v.id} value={v.id}>{(VT[v.type]&&VT[v.type].icon)||"🚗"} {v.year} {v.make} {v.model} ({v.type})</option>)}</select></FG>}
        {selV&&<div style={{gridColumn:"1/-1",padding:"9px 12px",background:`${vtc.color}14`,border:`1px solid ${vtc.color}44`,borderRadius:"var(--r2)",display:"flex",gap:10,alignItems:"center"}}><span style={{fontSize:22}}>{vtc.icon}</span><div><div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:700}}>{selV.year} {selV.make} {selV.model}</div><div style={{fontSize:11,color:"var(--txt2)"}}>{selV.engine?`⚙️ ${selV.engine}  `:""}{selV.driveType?`🔄 ${selV.driveType}  `:""}{selV.fuelType?`⛽ ${selV.fuelType}`:""}</div></div><Chip label={selV.type} color={vtc.color}/>{selV.vehicleId&&<span className="mono" style={{fontSize:10,color:"var(--txt3)",marginLeft:"auto"}}>{dispVehId(selV.vehicleId)}</span>}</div>}
        {customers.length===0&&<div style={{gridColumn:"1/-1",padding:"10px",background:"var(--s3)",borderRadius:"var(--r)",fontSize:12,color:"var(--ylw)"}}>⚠️ No clients on file. Add a client first.</div>}</>}
        {isPersonal&&<div style={{gridColumn:"1/-1",padding:"10px 14px",background:"var(--pur)0a",borderRadius:"var(--r)",fontSize:12,color:"var(--pur)"}}>🟣 This time block will appear in purple on your schedule calendar.</div>}
      </div>}
      {step===2&&<div className="fade" style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12}}>
        <FG label="Service Date" required><input type="date" value={f.scheduledDate} onChange={set("scheduledDate")}/></FG>
        <FG label="Scheduled Time"><input type="time" value={f.scheduledTime} onChange={set("scheduledTime")}/></FG>
        <FG label="Job Location / Address" span={2}><input value={f.location} onChange={set("location")} placeholder="Client address or job site"/></FG>
        <FG label="Odometer (miles)" span={2}><input type="number" value={f.odometer||""} onChange={set("odometer")} min="0" placeholder="Current mileage — used for service reminders and warranties"/></FG>
        <FG label="Job Status"><select value={f.status} onChange={set("status")}><option value="upcoming">Upcoming</option><option value="in-progress">In Progress</option><option value="completed">Completed</option></select></FG>
        <FG label="Logged Via"><select value={f.loggedVia} onChange={set("loggedVia")}><option value="manual">✏️ Manual</option><option value="call">📞 Phone Call</option><option value="email">📧 Email</option></select></FG>
      </div>}
      {step===3&&<div className="fade">
        {/* ── SERVICES ── */}
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
          <div style={{fontFamily:"var(--fd)",fontSize:13,fontWeight:900,letterSpacing:".08em",color:"var(--txt2)"}}>SERVICES <span style={{color:"var(--red)",fontSize:10,fontWeight:600}}>* at least 1 required to save</span></div>
        </div>
        {f.services.map(s=>(
          <div key={s.id} style={{display:"flex",alignItems:"center",gap:8,padding:"8px 12px",background:"var(--s3)",borderRadius:"var(--r)",marginBottom:5,borderLeft:"3px solid var(--grn)"}}>
            <div style={{flex:1,fontSize:13,fontWeight:600}}>{s.name}</div>
            <div style={{fontSize:11,color:"var(--txt3)",fontFamily:"var(--fm)",whiteSpace:"nowrap"}}>{s.laborHours}h @ ${s.laborRate}/hr</div>
            <div className="mono acc" style={{fontWeight:700,fontSize:12,minWidth:54,textAlign:"right"}}>{fmt$(s.laborHours*s.laborRate)}</div>
            <button aria-label="Remove" title="Remove" onClick={()=>setF(p=>({...p,services:p.services.filter(x=>x.id!==s.id)}))} style={{background:"none",border:"none",color:"var(--red)",cursor:"pointer",fontSize:14,padding:"0 2px",lineHeight:1}}>x</button>
          </div>
        ))}
        <div style={{background:"var(--s2)",border:"1px solid var(--bdr)",borderRadius:"var(--r2)",padding:"14px",marginBottom:4}}>
          <div style={{display:"grid",gridTemplateColumns:"1fr 80px 80px",gap:10,marginBottom:10}}>
            <div>
              <Lbl>Service Description</Lbl>
              <input value={svc.name} onChange={e=>setSvc(s=>({...s,name:e.target.value}))} placeholder="e.g. Brake Pad Replacement" onKeyDown={e=>e.key==="Enter"&&addSvc()}/>
            </div>
            <div>
              <Lbl>Hours</Lbl>
              <input value={svc.laborHours} onChange={e=>setSvc(s=>({...s,laborHours:e.target.value}))} placeholder="1.0" type="number" min="0" step=".25"/>
            </div>
            <div>
              <Lbl>$/hr</Lbl>
              <input value={svc.laborRate} onChange={e=>setSvc(s=>({...s,laborRate:e.target.value}))} placeholder={defaultRate} type="number" min="0"/>
            </div>
          </div>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
            <Btn v="outline" sz="sm" onClick={addSvc}>+ Add Service</Btn>
            {svc.name&&<div className="mono" style={{fontSize:12,color:"var(--acc)",fontWeight:700}}>Est: {fmt$(+svc.laborHours * +svc.laborRate)}</div>}
          </div>
        </div>
        <Divider m="16px 0"/>
        {/* ── PARTS ── */}
        <div style={{fontFamily:"var(--fd)",fontSize:13,fontWeight:900,letterSpacing:".08em",color:"var(--txt2)",marginBottom:8}}>PARTS <span style={{fontSize:10,color:"var(--txt3)",fontWeight:600}}>(optional)</span></div>
        {f.parts.map(p=>(
          <div key={p.id} style={{display:"flex",alignItems:"center",gap:8,padding:"8px 12px",background:"var(--s3)",borderRadius:"var(--r)",marginBottom:5,borderLeft:"3px solid var(--blu)"}}>
            <div style={{flex:1,fontSize:13,fontWeight:600}}>{p.name}</div>
            {p.partNumber&&<div className="mono" style={{fontSize:10,color:"var(--txt3)"}}>#{p.partNumber}</div>}
            <div style={{fontSize:11,color:"var(--txt3)"}}>×{p.qty}</div>
            <div className="mono acc" style={{fontWeight:700,fontSize:12,minWidth:54,textAlign:"right"}}>{fmt$(p.sell)}</div>
            <button aria-label="Remove" title="Remove" onClick={()=>setF(p2=>({...p2,parts:p2.parts.filter(x=>x.id!==p.id)}))} style={{background:"none",border:"none",color:"var(--red)",cursor:"pointer",fontSize:14,padding:"0 2px",lineHeight:1}}>x</button>
          </div>
        ))}
        <div style={{background:"var(--s2)",border:"1px solid var(--bdr)",borderRadius:"var(--r2)",padding:"14px",marginBottom:4}}>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:10}}>
            <div><Lbl>Part Name</Lbl><input value={prt.name} onChange={e=>setPrt(p=>({...p,name:e.target.value}))} placeholder="e.g. Oil Filter, Brake Pads"/></div>
            <div><Lbl>Part Number</Lbl><input value={prt.partNumber} onChange={e=>setPrt(p=>({...p,partNumber:e.target.value}))} placeholder="e.g. FL820S" style={{fontFamily:"var(--fm)",fontSize:12}}/></div>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"80px 1fr 1fr",gap:10,marginBottom:10}}>
            <div><Lbl>Qty</Lbl><input value={prt.qty} onChange={e=>setPrt(p=>({...p,qty:e.target.value}))} type="number" min="1"/></div>
            <div><Lbl>Sell Price ($)</Lbl><input value={prt.sell} onChange={e=>setPrt(p=>({...p,sell:e.target.value}))} placeholder="0.00" type="number" min="0"/></div>
            <div>
              <Lbl>Shop Cost ($)</Lbl>
              <input value={prt.cost} onChange={e=>setPrt(p=>({...p,cost:e.target.value}))} placeholder="0.00" type="number" min="0" style={{borderColor:"var(--bdr2)",background:"var(--s4)"}}/>
              <div style={{fontSize:9,color:"var(--txt3)",marginTop:2}}>Internal only</div>
            </div>
          </div>
          <Btn v="outline" sz="sm" onClick={addPrt}>+ Add Part</Btn>
        </div>
        {(f.services.length>0||f.parts.length>0)&&<div style={{marginTop:10,padding:"10px 14px",background:"var(--s3)",borderRadius:"var(--r2)",display:"flex",gap:20,fontSize:13}}>
          <span>Est. Invoice: <span className="mono acc" style={{fontWeight:700}}>{fmt$(est.total)}</span></span>
          <span>Est. Profit: <span className={"mono "+(est.profit>=0?"grn":"red")} style={{fontWeight:700}}>{fmt$(est.profit)}</span></span>
        </div>}
      </div>}
      {step===4&&<div className="fade">
        <div style={{fontFamily:"var(--fd)",fontSize:13,fontWeight:800,marginBottom:8}}>JOB NOTES <span style={{color:"var(--txt3)",fontWeight:600}}>(optional)</span></div>
        {f.notes.map(n=><div key={n.id} style={{padding:"7px 10px",background:"var(--s3)",borderLeft:"3px solid var(--ylw)",borderRadius:"var(--r)",marginBottom:5,fontSize:12}}>{n.text}</div>)}
        <div style={{display:"flex",gap:7}}><textarea value={nt} onChange={e=>setNt(e.target.value)} placeholder="Notes, diagnostics, customer requests…"/><Btn v="primary" onClick={addNt} style={{alignSelf:"flex-end",whiteSpace:"nowrap"}}>Add Note</Btn></div>
      </div>}
      {step===5&&<div className="fade">
        <div style={{fontFamily:"var(--fd)",fontSize:13,fontWeight:800,marginBottom:4}}>UPLOAD JOB PHOTOS <span style={{color:"var(--txt3)",fontWeight:600}}>(optional · up to 5)</span></div>
        <div style={{fontSize:12,color:"var(--txt3)",marginBottom:14}}>Photos will be attached to this job record and included in any reports generated.</div>
        <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:14}}>
          {f.photos.map(p=>(
            <div key={p.id} style={{position:"relative"}}>
              <img src={p.url} alt={p.name} className="photo-thumb"/>
              <button aria-label="Remove" title="Remove" onClick={()=>setF(prev=>({...prev,photos:prev.photos.filter(ph=>ph.id!==p.id)}))} style={{position:"absolute",top:-6,right:-6,background:"var(--red)",border:"none",borderRadius:"50%",width:18,height:18,display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",fontSize:10,color:"#fff",fontWeight:900}}>x</button>
            </div>
          ))}
          {f.photos.length<5&&(
            <div onClick={()=>photoRef.current.click()} style={{width:72,height:72,border:"1.5px dashed var(--bdr)",borderRadius:"var(--r)",display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",flexDirection:"column",gap:3,color:"var(--txt3)",fontSize:10,fontFamily:"var(--fd)",fontWeight:700,background:"var(--s3)"}}>
              <span style={{fontSize:22}}>📷</span>ADD
            </div>
          )}
          <input type="file" ref={photoRef} accept="image/*" multiple style={{display:"none"}} onChange={handlePhotos}/>
        </div>
        <div style={{fontSize:11,color:"var(--txt3)",padding:"8px 12px",background:"var(--s3)",borderRadius:"var(--r)"}}>{f.photos.length} of 5 photos uploaded. Tap a photo's x to remove it.</div>
      </div>}
      <BottomNav/>
    </Modal>
  );
};

/* ── PARTS LOOKUP ─────────────────────────────────────────────────────────── */
const PartsLookup=({vehicles=[],customers=[],quotes=[],setQuotes,logAction})=>{
  const[q,setQ]=useState("");
  const[vehId,setVehId]=useState("");
  const[qf,setQf]=useState({part:"",supplier:"RockAuto",price:"",partNum:""});
  const setQfK=function(k){return function(e){var v=e.target.value;setQf(function(p){var n=Object.assign({},p);n[k]=v;return n;});};};
  var veh=vehicles.find(function(v){return v.id===vehId;});
  var term=((veh?((veh.year||"")+" "+(veh.make||"")+" "+(veh.model||"")+" "):"")+q).trim();
  const SUPPLIERS=[
    {n:"RockAuto",col:"#22c55e",u:function(t){return "https://www.rockauto.com/en/partsearch/?partname="+encodeURIComponent(t);}},
    {n:"AutoZone",col:"#ef4444",u:function(t){return "https://www.autozone.com/searchresult?searchText="+encodeURIComponent(t);}},
    {n:"O'Reilly",col:"#f97316",u:function(t){return "https://www.oreillyauto.com/search?q="+encodeURIComponent(t);}},
    {n:"NAPA",col:"#3b82f6",u:function(t){return "https://www.napaonline.com/search?query="+encodeURIComponent(t);}},
    {n:"Amazon",col:"#eab308",u:function(t){return "https://www.amazon.com/s?k="+encodeURIComponent(t);}}
  ];
  const addQuote=function(){
    if(!qf.part.trim()||!qf.price)return;
    var e={id:uid(),date:TODAY,part:qf.part.trim(),supplier:qf.supplier,price:+qf.price||0,partNum:qf.partNum.trim(),vehicleId:vehId||null};
    setQuotes(function(p){return [e].concat(p);});
    if(logAction)logAction("part_quote_logged","part","",e.part+" quote \u2014 "+e.supplier+" "+fmt$(e.price));
    setQf(function(p){return Object.assign({},p,{price:"",partNum:""});});
  };
  const delQuote=function(id){setQuotes(function(p){return p.filter(function(x){return x.id!==id;});});};
  var best={};var counts={};
  quotes.forEach(function(x){var k=(x.part||"").toLowerCase();counts[k]=(counts[k]||0)+1;if(!(k in best)||x.price<best[k])best[k]=x.price;});
  return(
    <div className="fade" style={{paddingBottom:24}}>
      <div style={{fontFamily:"var(--fd)",fontSize:26,fontWeight:900,marginBottom:4}}>PARTS <span style={{color:"var(--acc)"}}>SOURCING</span></div>
      <div style={{fontSize:12,color:"var(--txt3)",marginBottom:14}}>Search suppliers directly, then log the real quotes you get. Prices and availability are set by the suppliers {"\u2014"} links open their sites in a new tab.</div>
      <Card style={{marginBottom:14}}>
        <div style={{display:"grid",gridTemplateColumns:vehicles.length>0?"220px 1fr":"1fr",gap:8,marginBottom:10}}>
          {vehicles.length>0&&<FG label="Vehicle context (optional)">
            <select value={vehId} onChange={function(e){setVehId(e.target.value);}}>
              <option value="">No vehicle</option>
              {vehicles.map(function(v){var c=customers.find(function(x){return x.id===v.customerId;});return <option key={v.id} value={v.id}>{(v.year||"")+" "+(v.make||"")+" "+(v.model||"")+(c?" \u2014 "+fullName(c):"")}</option>;})}
            </select>
          </FG>}
          <FG label="Part name or number">
            <input value={q} onChange={function(e){setQ(e.target.value);}} placeholder="e.g. front brake pads, FL820S, serpentine belt" onKeyDown={function(e){if(e.key==="Enter"&&term&&SUPPLIERS[0])window.open(SUPPLIERS[0].u(term),"_blank","noopener,noreferrer");}}/>
          </FG>
        </div>
        <Lbl>Open the search on:</Lbl>
        <div style={{display:"flex",gap:7,flexWrap:"wrap",marginTop:4}}>
          {SUPPLIERS.map(function(s){
            return <button key={s.n} disabled={!term} onClick={function(){if(term)window.open(s.u(term),"_blank","noopener,noreferrer");}} style={{padding:"7px 15px",borderRadius:"var(--r2)",border:"1px solid "+(term?s.col:"var(--bdr)"),background:term?s.col+"16":"var(--s3)",color:term?s.col:"var(--txt3)",fontSize:12,fontFamily:"var(--fd)",fontWeight:800,cursor:term?"pointer":"default",transition:".15s"}}>{s.n} {"\u2197"}</button>;
          })}
        </div>
        {!term&&<div style={{fontSize:10,color:"var(--txt3)",marginTop:8}}>Type a part above (and pick a vehicle for a smarter search) to light up the supplier buttons.</div>}
      </Card>
      <Card style={{marginBottom:14}}>
        <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900,marginBottom:10}}>LOG A QUOTE</div>
        <div style={{display:"grid",gridTemplateColumns:"1.4fr 1fr 130px 110px auto",gap:8,alignItems:"end"}}>
          <FG label="Part"><input value={qf.part} onChange={setQfK("part")} placeholder="Front brake pads"/></FG>
          <FG label="Part #"><input value={qf.partNum} onChange={setQfK("partNum")} placeholder="Optional" style={{fontFamily:"var(--fm)",fontSize:11}}/></FG>
          <FG label="Supplier"><select value={qf.supplier} onChange={setQfK("supplier")}>{SUPPLIERS.map(function(s){return <option key={s.n} value={s.n}>{s.n}</option>;})}<option value="Dealer">Dealer</option><option value="Other">Other</option></select></FG>
          <FG label="Price"><input type="number" step="0.01" min="0" value={qf.price} onChange={setQfK("price")} placeholder="0.00" onKeyDown={function(e){if(e.key==="Enter")addQuote();}}/></FG>
          <Btn v="primary" sz="md" onClick={addQuote} disabled={!qf.part.trim()||!qf.price}>Add</Btn>
        </div>
        <div style={{fontSize:10,color:"var(--txt3)",marginTop:8}}>Log 2-3 quotes per part \u2014 the best price gets flagged automatically, with a suggested sell at 40% margin.</div>
      </Card>
      {quotes.length>0&&<Card>
        <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900,marginBottom:10}}>QUOTE LOG <span style={{color:"var(--txt3)",fontWeight:600,fontSize:11}}>({quotes.length})</span></div>
        <div className="tbl-scroll">
          <table>
            <thead><tr><th>Date</th><th>Part</th><th>Part #</th><th>Supplier</th><th style={{textAlign:"right"}}>Price</th><th style={{textAlign:"right"}}>Sell @40%</th><th>Vehicle</th><th></th></tr></thead>
            <tbody>
              {quotes.map(function(x){
                var k=(x.part||"").toLowerCase();
                var isBest=counts[k]>1&&x.price===best[k];
                var xv=vehicles.find(function(v){return v.id===x.vehicleId;});
                var sup=SUPPLIERS.find(function(s){return s.n===x.supplier;});
                return(
                  <tr key={x.id}>
                    <td className="mono" style={{fontSize:11,color:"var(--txt3)"}}>{fmtD(x.date)}</td>
                    <td style={{fontWeight:600}}>{x.part}{isBest&&<span style={{marginLeft:7,background:"var(--grn)",color:"#fff",fontSize:8,fontFamily:"var(--fd)",fontWeight:900,padding:"1px 6px",borderRadius:8,verticalAlign:"middle"}}>BEST</span>}</td>
                    <td className="mono" style={{fontSize:11,color:"var(--txt3)"}}>{x.partNum||"\u2014"}</td>
                    <td><span style={{color:sup?sup.col:"var(--txt2)",fontFamily:"var(--fd)",fontWeight:700,fontSize:12}}>{x.supplier}</span></td>
                    <td className="mono" style={{textAlign:"right",color:isBest?"var(--grn)":"var(--txt)",fontWeight:isBest?700:400}}>{fmt$(x.price)}</td>
                    <td className="mono" style={{textAlign:"right",color:"var(--grn)"}}>{fmt$(x.price/0.6)}</td>
                    <td style={{fontSize:11,color:"var(--txt3)"}}>{xv?((xv.year||"")+" "+(xv.make||"")+" "+(xv.model||"")):"\u2014"}</td>
                    <td><button aria-label="Remove" title="Remove" onClick={function(){delQuote(x.id);}} style={{background:"none",border:"none",color:"var(--txt3)",cursor:"pointer",fontSize:14}}>x</button></td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </Card>}
    </div>
  );
};
/* ── TEMPLATES PAGE (with AI Describe Repair) ─────────────────────────────── */
