/* ══════════════════════════════════════════════════════════════════════════
   SCHEDULE PAGE — weekly calendar
══════════════════════════════════════════════════════════════════════════ */
const SchedulePage=({jobs,customers,vehicles,onSelectJob,onNewJob,blocks,setBlocks})=>{
  const[monthOffset,setMonthOffset]=useState(0);
  const[selDate,setSelDate]=useState(TODAY);
  const[blockModal,setBlockModal]=useState(false);
  const[blockForm,setBlockForm]=useState({label:"",startTime:"08:00",endTime:"17:00",color:"ylw"});
  const[blockErr,setBlockErr]=useState("");
  const[view,setView]=useState("month");

  const now=new Date();
  const displayMonth=new Date(now.getFullYear(),now.getMonth()+monthOffset,1);
  const yr=displayMonth.getFullYear();
  const mo=displayMonth.getMonth();
  const MONTHS=["January","February","March","April","May","June","July","August","September","October","November","December"];
  const DOW_HDR=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
  const firstDow=new Date(yr,mo,1).getDay();
  const daysInMo=new Date(yr,mo+1,0).getDate();
  const prevDays=new Date(yr,mo,0).getDate();
  const isoDate=function(y,m2,d){return y+"-"+String(m2+1).padStart(2,"0")+"-"+String(d).padStart(2,"0");};

  const jobsByDate=useMemo(function(){var m={};jobs.forEach(function(j){if(!m[j.scheduledDate])m[j.scheduledDate]=[];m[j.scheduledDate].push(j);});return m;},[jobs]);
  const blocksByDate=useMemo(function(){var m={};blocks.forEach(function(b){if(!m[b.date])m[b.date]=[];m[b.date].push(b);});return m;},[blocks]);

  // Day detail data — sorted chronologically
  const selJobs=(jobsByDate[selDate]||[]).slice().sort(function(a,b){return(a.scheduledTime||"")>(b.scheduledTime||"")?1:-1;});
  const selBlocks=(blocksByDate[selDate]||[]).slice().sort(function(a,b){return(a.startTime||"")>(b.startTime||"")?1:-1;});
  var selDayItems=[];
  selJobs.forEach(function(j){selDayItems.push({kind:"job",time:j.scheduledTime||"00:00",data:j});});
  selBlocks.forEach(function(b){selDayItems.push({kind:"block",time:b.startTime||"00:00",data:b});});
  selDayItems.sort(function(a,b){return a.time>b.time?1:-1;});
  var routeStops=selJobs.filter(function(j2){return j2.location&&String(j2.location).trim();}).map(function(j2){return j2.location;});
  var openRoute=function(){var u=routeUrl(routeStops);if(u)window.open(u,"_blank","noopener,noreferrer");};

  const BLOCK_COLORS={
    ylw:{hex:"#eab308",label:"Break / Personal"},
    red:{hex:"#ef4444",label:"Unavailable"},
    pur:{hex:"#a855f7",label:"Admin / Office"},
    cyn:{hex:"#06b6d4",label:"Parts Run"},
    grn:{hex:"#22c55e",label:"Training"},
  };

  // Job color: use vehicle-type color for visual variety, fallback to status color
  const jobColor=function(j){
    if(j.isPersonal)return"#a855f7";
    var v=vehicles.find(function(x){return x.id===j.vehicleId;});
    if(v&&VT[v.type])return VT[v.type].color;
    return sColor(j.status);
  };

  const saveBlock=function(){
    if(!blockForm.label.trim()){setBlockErr("Please enter a label.");return;}
    setBlocks(function(prev){return[...prev,{id:uid(),date:selDate,label:blockForm.label.trim(),startTime:blockForm.startTime,endTime:blockForm.endTime,color:blockForm.color}];});
    setBlockForm({label:"",startTime:"08:00",endTime:"17:00",color:"ylw"});
    setBlockErr("");setBlockModal(false);
  };
  const removeBlock=function(id){if(window.confirm("Remove this time block?"))setBlocks(function(prev){return prev.filter(function(b){return b.id!==id;});});};

  // Calendar grid cells
  var cells=[];
  for(var i=0;i<firstDow;i++){cells.push({type:"prev",day:prevDays-firstDow+1+i});}
  for(var dd=1;dd<=daysInMo;dd++){cells.push({type:"cur",day:dd,date:isoDate(yr,mo,dd)});}
  var rem=(7-cells.length%7)%7;
  for(var i2=0;i2<rem;i2++){cells.push({type:"next",day:i2+1});}

  // Month summary stats
  var moJobs=0;var moRev=0;
  var moPrefix=yr+"-"+String(mo+1).padStart(2,"0");
  for(var ds2 in jobsByDate){if(ds2.startsWith(moPrefix)){jobsByDate[ds2].forEach(function(j){moJobs++;if(j.status==="completed")moRev+=calcJob(j).total;});}}

  // Selected date label
  var selDateObj=new Date(selDate+"T12:00:00");
  var selIsToday=selDate===TODAY;
  var selLabel=selIsToday?"Today":selDateObj.toLocaleDateString("en-US",{weekday:"long",month:"short",day:"numeric"});

  // ── Agenda view data ──
  var agendaSorted=jobs.slice().sort(function(a,b){var ka=(a.scheduledDate||"")+"T"+(a.scheduledTime||"00:00");var kb=(b.scheduledDate||"")+"T"+(b.scheduledTime||"00:00");return ka>kb?1:-1;});
  var agOverdue=agendaSorted.filter(function(j){return(j.scheduledDate||"")<TODAY&&j.status!=="completed";});
  var agUpcoming=agendaSorted.filter(function(j){return(j.scheduledDate||"")>=TODAY;});
  var agGroups=[];var agCur=null;
  agUpcoming.forEach(function(j){if(!agCur||agCur.date!==j.scheduledDate){agCur={date:j.scheduledDate,items:[]};agGroups.push(agCur);}agCur.items.push(j);});
  var agTomorrow=(function(){var t=new Date();t.setDate(t.getDate()+1);return t.getFullYear()+"-"+String(t.getMonth()+1).padStart(2,"0")+"-"+String(t.getDate()).padStart(2,"0");})();
  var agLabel=function(ds){if(ds===TODAY)return"Today";if(ds===agTomorrow)return"Tomorrow";var d=new Date(ds+"T12:00:00");return d.toLocaleDateString("en-US",{weekday:"long",month:"short",day:"numeric"});};
  var renderAgendaRow=function(j){
    var c=customers.find(function(x){return x.id===j.customerId;})||{};
    var v=vehicles.find(function(x){return x.id===j.vehicleId;})||{};
    var vtc=VT[v.type]||VT.Car;
    var jc=jobColor(j);
    var tot=calcJob(j).total;
    var svc=(j.services||[]).map(function(s){return s.name;}).join(", ");
    var vehStr=v.make?((v.year||"")+" "+v.make+" "+(v.model||"")):"";
    return(
      <div key={j.id} onClick={function(){onSelectJob(j.id);}} style={{display:"flex",alignItems:"center",gap:10,background:"var(--s2)",border:"1px solid var(--bdr)",borderLeft:"4px solid "+jc,borderRadius:10,padding:"10px 12px",cursor:"pointer",marginBottom:7}} onMouseEnter={function(e){e.currentTarget.style.background="var(--s3)";}} onMouseLeave={function(e){e.currentTarget.style.background="var(--s2)";}}>
        <div style={{fontFamily:"var(--fm)",fontSize:11,color:"var(--txt2)",flexShrink:0,minWidth:42,textAlign:"center"}}>{j.scheduledTime?fmtT(j.scheduledTime):"--"}</div>
        <span style={{fontSize:19,flexShrink:0}}>{vtc.icon}</span>
        <div style={{flex:1,minWidth:0}}>
          <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:800,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{j.isPersonal?"Personal Time":(fullName(c)||"Unassigned")}</div>
          <div style={{fontSize:11,color:"var(--txt3)",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{vehStr}{vehStr&&svc?"  \u00b7  ":""}{svc}</div>
        </div>
        <div style={{textAlign:"right",flexShrink:0}}>
          <Chip label={j.isPersonal?"Personal":sLabel(j.status)} color={jc} small/>
          {!j.isPersonal&&<div className="mono" style={{fontSize:12,color:"var(--grn)",fontWeight:700,marginTop:3}}>{fmt$(tot)}</div>}
        </div>
      </div>
    );
  };

  return(
    <div className="fade" style={{paddingBottom:32}}>

      {/* ── Time Block Modal ── */}
      {blockModal&&(
        <div style={{position:"fixed",inset:0,background:"#000d",zIndex:400,display:"flex",alignItems:"center",justifyContent:"center",padding:16}} onClick={function(e){if(e.target===e.currentTarget)setBlockModal(false);}}>
          <div className="pop" style={{background:"var(--s1)",border:"1px solid var(--bdr)",borderRadius:16,padding:"24px 22px",width:"100%",maxWidth:380,boxShadow:"0 24px 80px #000e"}}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:16}}>
              <div>
                <div style={{fontFamily:"var(--fd)",fontSize:18,fontWeight:900}}>ADD TIME BLOCK</div>
                <div style={{fontSize:11,color:"var(--acc)",fontFamily:"var(--fm)",marginTop:2}}>{selDateObj.toLocaleDateString("en-US",{weekday:"long",month:"long",day:"numeric",year:"numeric"})}</div>
              </div>
              <button aria-label="Remove" title="Remove" onClick={function(){setBlockModal(false);}} style={{background:"var(--s3)",border:"1px solid var(--bdr)",borderRadius:"50%",width:28,height:28,cursor:"pointer",color:"var(--txt3)",fontSize:14,display:"flex",alignItems:"center",justifyContent:"center"}}>x</button>
            </div>
            <div style={{display:"grid",gap:12}}>
              <div>
                <Lbl>Label / Reason *</Lbl>
                <input value={blockForm.label} onChange={function(e){setBlockForm(function(p){return Object.assign({},p,{label:e.target.value});});setBlockErr("");}} placeholder="e.g. Lunch Break, Parts Run, Personal Time..." autoFocus onKeyDown={function(e){if(e.key==="Enter")saveBlock();}}/>
              </div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
                <div><Lbl>Start Time</Lbl><input type="time" value={blockForm.startTime} onChange={function(e){setBlockForm(function(p){return Object.assign({},p,{startTime:e.target.value});});}}/></div>
                <div><Lbl>End Time</Lbl><input type="time" value={blockForm.endTime} onChange={function(e){setBlockForm(function(p){return Object.assign({},p,{endTime:e.target.value});});}}/></div>
              </div>
              <div>
                <Lbl>Category</Lbl>
                <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
                  {Object.entries(BLOCK_COLORS).map(function(entry){
                    var k=entry[0];var v=entry[1];var sel=blockForm.color===k;
                    return(
                      <button key={k} onClick={function(){setBlockForm(function(p){return Object.assign({},p,{color:k});});}}
                        style={{padding:"5px 12px",borderRadius:20,border:"2px solid "+(sel?v.hex:"var(--bdr)"),background:sel?v.hex+"22":"var(--s3)",color:sel?v.hex:"var(--txt3)",fontSize:11,fontFamily:"var(--fd)",fontWeight:700,cursor:"pointer",transition:".15s"}}>
                        {v.label}
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>
            {blockErr&&<div style={{fontSize:12,color:"var(--red)",padding:"7px 11px",background:"var(--red)14",border:"1px solid var(--red)44",borderRadius:"var(--r)",marginTop:10}}>{blockErr}</div>}
            <div style={{fontSize:11,color:"var(--txt3)",background:"var(--s3)",border:"1px solid var(--bdr)",borderRadius:"var(--r)",padding:"8px 12px",marginTop:12}}>
              Saved immediately. Navigate freely — this block persists on your calendar.
            </div>
            <div style={{display:"flex",gap:8,marginTop:14,paddingTop:12,borderTop:"1px solid var(--bdr)"}}>
              <Btn v="ghost" full onClick={function(){setBlockModal(false);}}>Cancel</Btn>
              <Btn v="primary" full onClick={saveBlock}>Save Time Block</Btn>
            </div>
          </div>
        </div>
      )}

      {/* ── Page Header ── */}
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:16,flexWrap:"wrap",gap:10}}>
        <div>
          <div style={{fontFamily:"var(--fd)",fontSize:26,fontWeight:900}}>MY <span style={{color:"var(--acc)"}}>SCHEDULE</span></div>
          <div style={{fontSize:11,color:"var(--txt3)",marginTop:2}}>{MONTHS[mo]} {yr} &nbsp;&middot;&nbsp; {moJobs} job{moJobs!==1?"s":""} &nbsp;&middot;&nbsp; {blocks.length} time block{blocks.length!==1?"s":""}</div>
        </div>
        <div style={{display:"flex",gap:7}}>
          <Btn v="primary" sz="sm" onClick={function(){onNewJob({scheduledDate:selDate});}}>+ New Job</Btn>
          <Btn v="subtle" sz="sm" onClick={function(){setBlockModal(true);}}>+ Time Block</Btn>
        </div>
      </div>

      {/* View toggle */}
      <div style={{display:"flex",gap:0,marginBottom:14,background:"var(--s2)",border:"1px solid var(--bdr)",borderRadius:10,padding:3,width:"fit-content"}}>
        {[["month","Month"],["agenda","Agenda"]].map(function(tg){var active=view===tg[0];return(
          <button key={tg[0]} onClick={function(){setView(tg[0]);}} style={{padding:"6px 20px",borderRadius:8,border:"none",cursor:"pointer",fontFamily:"var(--fd)",fontSize:12,fontWeight:800,letterSpacing:".04em",background:active?"var(--acc)":"transparent",color:active?"#fff":"var(--txt3)",transition:".15s"}}>{tg[1]}</button>
        );})}
      </div>
      {view==="month"&&(<>
      {/* ══════════════════════════════════════
          CALENDAR
      ══════════════════════════════════════ */}
      <div style={{background:"var(--s1)",border:"1px solid var(--bdr)",borderRadius:14,overflow:"hidden",marginBottom:16}}>
        {/* Month navigation */}
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"11px 16px",borderBottom:"1px solid var(--bdr)"}}>
          <button onClick={function(){setMonthOffset(function(o){return o-1;});}} style={{background:"var(--s3)",border:"1px solid var(--bdr)",borderRadius:8,width:32,height:32,cursor:"pointer",color:"var(--txt2)",fontSize:16,fontWeight:900,display:"flex",alignItems:"center",justifyContent:"center"}} title="Previous month">{"<"}</button>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <span style={{fontFamily:"var(--fd)",fontSize:16,fontWeight:900,letterSpacing:".04em"}}>{MONTHS[mo].toUpperCase()} {yr}</span>
            {monthOffset!==0&&<button onClick={function(){setMonthOffset(0);setSelDate(TODAY);}} style={{background:"var(--acc)18",border:"1px solid var(--acc)55",borderRadius:20,padding:"3px 10px",fontSize:10,fontFamily:"var(--fd)",fontWeight:800,color:"var(--acc)",cursor:"pointer"}}>Today</button>}
          </div>
          <button onClick={function(){setMonthOffset(function(o){return o+1;});}} style={{background:"var(--s3)",border:"1px solid var(--bdr)",borderRadius:8,width:32,height:32,cursor:"pointer",color:"var(--txt2)",fontSize:16,fontWeight:900,display:"flex",alignItems:"center",justifyContent:"center"}} title="Next month">{">"}</button>
        </div>

        {/* Day-of-week header row */}
        <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",borderBottom:"1px solid var(--bdr)"}}>
          {DOW_HDR.map(function(d,di){
            var wknd=di===0||di===6;
            return(
              <div key={d} style={{textAlign:"center",fontFamily:"var(--fd)",fontSize:10,fontWeight:800,letterSpacing:".08em",color:wknd?"var(--txt3)":"var(--txt2)",padding:"7px 0",borderRight:di<6?"1px solid var(--bdr)":"none"}}>{d.toUpperCase()}</div>
            );
          })}
        </div>

        {/* Calendar grid */}
        <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)"}}>
          {cells.map(function(cell,idx){
            var isLast=idx===cells.length-1;
            var col=idx%7;
            var borderR=col<6?"1px solid var(--bdr)":"none";
            var borderB=idx<cells.length-7?"1px solid var(--bdr)":"none";
            if(cell.type!=="cur"){
              return(
                <div key={idx} style={{minHeight:72,background:"var(--s1)",borderRight:borderR,borderBottom:borderB,opacity:.3}}/>
              );
            }
            var dateStr=cell.date;
            var dayJobs=jobsByDate[dateStr]||[];
            var dayBlocks=blocksByDate[dateStr]||[];
            var isToday=dateStr===TODAY;
            var isSel=dateStr===selDate;
            var wknd=col===0||col===6;
            return(
              <div key={dateStr} onClick={function(){setSelDate(dateStr);}}
                style={{
                  minHeight:80,borderRight:borderR,borderBottom:borderB,
                  background:isSel?"var(--acc)16":isToday?"var(--s2)":"var(--s1)",
                  cursor:"pointer",transition:"background .12s",
                  outline:isSel?"2px solid var(--acc)":"none",
                  outlineOffset:"-2px",
                  position:"relative",
                }}
                onMouseEnter={function(e){if(!isSel)e.currentTarget.style.background="var(--s2)";}}
                onMouseLeave={function(e){if(!isSel)e.currentTarget.style.background=isToday?"var(--s2)":"var(--s1)";}}>
                {/* Date number */}
                <div style={{padding:"5px 5px 3px",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                  <div style={{
                    width:20,height:20,borderRadius:"50%",flexShrink:0,
                    background:isToday?"var(--acc)":"transparent",
                    display:"flex",alignItems:"center",justifyContent:"center",
                  }}>
                    <span style={{fontFamily:"var(--fd)",fontSize:11,fontWeight:isToday?900:isSel?800:500,color:isToday?"#fff":isSel?"var(--acc)":wknd?"var(--txt3)":"var(--txt2)"}}>{cell.day}</span>
                  </div>
                  {(dayJobs.length+dayBlocks.length)>0&&(
                    <div style={{display:"flex",gap:2,paddingRight:2}}>
                      {dayJobs.length>0&&<div style={{background:"var(--acc)",color:"#fff",borderRadius:10,fontSize:8,fontFamily:"var(--fd)",fontWeight:900,padding:"0 4px",lineHeight:"14px",minWidth:14,textAlign:"center"}}>{dayJobs.length}</div>}
                      {dayBlocks.length>0&&<div style={{background:"#eab308",color:"#000",borderRadius:10,fontSize:8,fontFamily:"var(--fd)",fontWeight:900,padding:"0 4px",lineHeight:"14px",minWidth:14,textAlign:"center"}}>{dayBlocks.length}</div>}
                    </div>
                  )}
                </div>
                {/* Job lines — one per job, color = vehicle type color */}
                <div style={{padding:"0 2px 3px",display:"flex",flexDirection:"column",gap:1}}>
                  {dayJobs.map(function(j){
                    var col2=jobColor(j);
                    var c=customers.find(function(x){return x.id===j.customerId;})||{};
                    var hrs=(j.services||[]).reduce(function(s,sv){return s+sv.laborHours;},0);
                    var shortId=j.jobId?(j.jobId.split("-")[0]||j.jobId.slice(0,5)):(j.id&&j.id.slice(0,4));
                    return(
                      <div key={j.id}
                        style={{
                          background:col2+"28",
                          borderLeft:"2.5px solid "+col2,
                          borderRadius:"0 3px 3px 0",
                          padding:"1px 3px",
                          display:"flex",
                          alignItems:"center",
                          gap:3,
                          overflow:"hidden",
                        }}>
                        {/* Job ID chip */}
                        <span style={{background:col2,color:"#fff",borderRadius:3,fontSize:7,fontFamily:"var(--fm)",fontWeight:700,padding:"0 3px",lineHeight:"13px",flexShrink:0}}>{shortId}</span>
                        {/* Client name */}
                        <span style={{fontSize:8,fontFamily:"var(--fd)",fontWeight:700,color:col2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",flex:1}}>
                          {j.isPersonal?"Personal":fullName(c).split(" ")[0]||"Job"}
                        </span>
                        {/* Hours */}
                        {hrs>0&&<span style={{fontSize:7,fontFamily:"var(--fm)",color:col2,flexShrink:0,opacity:.8}}>{hrs}h</span>}
                      </div>
                    );
                  })}
                  {/* Block lines */}
                  {dayBlocks.map(function(b){
                    var bc=BLOCK_COLORS[b.color]||BLOCK_COLORS.ylw;
                    return(
                      <div key={b.id}
                        style={{
                          background:bc.hex+"22",
                          borderLeft:"2.5px solid "+bc.hex,
                          borderRadius:"0 3px 3px 0",
                          padding:"1px 3px",
                          display:"flex",
                          alignItems:"center",
                          gap:3,
                          overflow:"hidden",
                        }}>
                        <span style={{background:bc.hex,color:"#000",borderRadius:3,fontSize:7,fontFamily:"var(--fd)",fontWeight:900,padding:"0 3px",lineHeight:"13px",flexShrink:0}}>BLK</span>
                        <span style={{fontSize:8,fontFamily:"var(--fd)",fontWeight:700,color:bc.hex,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",flex:1}}>{b.label}</span>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>

        {/* Legend row */}
        <div style={{display:"flex",gap:14,padding:"8px 14px",borderTop:"1px solid var(--bdr)",flexWrap:"wrap"}}>
          <span style={{fontSize:9,color:"var(--txt3)",fontFamily:"var(--fd)",fontWeight:800,letterSpacing:".06em"}}>LEGEND:</span>
          {[
            ["var(--blu)","Upcoming"],
            ["var(--acc)","In Progress"],
            ["var(--grn)","Completed"],
            ["#a855f7","Personal"],
            ["#eab308","Time Block"],
          ].map(function(item){
            return(
              <div key={item[1]} style={{display:"flex",alignItems:"center",gap:4,fontSize:9,color:"var(--txt3)",fontFamily:"var(--fd)",fontWeight:700}}>
                <div style={{width:8,height:8,borderRadius:2,background:item[0],flexShrink:0}}/>
                {item[1]}
              </div>
            );
          })}
        </div>
      </div>

      {/* ══════════════════════════════════════
          DAY DETAIL — defaults to Today
      ══════════════════════════════════════ */}
      <div>
        {/* Section header */}
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
          <div>
            <div style={{fontFamily:"var(--fd)",fontSize:18,fontWeight:900}}>
              {selLabel}
              {selIsToday&&<span style={{marginLeft:8,background:"var(--acc)",color:"#fff",fontSize:10,fontFamily:"var(--fd)",fontWeight:900,padding:"2px 9px",borderRadius:12,verticalAlign:"middle"}}>Today</span>}
            </div>
            <div style={{fontSize:11,color:"var(--txt3)",marginTop:2}}>
              {selIsToday?"":selDateObj.toLocaleDateString("en-US",{month:"long",day:"numeric",year:"numeric"})+" \u00b7 "}
              {selDayItems.length===0?"Nothing scheduled":selJobs.length+" job"+(selJobs.length!==1?"s":"")+(selBlocks.length>0?" + "+selBlocks.length+" time block"+(selBlocks.length!==1?"s":""):"")}
            </div>
          </div>
          <div style={{display:"flex",gap:7}}>
            {routeStops.length>0&&<Btn v="outline" sz="sm" onClick={openRoute}>Route ({routeStops.length})</Btn>}
            <Btn v="primary" sz="sm" onClick={function(){onNewJob({scheduledDate:selDate});}}>+ Job</Btn>
            <Btn v="subtle" sz="sm" onClick={function(){setBlockModal(true);}}>+ Block</Btn>
          </div>
        </div>

        {/* Empty state */}
        {selDayItems.length===0&&(
          <div style={{background:"var(--s2)",border:"1px solid var(--bdr)",borderRadius:12,padding:"28px 16px",textAlign:"center"}}>
            <div style={{fontSize:32,marginBottom:8}}>📅</div>
            <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:800,color:"var(--txt2)",marginBottom:4}}>Nothing Scheduled</div>
            <div style={{fontSize:12,color:"var(--txt3)"}}>Tap a date on the calendar, or use the buttons above to add a job or block time.</div>
          </div>
        )}

        {/* Chronological list */}
        <div style={{display:"flex",flexDirection:"column",gap:8}}>
          {selDayItems.map(function(item,idx){
            if(item.kind==="job"){
              var j=item.data;
              var c=customers.find(function(x){return x.id===j.customerId;})||{};
              var v=vehicles.find(function(x){return x.id===j.vehicleId;})||{};
              var vtc=VT[(v.type)]||VT.Car;
              var jCol=jobColor(j);
              var calc=calcJob(j);
              var hrs2=(j.services||[]).reduce(function(s,sv){return s+sv.laborHours;},0);
              var shortId2=j.jobId?(j.jobId.split("-")[0]):(j.id&&j.id.slice(0,5));
              return(
                <div key={j.id} onClick={function(){onSelectJob(j.id);}}
                  style={{background:"var(--s2)",border:"1px solid var(--bdr)",borderLeft:"4px solid "+jCol,borderRadius:12,overflow:"hidden",cursor:"pointer",transition:".15s"}}
                  onMouseEnter={function(e){e.currentTarget.style.background="var(--s3)";}}
                  onMouseLeave={function(e){e.currentTarget.style.background="var(--s2)";}}>
                  {/* Color bar */}
                  <div style={{height:2,background:jCol+"66"}}/>
                  <div style={{padding:"11px 14px"}}>
                    {/* Top row: time + ID chip + status */}
                    <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:7}}>
                      {j.scheduledTime&&<span style={{fontFamily:"var(--fm)",fontSize:11,color:"var(--txt3)",flexShrink:0}}>{fmtT(j.scheduledTime)}</span>}
                      <span style={{background:jCol,color:"#fff",borderRadius:5,fontSize:10,fontFamily:"var(--fm)",fontWeight:700,padding:"1px 7px",flexShrink:0}}>{shortId2}</span>
                      <div style={{flex:1}}/>
                      <Chip label={j.isPersonal?"Personal":sLabel(j.status)} color={jCol} small/>
                    </div>
                    {/* Client + vehicle */}
                    <div style={{display:"flex",gap:9,alignItems:"center",marginBottom:6}}>
                      <span style={{fontSize:20,flexShrink:0}}>{vtc.icon}</span>
                      <div style={{flex:1,minWidth:0}}>
                        <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{j.isPersonal?"Personal Time":fullName(c)||"—"}</div>
                        {!j.isPersonal&&v.make&&<div style={{fontSize:11,color:"var(--txt3)",marginTop:1}}>{v.year} {v.make} {v.model}</div>}
                      </div>
                      {!j.isPersonal&&hrs2>0&&<div style={{background:jCol+"22",border:"1px solid "+jCol+"55",borderRadius:8,padding:"3px 9px",textAlign:"center",flexShrink:0}}>
                        <div style={{fontFamily:"var(--fm)",fontSize:12,fontWeight:700,color:jCol}}>{hrs2}h</div>
                        <div style={{fontSize:8,color:"var(--txt3)",fontFamily:"var(--fd)",fontWeight:700}}>LABOR</div>
                      </div>}
                    </div>
                    {/* Services */}
                    {!j.isPersonal&&(j.services||[]).length>0&&(
                      <div style={{fontSize:11,color:"var(--txt2)",marginBottom:6,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
                        {(j.services||[]).map(function(s){return s.name;}).join("  ·  ")}
                      </div>
                    )}
                    {/* Location */}
                    {j.location&&<div style={{fontSize:10,color:"var(--txt3)",marginBottom:6}}>📍 {j.location}</div>}
                    {/* Footer: invoice */}
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",paddingTop:8,borderTop:"1px solid var(--bdr)"}}>
                      <span style={{fontFamily:"var(--fd)",fontSize:11,fontWeight:700,color:"var(--txt3)"}}>Invoice</span>
                      <span className="mono" style={{fontSize:14,fontWeight:700,color:"var(--grn)"}}>{fmt$(calc.total)}</span>
                    </div>
                  </div>
                </div>
              );
            } else {
              var b=item.data;
              var bc=BLOCK_COLORS[b.color]||BLOCK_COLORS.ylw;
              return(
                <div key={b.id}
                  style={{background:bc.hex+"0e",border:"1px solid "+bc.hex+"44",borderLeft:"4px solid "+bc.hex,borderRadius:12,overflow:"hidden"}}>
                  <div style={{height:2,background:bc.hex+"44"}}/>
                  <div style={{padding:"11px 14px"}}>
                    <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
                      <span style={{fontFamily:"var(--fm)",fontSize:11,color:bc.hex,flexShrink:0}}>{fmtT(b.startTime)}</span>
                      <span style={{background:bc.hex,color:"#000",borderRadius:5,fontSize:10,fontFamily:"var(--fd)",fontWeight:900,padding:"1px 8px",flexShrink:0}}>BLOCKED</span>
                      <div style={{flex:1}}/>
                      <button aria-label="Remove" title="Remove" onClick={function(){removeBlock(b.id);}} style={{background:"none",border:"none",color:"var(--txt3)",cursor:"pointer",fontSize:14,padding:"2px 5px"}} title="Remove">x</button>
                    </div>
                    <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900,color:bc.hex,marginBottom:3}}>{b.label}</div>
                    <div style={{fontSize:11,color:"var(--txt3)",fontFamily:"var(--fm)",marginBottom:6}}>{fmtT(b.startTime)} &mdash; {fmtT(b.endTime)}</div>
                    <div style={{display:"inline-flex",background:bc.hex+"22",border:"1px solid "+bc.hex+"44",borderRadius:20,padding:"2px 10px"}}>
                      <span style={{fontSize:9,color:bc.hex,fontFamily:"var(--fd)",fontWeight:800,letterSpacing:".06em"}}>{bc.label.toUpperCase()}</span>
                    </div>
                  </div>
                </div>
              );
            }
          })}
        </div>
      </div>
      </>)}
      {view==="agenda"&&(<>
        {(agOverdue.length===0&&agUpcoming.length===0)&&(
          <div style={{background:"var(--s2)",border:"1px solid var(--bdr)",borderRadius:12,padding:"34px 16px",textAlign:"center"}}>
            <div style={{fontSize:32,marginBottom:8}}>📅</div>
            <div style={{fontFamily:"var(--fd)",fontSize:15,fontWeight:800,color:"var(--txt2)",marginBottom:4}}>No Upcoming Work</div>
            <div style={{fontSize:12,color:"var(--txt3)",marginBottom:14}}>Your agenda is clear. Schedule a job and it will show up here.</div>
            <Btn v="primary" sz="sm" onClick={function(){onNewJob({scheduledDate:TODAY});}}>+ Schedule a Job</Btn>
          </div>
        )}
        {agOverdue.length>0&&(<div style={{marginBottom:10}}>
          <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
            <div style={{fontFamily:"var(--fd)",fontSize:13,fontWeight:900,color:"var(--red)",letterSpacing:".04em"}}>NEEDS ATTENTION</div>
            <div style={{flex:1,height:1,background:"var(--red)44"}}/>
            <div style={{fontSize:10,color:"var(--red)",fontFamily:"var(--fm)"}}>{agOverdue.length} past due</div>
          </div>
          {agOverdue.map(function(j){return renderAgendaRow(j);})}
        </div>)}
        {agGroups.map(function(g){return(
          <div key={g.date}>
            <div style={{display:"flex",alignItems:"center",gap:8,margin:"14px 0 8px"}}>
              <div style={{fontFamily:"var(--fd)",fontSize:13,fontWeight:900,color:"var(--acc)",letterSpacing:".04em"}}>{agLabel(g.date).toUpperCase()}</div>
              <div style={{flex:1,height:1,background:"var(--bdr)"}}/>
              <div style={{fontSize:10,color:"var(--txt3)",fontFamily:"var(--fm)"}}>{g.items.length} job{g.items.length!==1?"s":""}</div>
            </div>
            {g.items.map(function(j){return renderAgendaRow(j);})}
          </div>
        );})}
      </>)}
    </div>
  );
};

