/* ════════════════ PRODUCTION PAGES ════════════════ */

// ── REPORTS & ANALYTICS PAGE (with expense tracking) ──
const ReportsPage=({jobs,customers,invoices,expenses,setExpenses,logAction})=>{
  const[showExp,setShowExp]=useState(false);
  const[ef,setEf]=useState({date:TODAY,category:"Supplies",amount:"",note:""});
  // Last 6 months revenue/profit
  const months=[];
  var nowD=new Date();
  for(var i=5;i>=0;i--){
    var d=new Date(nowD.getFullYear(),nowD.getMonth()-i,1);
    months.push({key:d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0"),label:d.toLocaleDateString("en-US",{month:"short"})});
  }
  const byMonth=months.map(function(m){
    var rev=0;var cost=0;
    jobs.forEach(function(j){if(j.status==="completed"&&(j.scheduledDate||"").startsWith(m.key)){var c=calcJob(j);rev+=c.total;cost+=c.partsCost;}});
    expenses.forEach(function(e){if((e.date||"").startsWith(m.key))cost+=e.amount;});
    return{label:m.label,rev:rev,cost:cost,profit:rev-cost};
  });
  const maxRev=Math.max.apply(null,byMonth.map(function(m){return m.rev;}).concat([1]));
  // Top clients
  const clientRev={};
  jobs.forEach(function(j){if(j.status==="completed"&&j.customerId){clientRev[j.customerId]=(clientRev[j.customerId]||0)+calcJob(j).total;}});
  const topClients=Object.keys(clientRev).map(function(cid){return{c:customers.find(function(x){return x.id===cid;})||{},rev:clientRev[cid]};}).sort(function(a,b){return b.rev-a.rev;}).slice(0,5);
  // Service mix
  const svcMix={};
  jobs.forEach(function(j){(j.services||[]).forEach(function(s){var key=(s.name||"Other").trim();svcMix[key]=(svcMix[key]||0)+1;});});
  const topSvcs=Object.keys(svcMix).map(function(k){return{name:k,n:svcMix[k]};}).sort(function(a,b){return b.n-a.n;}).slice(0,6);
  const maxSvc=Math.max.apply(null,topSvcs.map(function(s){return s.n;}).concat([1]));
  const totExp=expenses.reduce(function(s,e){return s+e.amount;},0);
  const totRev=jobs.filter(function(j){return j.status==="completed";}).reduce(function(s,j){return s+calcJob(j).total;},0);
  const totPartsCost=jobs.filter(function(j){return j.status==="completed";}).reduce(function(s,j){return s+calcJob(j).partsCost;},0);
  const saveExp=function(){
    var amt=+ef.amount;if(!amt)return;
    var ex={id:uid(),date:ef.date,category:ef.category,amount:amt,note:ef.note};
    setExpenses(function(p){return[ex,...p];});
    logAction("expense_added","expense","",fmt$(amt)+" expense recorded: "+ef.category+(ef.note?" - "+ef.note:""));
    setEf({date:TODAY,category:"Supplies",amount:"",note:""});setShowExp(false);
  };
  const delExp=function(id){if(window.confirm("Delete this expense?")){setExpenses(function(p){return p.filter(function(e){return e.id!==id;});});logAction("expense_deleted","expense","","Expense deleted");}};
  return(
    <div className="fade" style={{paddingBottom:24}}>
      {showExp&&(
        <Modal title="ADD EXPENSE" onClose={function(){setShowExp(false);}}>
          <div style={{display:"grid",gap:11}}>
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
              <FG label="Date"><input type="date" value={ef.date} onChange={function(e){setEf(function(p){return Object.assign({},p,{date:e.target.value});});}}/></FG>
              <FG label="Amount *"><input type="number" step="0.01" min="0" value={ef.amount} onChange={function(e){setEf(function(p){return Object.assign({},p,{amount:e.target.value});});}} autoFocus/></FG>
            </div>
            <FG label="Category">
              <select value={ef.category} onChange={function(e){setEf(function(p){return Object.assign({},p,{category:e.target.value});});}}>
                {EXP_CATS.map(function(c){return <option key={c} value={c}>{c}</option>;})}
              </select>
            </FG>
            <FG label="Note"><input value={ef.note} onChange={function(e){setEf(function(p){return Object.assign({},p,{note:e.target.value});});}} placeholder="e.g. Impact wrench, shop towels..."/></FG>
            <Btn v="primary" full onClick={saveExp}>Save Expense</Btn>
          </div>
        </Modal>
      )}
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:14,flexWrap:"wrap",gap:8}}>
        <div>
          <div style={{fontFamily:"var(--fd)",fontSize:26,fontWeight:900}}>REPORTS <span style={{color:"var(--acc)"}}>&amp; EXPENSES</span></div>
          <div style={{fontSize:11,color:"var(--txt3)",marginTop:2}}>Business performance overview</div>
        </div>
        <Btn v="primary" sz="sm" onClick={function(){setShowExp(true);}}>+ Add Expense</Btn>
      </div>
      {/* Headline stats */}
      <div style={{display:"flex",gap:7,marginBottom:14,flexWrap:"wrap"}}>
        <Card style={{flex:1,minWidth:100}}><Lbl>Total Revenue</Lbl><div style={{fontFamily:"var(--fd)",fontSize:19,fontWeight:900,color:"var(--grn)"}}>{fmt$(totRev)}</div></Card>
        <Card style={{flex:1,minWidth:100}}><Lbl>Parts Cost</Lbl><div style={{fontFamily:"var(--fd)",fontSize:19,fontWeight:900,color:"var(--ylw)"}}>{fmt$(totPartsCost)}</div></Card>
        <Card style={{flex:1,minWidth:100}}><Lbl>Expenses</Lbl><div style={{fontFamily:"var(--fd)",fontSize:19,fontWeight:900,color:"var(--red)"}}>{fmt$(totExp)}</div></Card>
        <Card style={{flex:1,minWidth:100}}><Lbl>Net Profit</Lbl><div style={{fontFamily:"var(--fd)",fontSize:19,fontWeight:900,color:(totRev-totPartsCost-totExp)>=0?"var(--grn)":"var(--red)"}}>{fmt$(totRev-totPartsCost-totExp)}</div></Card>
      </div>
      {/* Monthly revenue bars */}
      <Card style={{marginBottom:12}}>
        <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900,marginBottom:14}}>REVENUE — LAST 6 MONTHS</div>
        <div style={{display:"flex",gap:8,alignItems:"flex-end",height:130}}>
          {byMonth.map(function(m){
            const h=Math.max(4,(m.rev/maxRev)*110);
            return(
              <div key={m.label} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",gap:4}}>
                <span className="mono" style={{fontSize:9,color:"var(--txt3)"}}>{m.rev>0?fmt$(m.rev):""}</span>
                <div style={{width:"100%",maxWidth:42,height:h,background:"linear-gradient(180deg,var(--acc),var(--acc2))",borderRadius:"5px 5px 0 0",opacity:m.rev>0?1:.18}}/>
                <span style={{fontSize:10,fontFamily:"var(--fd)",fontWeight:700,color:"var(--txt3)"}}>{m.label}</span>
              </div>
            );
          })}
        </div>
      </Card>
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:12,marginBottom:12}}>
        {/* Top clients */}
        <Card>
          <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900,marginBottom:10}}>TOP CLIENTS</div>
          {topClients.length===0&&<div style={{fontSize:11,color:"var(--txt3)"}}>No completed jobs yet.</div>}
          {topClients.map(function(tc,i){return(
            <div key={i} style={{display:"flex",justifyContent:"space-between",gap:8,padding:"5px 0",borderBottom:i<topClients.length-1?"1px solid var(--bdr)":"none",fontSize:12}}>
              <span style={{fontFamily:"var(--fd)",fontWeight:700}}>{i+1}. {fullName(tc.c)||"Client"}</span>
              <span className="mono" style={{color:"var(--grn)"}}>{fmt$(tc.rev)}</span>
            </div>
          );})}
        </Card>
        {/* Service mix */}
        <Card>
          <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900,marginBottom:10}}>SERVICE MIX</div>
          {topSvcs.length===0&&<div style={{fontSize:11,color:"var(--txt3)"}}>No services logged yet.</div>}
          {topSvcs.map(function(s,i){return(
            <div key={i} style={{marginBottom:7}}>
              <div style={{display:"flex",justifyContent:"space-between",fontSize:11,marginBottom:2}}>
                <span style={{overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{s.name}</span>
                <span className="mono" style={{color:"var(--txt3)",flexShrink:0}}>{s.n}</span>
              </div>
              <div style={{height:5,background:"var(--s3)",borderRadius:3}}><div style={{height:"100%",width:((s.n/maxSvc)*100)+"%",background:"var(--cyn)",borderRadius:3}}/></div>
            </div>
          );})}
        </Card>
      </div>
      {/* Expense ledger */}
      <Card>
        <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900,marginBottom:10}}>EXPENSE LEDGER</div>
        {expenses.length===0&&<div style={{fontSize:11,color:"var(--txt3)",padding:"8px 0"}}>No expenses recorded. Track tools, supplies, and fuel here for accurate profit numbers.</div>}
        {expenses.map(function(e){return(
          <div key={e.id} style={{display:"flex",gap:10,alignItems:"center",padding:"7px 0",borderBottom:"1px solid var(--bdr)",fontSize:12}}>
            <span className="mono" style={{color:"var(--txt3)",fontSize:10,flexShrink:0}}>{fmtD(e.date)}</span>
            <span style={{background:"var(--s3)",borderRadius:10,padding:"1px 9px",fontSize:9,fontFamily:"var(--fd)",fontWeight:700,color:"var(--txt2)",flexShrink:0}}>{e.category}</span>
            <span style={{flex:1,color:"var(--txt2)",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{e.note}</span>
            <span className="mono" style={{color:"var(--red)",flexShrink:0}}>-{fmt$(e.amount)}</span>
            <button aria-label="Remove" title="Remove" onClick={function(){delExp(e.id);}} style={{background:"none",border:"none",color:"var(--txt3)",cursor:"pointer",fontSize:14}}>x</button>
          </div>
        );})}
      </Card>
    </div>
  );
};

// ── SERVICE REMINDERS PAGE ──
const RemindersPage=({jobs,customers,vehicles,dismissed,setDismissed,onNewJob,comms=[],onUpdateComm})=>{
  // Build reminders: latest completed job per vehicle per rule
  var reminders=[];
  var nowMs=new Date(TODAY+"T12:00:00").getTime();
  vehicles.forEach(function(v){
    REMIND_RULES.forEach(function(rule){
      var matching=jobs.filter(function(j){
        return j.vehicleId===v.id&&j.status==="completed"&&(j.services||[]).some(function(s){return(s.name||"").toLowerCase().indexOf(rule.key)>=0;});
      }).sort(function(a,b){return a.scheduledDate>b.scheduledDate?-1:1;});
      if(matching.length===0)return;
      var last=matching[0];
      var lastMs=new Date(last.scheduledDate+"T12:00:00").getTime();
      var dueMs=lastMs+rule.days*86400000;
      var daysLeft=Math.round((dueMs-nowMs)/86400000);
      if(daysLeft<=21){
        var rid=v.id+"-"+rule.key+"-"+last.scheduledDate;
        if(dismissed[rid])return;
        reminders.push({rid:rid,vehicle:v,rule:rule,lastDate:last.scheduledDate,daysLeft:daysLeft,customerId:v.customerId});
      }
    });
  });
  reminders.sort(function(a,b){return a.daysLeft-b.daysLeft;});
  var fuList=(comms||[]).filter(function(cm){return cm.followUp&&!cm.done;}).slice().sort(function(a,b){return (a.followUpDate||"")>(b.followUpDate||"")?1:-1;});
  return(
    <div className="fade" style={{paddingBottom:24}}>
      <div style={{marginBottom:14}}>
        <div style={{fontFamily:"var(--fd)",fontSize:26,fontWeight:900}}>SERVICE <span style={{color:"var(--acc)"}}>REMINDERS</span></div>
        <div style={{fontSize:11,color:"var(--txt3)",marginTop:2}}>Client follow-ups you logged, plus service-interval opportunities</div>
      </div>
      {fuList.length>0&&<div style={{marginBottom:18}}>
        <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
          <div style={{fontFamily:"var(--fd)",fontSize:13,fontWeight:900,color:"var(--ylw)",letterSpacing:".05em"}}>CLIENT FOLLOW-UPS</div>
          <div style={{flex:1,height:1,background:"var(--ylw)44"}}/>
          <span style={{fontSize:10,color:"var(--ylw)",fontFamily:"var(--fm)"}}>{fuList.length} open</span>
        </div>
        <div style={{display:"flex",flexDirection:"column",gap:7}}>
          {fuList.map(function(cm){
            var c=customers.find(function(x){return x.id===cm.customerId;});
            var due=cm.followUpDate&&cm.followUpDate<=TODAY;
            var ch=COMM_CH[cm.channel]||COMM_CH.Call;
            return(
              <div key={cm.id} style={{display:"flex",alignItems:"center",gap:10,background:"var(--s2)",border:"1px solid "+(due?"var(--red)55":"var(--bdr)"),borderLeft:"4px solid "+(due?"var(--red)":"var(--ylw)"),borderRadius:10,padding:"10px 12px"}}>
                <span className="mono" style={{fontSize:11,color:due?"var(--red)":"var(--ylw)",flexShrink:0,minWidth:64}}>{fmtD(cm.followUpDate)}</span>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{fontFamily:"var(--fd)",fontSize:13,fontWeight:800,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{c?fullName(c):"Client"}<span style={{marginLeft:8,color:ch.col,fontSize:9,fontWeight:800}}>{cm.channel.toUpperCase()}</span></div>
                  <div style={{fontSize:11,color:"var(--txt3)",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{cm.summary}</div>
                </div>
                {due&&<span style={{background:"var(--red)",color:"#fff",fontSize:9,fontFamily:"var(--fd)",fontWeight:900,padding:"2px 8px",borderRadius:10,flexShrink:0}}>DUE</span>}
                {onUpdateComm&&<Btn v="outline" sz="sm" onClick={function(){onUpdateComm(cm.id,{done:true});}}>Done</Btn>}
              </div>
            );
          })}
        </div>
      </div>}
      {reminders.length===0&&<Card><div style={{textAlign:"center",padding:"24px 0",color:"var(--txt3)",fontSize:13}}>No reminders due. As you complete jobs, follow-up windows for oil changes, rotations, and inspections will appear here automatically.</div></Card>}
      <div style={{display:"flex",flexDirection:"column",gap:8}}>
        {reminders.map(function(r){
          const c=customers.find(function(x){return x.id===r.customerId;})||{};
          const overdue=r.daysLeft<0;
          const col=overdue?"var(--red)":r.daysLeft<=7?"var(--acc)":"var(--ylw)";
          return(
            <div key={r.rid} style={{background:"var(--s2)",border:"1px solid var(--bdr)",borderLeft:"4px solid "+col,borderRadius:12,padding:"12px 14px",display:"flex",gap:10,alignItems:"center",flexWrap:"wrap"}}>
              <div style={{flex:1,minWidth:160}}>
                <div style={{display:"flex",gap:7,alignItems:"center",marginBottom:2,flexWrap:"wrap"}}>
                  <span style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900}}>{r.rule.label}</span>
                  <span style={{background:col+"22",color:col,fontSize:9,fontFamily:"var(--fd)",fontWeight:900,padding:"1px 8px",borderRadius:10}}>{overdue?Math.abs(r.daysLeft)+" DAYS OVERDUE":r.daysLeft===0?"DUE TODAY":"DUE IN "+r.daysLeft+" DAYS"}</span>
                </div>
                <div style={{fontSize:12,color:"var(--txt2)"}}>{fullName(c)||"Client"} &middot; {r.vehicle.year} {r.vehicle.make} {r.vehicle.model}</div>
                <div style={{fontSize:10,color:"var(--txt3)",marginTop:1}}>Last serviced {fmtD(r.lastDate)}</div>
              </div>
              <div style={{display:"flex",gap:6,flexShrink:0}}>
                <Btn v="primary" sz="sm" onClick={function(){onNewJob({customerId:r.customerId,vehicleId:r.vehicle.id});}}>Book Job</Btn>
                <Btn v="ghost" sz="sm" onClick={function(){setDismissed(function(p){var n=Object.assign({},p);n[r.rid]=true;return n;});}}>Dismiss</Btn>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

// ── GLOBAL SEARCH MODAL ──
const SearchModal=({onClose,customers,vehicles,jobs,invoices,onSelectJob,onGoClients,onOpenInvoice})=>{
  const[q,setQ]=useState("");
  const lq=q.toLowerCase();
  const match=function(s){return s&&String(s).toLowerCase().indexOf(lq)>=0;};
  const results=lq.length<2?{clients:[],vehs:[],jobs:[],invs:[]}:{
    clients:customers.filter(function(c){return match(fullName(c))||match(c.phone)||match(dispCustId(c.id))||match(c.email);}).slice(0,5),
    vehs:vehicles.filter(function(v){return match(v.make)||match(v.model)||match(dispVehId(v.vehicleId))||match(v.vin);}).slice(0,5),
    jobs:jobs.filter(function(j){return match(dispJobId(j.jobId))||(j.services||[]).some(function(s){return match(s.name);});}).slice(0,5),
    invs:invoices.filter(function(inv){return match(inv.invId)||(inv.shopWarranties||[]).some(function(w){return match(w.warId);});}).slice(0,5),
  };
  const Section=function(p){return p.items.length===0?null:(
    <div style={{marginBottom:12}}>
      <div style={{fontSize:9,fontFamily:"var(--fd)",fontWeight:800,letterSpacing:".1em",color:"var(--txt3)",marginBottom:5}}>{p.title}</div>
      {p.items}
    </div>
  );};
  return(
    <div style={{position:"fixed",inset:0,background:"#000d",zIndex:500,display:"flex",alignItems:"flex-start",justifyContent:"center",padding:"60px 14px 14px"}} onClick={function(e){if(e.target===e.currentTarget)onClose();}}>
      <div className="pop" style={{background:"var(--s1)",border:"1px solid var(--bdr)",borderRadius:16,width:"100%",maxWidth:520,maxHeight:"75vh",display:"flex",flexDirection:"column",boxShadow:"0 24px 80px #000e"}}>
        <div style={{padding:"14px 16px",borderBottom:"1px solid var(--bdr)"}}>
          <input value={q} onChange={function(e){setQ(e.target.value);}} placeholder="Search clients, vehicles, jobs, invoices, warranty IDs..." autoFocus style={{width:"100%"}}/>
        </div>
        <div style={{flex:1,overflowY:"auto",padding:"12px 16px"}}>
          {lq.length<2&&<div style={{fontSize:12,color:"var(--txt3)",textAlign:"center",padding:"16px 0"}}>Type at least 2 characters to search everything.</div>}
          <Section title="CLIENTS" items={results.clients.map(function(c){return(
            <button key={c.id} onClick={function(){onGoClients();onClose();}} style={{display:"block",width:"100%",textAlign:"left",background:"var(--s3)",border:"1px solid var(--bdr)",borderRadius:"var(--r)",padding:"7px 11px",marginBottom:4,cursor:"pointer",fontSize:12}}>
              <span style={{fontFamily:"var(--fd)",fontWeight:800}}>{fullName(c)}</span> <span className="mono" style={{fontSize:10,color:"var(--acc)"}}>{dispCustId(c.id)}</span>
            </button>
          );})}/>
          <Section title="VEHICLES" items={results.vehs.map(function(v){return(
            <button key={v.id} onClick={function(){onGoClients();onClose();}} style={{display:"block",width:"100%",textAlign:"left",background:"var(--s3)",border:"1px solid var(--bdr)",borderRadius:"var(--r)",padding:"7px 11px",marginBottom:4,cursor:"pointer",fontSize:12}}>
              <span style={{fontFamily:"var(--fd)",fontWeight:800}}>{v.year} {v.make} {v.model}</span> <span className="mono" style={{fontSize:10,color:"var(--acc)"}}>{dispVehId(v.vehicleId)}</span>
            </button>
          );})}/>
          <Section title="JOBS" items={results.jobs.map(function(j){return(
            <button key={j.id} onClick={function(){onSelectJob(j.id);onClose();}} style={{display:"block",width:"100%",textAlign:"left",background:"var(--s3)",border:"1px solid var(--bdr)",borderRadius:"var(--r)",padding:"7px 11px",marginBottom:4,cursor:"pointer",fontSize:12}}>
              <span className="mono" style={{fontSize:10,color:"var(--acc)"}}>{dispJobId(j.jobId)}</span> <span style={{color:"var(--txt2)"}}>{(j.services||[]).map(function(s){return s.name;}).join(", ")}</span>
            </button>
          );})}/>
          <Section title="INVOICES" items={results.invs.map(function(inv){return(
            <button key={inv.id} onClick={function(){onOpenInvoice(inv.id);onClose();}} style={{display:"block",width:"100%",textAlign:"left",background:"var(--s3)",border:"1px solid var(--bdr)",borderRadius:"var(--r)",padding:"7px 11px",marginBottom:4,cursor:"pointer",fontSize:12}}>
              <span className="mono" style={{fontSize:10,color:"var(--acc)"}}>{inv.invId}</span> <span style={{color:"var(--txt2)"}}>{inv.status}</span>
            </button>
          );})}/>
        </div>
      </div>
    </div>
  );
};


// ── INVOICE DETAIL (preview + warranties + payments) ──
const InvoiceDetail=({inv,customers,vehicles,settings,onBack,onUpdate,logAction})=>{
  const[payModal,setPayModal]=useState(false);
  const[pay,setPay]=useState({amount:"",method:"Cash",note:""});
  const[warTab,setWarTab]=useState("shop");
  const c=customers.find(function(x){return x.id===inv.customerId;})||{};
  const v=vehicles.find(function(x){return x.id===inv.vehicleId;})||{};
  const t=invTotals(inv);
  const upd=function(patch){onUpdate(Object.assign({},inv,patch));};
  const recordPay=function(){
    var amt=+pay.amount;if(!amt||amt<=0)return;
    var p={id:uid(),amount:amt,method:pay.method,note:pay.note,date:new Date().toISOString()};
    var newPays=[...(inv.payments||[]),p];
    var newTotals=invTotals(Object.assign({},inv,{payments:newPays}));
    var newStatus=newTotals.due<=0.005?"paid":"partial";
    upd({payments:newPays,status:newStatus});
    logAction("payment_recorded","payment",inv.invId,fmt$(amt)+" payment recorded on "+inv.invId+" via "+pay.method,[{field:"balance",from:fmt$(t.due),to:fmt$(newTotals.due)}]);
    setPay({amount:"",method:"Cash",note:""});setPayModal(false);
  };
  const setPW=function(idx,k,val){
    var pw=Object.assign({},inv.partsWarranties||{});
    var entry=Object.assign({covered:false,supplier:"",manufacturer:"",warrantyId:"",duration:"",notes:"",photo:null},pw[idx]||{});
    entry[k]=val;pw[idx]=entry;upd({partsWarranties:pw});
  };
  const handleWPhoto=function(idx){return function(e){var file=e.target.files[0];if(!file)return;var r=new FileReader();r.onload=function(ev){setPW(idx,"photo",ev.target.result);};r.readAsDataURL(file);};};
  const toggleSW=function(i){
    var sw=(inv.shopWarranties||[]).map(function(w,wi){return wi===i?Object.assign({},w,{checked:!w.checked}):w;});
    upd({shopWarranties:sw});
  };
  const emailInvoice=function(){
    var body="Invoice "+inv.invId+"%0D%0A"+
      "Date: "+fmtD(inv.issuedDate||inv.createdAt.slice(0,10))+"%0D%0A"+
      "Client: "+encodeURIComponent(fullName(c))+"%0D%0A"+
      (v.make?"Vehicle: "+encodeURIComponent(v.year+" "+v.make+" "+v.model)+"%0D%0A":"")+
      "%0D%0ATotal: "+encodeURIComponent(fmt$(t.total))+"%0D%0APaid: "+encodeURIComponent(fmt$(t.paid))+"%0D%0ABalance Due: "+encodeURIComponent(fmt$(t.due))+
      "%0D%0A%0D%0AThank you for your business.";
    window.location.href="mailto:"+(c.email||"")+"?subject="+encodeURIComponent("Invoice "+inv.invId+" - "+(settings.shopName||"Invoice"))+"&body="+body;
  };
  const printInvoice=function(){window.print();};
  const sColor2=inv.status==="paid"?"var(--grn)":inv.status==="partial"?"var(--ylw)":inv.status==="void"?"var(--txt3)":"var(--blu)";
  return(
    <div className="fade" style={{paddingBottom:30}}>
      {payModal&&(
        <Modal title="RECORD PAYMENT" subtitle={"Balance due: "+fmt$(t.due)} onClose={function(){setPayModal(false);}}>
          <div style={{display:"grid",gap:11}}>
            <FG label="Amount *"><input type="number" step="0.01" min="0" value={pay.amount} onChange={function(e){setPay(function(p){return Object.assign({},p,{amount:e.target.value});});}} autoFocus placeholder={t.due.toFixed(2)}/></FG>
            <FG label="Method">
              <select value={pay.method} onChange={function(e){setPay(function(p){return Object.assign({},p,{method:e.target.value});});}}>
                {PAY_METHODS.map(function(m){return <option key={m} value={m}>{m}</option>;})}
              </select>
            </FG>
            <FG label="Note"><input value={pay.note} onChange={function(e){setPay(function(p){return Object.assign({},p,{note:e.target.value});});}} placeholder="e.g. Deposit on drop-off"/></FG>
            <div style={{display:"flex",gap:6}}>
              <Btn v="subtle" sz="sm" onClick={function(){setPay(function(p){return Object.assign({},p,{amount:String(t.due.toFixed(2))});});}}>Full Balance</Btn>
              <Btn v="subtle" sz="sm" onClick={function(){setPay(function(p){return Object.assign({},p,{amount:String((t.due/2).toFixed(2))});});}}>Half</Btn>
            </div>
            <Btn v="primary" full onClick={recordPay}>Save Payment</Btn>
          </div>
        </Modal>
      )}
      <div className="no-print" style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14,flexWrap:"wrap",gap:8}}>
        <Btn v="ghost" sz="sm" onClick={onBack}>Back to Invoices</Btn>
        <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
          {inv.status!=="void"&&t.due>0.005&&<Btn v="primary" sz="sm" onClick={function(){setPayModal(true);}}>Record Payment</Btn>}
          <Btn v="subtle" sz="sm" onClick={emailInvoice}>Email</Btn>
          <Btn v="subtle" sz="sm" onClick={printInvoice}>Print / PDF</Btn>
          {inv.status!=="void"&&<Btn v="ghost" sz="sm" onClick={function(){if(window.confirm("Void this invoice? This cannot be undone."))upd({status:"void"});logAction("invoice_voided","invoice",inv.invId,"Invoice "+inv.invId+" voided");}}>Void</Btn>}
        </div>
      </div>

      {/* ══ PRINTABLE INVOICE ══ */}
      <div className="print-area" style={{background:"var(--s1)",border:"1px solid var(--bdr)",borderRadius:14,padding:"26px 28px",maxWidth:720,margin:"0 auto"}}>
        {/* Header */}
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:14,marginBottom:18,paddingBottom:16,borderBottom:"2px solid var(--acc)"}}>
          <div style={{display:"flex",gap:13,alignItems:"center"}}>
            {settings.logo&&<img src={settings.logo} style={{width:54,height:54,objectFit:"contain",borderRadius:8}} alt=""/>}
            <div>
              <div style={{fontFamily:"var(--fd)",fontSize:21,fontWeight:900}}>{settings.shopName||"Your Shop Name"}</div>
              {settings.address&&<div style={{fontSize:11,color:"var(--txt2)"}}>{settings.address}</div>}
              <div style={{fontSize:11,color:"var(--txt2)"}}>{settings.phone||""}{settings.phone&&settings.email?" \u00b7 ":""}{settings.email||""}</div>
            </div>
          </div>
          <div style={{textAlign:"right"}}>
            <div style={{fontFamily:"var(--fd)",fontSize:16,fontWeight:900,color:"var(--acc)"}}>INVOICE</div>
            <div className="mono" style={{fontSize:12}}>{inv.invId}</div>
            <div style={{fontSize:11,color:"var(--txt3)",marginTop:3}}>{fmtD(inv.issuedDate||inv.createdAt.slice(0,10))}</div>
            <div style={{marginTop:5}}><Chip label={inv.status.toUpperCase()} color={sColor2} small/></div>
          </div>
        </div>
        {/* Bill to / vehicle */}
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:14,marginBottom:18}}>
          <div>
            <div style={{fontSize:9,fontFamily:"var(--fd)",fontWeight:800,letterSpacing:".1em",color:"var(--txt3)",marginBottom:4}}>BILL TO</div>
            <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:800}}>{fullName(c)||"Client"}</div>
            {c.phone&&<div style={{fontSize:11,color:"var(--txt2)"}}>{c.phone}</div>}
            {c.email&&<div style={{fontSize:11,color:"var(--txt2)"}}>{c.email}</div>}
            <div className="mono" style={{fontSize:10,color:"var(--txt3)",marginTop:2}}>{dispCustId(c.id)}</div>
          </div>
          <div>
            <div style={{fontSize:9,fontFamily:"var(--fd)",fontWeight:800,letterSpacing:".1em",color:"var(--txt3)",marginBottom:4}}>VEHICLE / JOB</div>
            {v.make?<div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:800}}>{v.year} {v.make} {v.model}</div>:<div style={{fontSize:12,color:"var(--txt3)"}}>No vehicle on file</div>}
            {v.vehicleId&&<div className="mono" style={{fontSize:10,color:"var(--txt3)"}}>{dispVehId(v.vehicleId)}</div>}
            {inv.jobDisplayId&&<div className="mono" style={{fontSize:10,color:"var(--txt3)"}}>Job: {inv.jobDisplayId}</div>}
            {inv.odometer&&<div style={{fontSize:10,color:"var(--txt3)"}}>Odometer: {inv.odometer} mi</div>}
          </div>
        </div>
        {/* Labor line items */}
        <div style={{marginBottom:14}}>
          <div style={{fontSize:9,fontFamily:"var(--fd)",fontWeight:800,letterSpacing:".1em",color:"var(--txt3)",marginBottom:6,paddingBottom:4,borderBottom:"1px solid var(--bdr)"}}>SERVICES / LABOR</div>
          {(inv.laborItems||[]).map(function(li,i){return(
            <div key={i} style={{display:"flex",justifyContent:"space-between",gap:10,padding:"5px 0",fontSize:12.5,borderBottom:"1px solid var(--bdr)"}}>
              <span style={{flex:1}}>{li.name}</span>
              <span className="mono" style={{color:"var(--txt3)",flexShrink:0}}>{li.hours}h @ {fmt$(li.rate)}/hr</span>
              <span className="mono" style={{minWidth:74,textAlign:"right",flexShrink:0}}>{fmt$(li.hours*li.rate)}</span>
            </div>
          );})}
          {(inv.laborItems||[]).length===0&&<div style={{fontSize:11,color:"var(--txt3)",padding:"5px 0"}}>No labor items</div>}
        </div>
        {/* Parts line items */}
        <div style={{marginBottom:14}}>
          <div style={{fontSize:9,fontFamily:"var(--fd)",fontWeight:800,letterSpacing:".1em",color:"var(--txt3)",marginBottom:6,paddingBottom:4,borderBottom:"1px solid var(--bdr)"}}>PARTS &amp; MATERIALS</div>
          {(inv.partItems||[]).map(function(p,i){return(
            <div key={i} style={{display:"flex",justifyContent:"space-between",gap:10,padding:"5px 0",fontSize:12.5,borderBottom:"1px solid var(--bdr)"}}>
              <span style={{flex:1}}>{p.name}{(inv.partsWarranties&&inv.partsWarranties[i]&&inv.partsWarranties[i].covered)?<span style={{marginLeft:6,fontSize:9,background:"var(--grn)18",color:"var(--grn)",padding:"1px 6px",borderRadius:8,fontFamily:"var(--fd)",fontWeight:800}}>WARRANTY</span>:null}</span>
              <span className="mono" style={{color:"var(--txt3)",flexShrink:0}}>x{p.qty}</span>
              <span className="mono" style={{minWidth:74,textAlign:"right",flexShrink:0}}>{fmt$(p.qty*p.sell)}</span>
            </div>
          );})}
          {(inv.partItems||[]).length===0&&<div style={{fontSize:11,color:"var(--txt3)",padding:"5px 0"}}>No parts</div>}
        </div>
        {/* Totals */}
        <div style={{marginLeft:"auto",maxWidth:300,marginBottom:16}}>
          <div style={{display:"flex",justifyContent:"space-between",fontSize:12,padding:"3px 0"}}><span style={{color:"var(--txt2)"}}>Labor Subtotal</span><span className="mono">{fmt$(t.lab)}</span></div>
          <div style={{display:"flex",justifyContent:"space-between",fontSize:12,padding:"3px 0"}}><span style={{color:"var(--txt2)"}}>Parts Subtotal</span><span className="mono">{fmt$(t.parts)}</span></div>
          <div style={{display:"flex",justifyContent:"space-between",fontSize:12,padding:"3px 0"}}><span style={{color:"var(--txt2)"}}>Sales Tax {((inv.taxRate||0.075)*100).toFixed(1)}% (parts only)</span><span className="mono">{fmt$(t.tax)}</span></div>
          <div style={{fontSize:9,color:"var(--txt3)",textAlign:"right",marginBottom:4}}>Labor exempt per SC Code 12-36-910</div>
          <div style={{display:"flex",justifyContent:"space-between",fontSize:15,fontWeight:700,padding:"6px 0",borderTop:"1px solid var(--bdr2)"}}><span style={{fontFamily:"var(--fd)",fontWeight:900}}>TOTAL</span><span className="mono">{fmt$(t.total)}</span></div>
          {t.paid>0&&<div style={{display:"flex",justifyContent:"space-between",fontSize:12,padding:"3px 0",color:"var(--grn)"}}><span>Payments Applied</span><span className="mono">-{fmt$(t.paid)}</span></div>}
          <div style={{display:"flex",justifyContent:"space-between",fontSize:16,fontWeight:700,padding:"6px 0",borderTop:"2px solid var(--acc)"}}><span style={{fontFamily:"var(--fd)",fontWeight:900,color:"var(--acc)"}}>BALANCE DUE</span><span className="mono" style={{color:t.due<=0.005?"var(--grn)":"var(--acc)"}}>{fmt$(Math.max(0,t.due))}</span></div>
        </div>
        {/* Payment history */}
        {(inv.payments||[]).length>0&&(
          <div style={{marginBottom:16}}>
            <div style={{fontSize:9,fontFamily:"var(--fd)",fontWeight:800,letterSpacing:".1em",color:"var(--txt3)",marginBottom:5}}>PAYMENT HISTORY</div>
            {inv.payments.map(function(p){return(
              <div key={p.id} style={{display:"flex",gap:10,fontSize:11,color:"var(--txt2)",padding:"3px 0"}}>
                <span className="mono" style={{color:"var(--txt3)"}}>{fmtDT(p.date)}</span>
                <span>{p.method}</span>
                <span className="mono" style={{color:"var(--grn)"}}>{fmt$(p.amount)}</span>
                {p.note&&<span style={{color:"var(--txt3)"}}>{p.note}</span>}
              </div>
            );})}
          </div>
        )}
        {/* Active shop warranties (print view) */}
        {(inv.shopWarranties||[]).filter(function(w){return w.checked;}).length>0&&(
          <div style={{marginBottom:14,paddingTop:12,borderTop:"1px solid var(--bdr)"}}>
            <div style={{fontSize:9,fontFamily:"var(--fd)",fontWeight:800,letterSpacing:".1em",color:"var(--txt3)",marginBottom:6}}>SHOP WARRANTY — LABOR &amp; WORKMANSHIP</div>
            {(inv.shopWarranties||[]).filter(function(w){return w.checked;}).map(function(w,i){return(
              <div key={i} style={{marginBottom:8}}>
                <div style={{fontSize:11.5,fontWeight:700}}>{w.service} <span className="mono" style={{fontSize:9,color:"var(--acc)"}}>{w.warId}</span> <span style={{color:"var(--txt3)",fontWeight:400}}>({w.dur})</span></div>
                <div style={{fontSize:10.5,color:"var(--txt2)",lineHeight:1.5}}>{w.term}</div>
              </div>
            );})}
            <div style={{fontSize:9,color:"var(--txt3)",lineHeight:1.55,marginTop:8,paddingTop:8,borderTop:"1px solid var(--bdr)"}}>{SHOP_WARRANTY_FOOTER}</div>
          </div>
        )}
        {inv.notes&&<div style={{fontSize:11,color:"var(--txt2)",paddingTop:10,borderTop:"1px solid var(--bdr)"}}>{inv.notes}</div>}
        <div style={{textAlign:"center",fontSize:10,color:"var(--txt3)",marginTop:14}}>Thank you for your business.</div>
      </div>

      {/* ══ WARRANTY EDITOR (not printed) ══ */}
      <div className="no-print" style={{maxWidth:720,margin:"14px auto 0"}}>
        <Card>
          <div style={{display:"flex",gap:0,borderBottom:"1px solid var(--bdr)",marginBottom:12}}>
            {[["shop","Shop Warranty (Labor)"],["parts","Parts Warranty"]].map(function(tb){return(
              <button key={tb[0]} onClick={function(){setWarTab(tb[0]);}} style={{background:"none",border:"none",borderBottom:warTab===tb[0]?"2px solid var(--acc)":"2px solid transparent",padding:"7px 14px",fontFamily:"var(--fd)",fontSize:12,fontWeight:800,color:warTab===tb[0]?"var(--acc)":"var(--txt3)",cursor:"pointer"}}>{tb[1]}</button>
            );})}
          </div>
          {warTab==="shop"&&(
            <div>
              <div style={{fontSize:11,color:"var(--txt3)",marginBottom:10}}>Check the warranties to include on this invoice. Terms cover labor and workmanship only — parts are excluded.</div>
              {(inv.shopWarranties||[]).map(function(w,i){return(
                <label key={i} style={{display:"flex",gap:10,alignItems:"flex-start",padding:"9px 11px",background:w.checked?"var(--grn)0c":"var(--s3)",border:"1px solid "+(w.checked?"var(--grn)44":"var(--bdr)"),borderRadius:"var(--r2)",marginBottom:6,cursor:"pointer"}}>
                  <input type="checkbox" checked={w.checked} onChange={function(){toggleSW(i);}} style={{marginTop:2,accentColor:"var(--grn)",flexShrink:0}}/>
                  <div style={{flex:1}}>
                    <div style={{display:"flex",gap:7,alignItems:"center",flexWrap:"wrap"}}>
                      <span style={{fontFamily:"var(--fd)",fontSize:13,fontWeight:800}}>{w.service}</span>
                      <span className="mono" style={{fontSize:9,color:"var(--acc)"}}>{w.warId}</span>
                      <span style={{fontSize:10,color:"var(--txt3)"}}>{w.dur}</span>
                    </div>
                    <div style={{fontSize:10.5,color:"var(--txt2)",marginTop:3,lineHeight:1.5}}>{w.term}</div>
                  </div>
                </label>
              );})}
              <div style={{fontSize:10,color:"var(--ylw)",marginTop:8}}>* These warranty terms are templates. We advise reviewing this language with a licensed attorney before presenting it to clients.</div>
            </div>
          )}
          {warTab==="parts"&&(
            <div>
              <div style={{fontSize:11,color:"var(--txt3)",marginBottom:10}}>Record manufacturer or supplier warranty details for each part. The warranty badge appears on the printed invoice.</div>
              {(inv.partItems||[]).length===0&&<div style={{fontSize:12,color:"var(--txt3)",padding:"10px 0"}}>No parts on this invoice.</div>}
              {(inv.partItems||[]).map(function(p,i){
                const pw=Object.assign({covered:false,supplier:"",manufacturer:"",warrantyId:"",duration:"",notes:"",photo:null},(inv.partsWarranties||{})[i]||{});
                return(
                  <div key={i} style={{background:"var(--s3)",border:"1px solid var(--bdr)",borderRadius:"var(--r2)",padding:"11px 13px",marginBottom:8}}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:pw.covered?10:0}}>
                      <span style={{fontFamily:"var(--fd)",fontSize:13,fontWeight:800}}>{p.name} <span style={{color:"var(--txt3)",fontWeight:400}}>x{p.qty}</span></span>
                      <label style={{display:"flex",gap:6,alignItems:"center",cursor:"pointer",fontSize:11,fontFamily:"var(--fd)",fontWeight:700,color:pw.covered?"var(--grn)":"var(--txt3)"}}>
                        <input type="checkbox" checked={pw.covered} onChange={function(e){setPW(i,"covered",e.target.checked);}} style={{accentColor:"var(--grn)"}}/>
                        Warranty {pw.covered?"Yes":"No"}
                      </label>
                    </div>
                    {pw.covered&&(
                      <div style={{display:"grid",gap:8}}>
                        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
                          <FG label="Store / Supplier"><input value={pw.supplier} onChange={function(e){setPW(i,"supplier",e.target.value);}} placeholder="e.g. AutoZone Conway"/></FG>
                          <FG label="Manufacturer">
                            <select value={pw.manufacturer} onChange={function(e){setPW(i,"manufacturer",e.target.value);}}>
                              <option value="">Select...</option>
                              {MFRS.map(function(m){return <option key={m} value={m}>{m}</option>;})}
                            </select>
                          </FG>
                        </div>
                        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
                          <FG label="Warranty ID"><input value={pw.warrantyId} onChange={function(e){setPW(i,"warrantyId",e.target.value);}} placeholder="From receipt or tag"/></FG>
                          <FG label="Duration"><input value={pw.duration} onChange={function(e){setPW(i,"duration",e.target.value);}} placeholder="e.g. 12 mo / 12,000 mi"/></FG>
                        </div>
                        <FG label="Notes"><input value={pw.notes} onChange={function(e){setPW(i,"notes",e.target.value);}} placeholder="Conditions, exclusions..."/></FG>
                        <div style={{display:"flex",gap:10,alignItems:"center"}}>
                          <label htmlFor={"pw-photo-"+inv.id+"-"+i} style={{display:"inline-block",cursor:"pointer",background:"var(--s4)",border:"1px solid var(--bdr)",borderRadius:"var(--r)",padding:"5px 11px",fontSize:11,fontFamily:"var(--fd)",fontWeight:800,color:"var(--txt2)"}}>
                            {pw.photo?"Change Receipt Photo":"Upload Receipt Photo"}
                          </label>
                          <input id={"pw-photo-"+inv.id+"-"+i} type="file" accept="image/*" style={{display:"none"}} onChange={handleWPhoto(i)}/>
                          {pw.photo&&<img src={pw.photo} style={{width:42,height:42,objectFit:"cover",borderRadius:6,border:"1px solid var(--bdr)"}} alt=""/>}
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </Card>
      </div>
    </div>
  );
};

// ── INVOICE HISTORY PAGE ──
const InvoiceHistoryPage=({invoices,customers,vehicles,jobs,onOpen,onCreateFrom})=>{
  const[fClient,setFClient]=useState("all");
  const[fStatus,setFStatus]=useState("all");
  const[fFrom,setFFrom]=useState("");
  const[fTo,setFTo]=useState("");
  const[fSearch,setFSearch]=useState("");
  const[fWar,setFWar]=useState(false);
  const[selSet,setSelSet]=useState({});
  const[pickJob,setPickJob]=useState(false);
  const q=fSearch.toLowerCase();
  const filtered=invoices.filter(function(inv){
    if(fClient!=="all"&&inv.customerId!==fClient)return false;
    if(fStatus!=="all"&&inv.status!==fStatus)return false;
    var d=(inv.issuedDate||inv.createdAt.slice(0,10));
    if(fFrom&&d<fFrom)return false;
    if(fTo&&d>fTo)return false;
    if(fWar){
      var hasShop=(inv.shopWarranties||[]).some(function(w){return w.checked;});
      var hasPart=Object.keys(inv.partsWarranties||{}).some(function(k){return inv.partsWarranties[k].covered;});
      if(!hasShop&&!hasPart)return false;
    }
    if(q){
      var c=customers.find(function(x){return x.id===inv.customerId;})||{};
      var hay=(inv.invId+" "+fullName(c)+" "+(inv.laborItems||[]).map(function(l){return l.name;}).join(" ")+" "+(inv.shopWarranties||[]).map(function(w){return w.warId;}).join(" ")).toLowerCase();
      if(hay.indexOf(q)<0)return false;
    }
    return true;
  });
  const totals=filtered.reduce(function(acc,inv){var t=invTotals(inv);if(inv.status!=="void"){acc.invoiced+=t.total;acc.collected+=t.paid;acc.due+=Math.max(0,t.due);}return acc;},{invoiced:0,collected:0,due:0});
  const selIds=Object.keys(selSet).filter(function(k){return selSet[k];});
  const printSelected=function(){
    document.body.classList.add("print-multi");
    window.print();
    window.setTimeout(function(){document.body.classList.remove("print-multi");},800);
  };
  const jobsNoInvoice=jobs.filter(function(j){return !j.isPersonal&&!invoices.some(function(inv){return inv.jobId===j.id;});});
  const STAT_COLORS={draft:"var(--txt3)",issued:"var(--blu)",partial:"var(--ylw)",paid:"var(--grn)","void":"var(--txt3)"};
  return(
    <div className="fade" style={{paddingBottom:24}}>
      {pickJob&&(
        <Modal title="CREATE INVOICE FROM JOB" subtitle="Select a job that does not have an invoice yet" onClose={function(){setPickJob(false);}}>
          {jobsNoInvoice.length===0&&<div style={{fontSize:12,color:"var(--txt3)",padding:"12px 0"}}>Every job already has an invoice, or no jobs exist yet.</div>}
          <div style={{display:"flex",flexDirection:"column",gap:6,maxHeight:340,overflowY:"auto"}}>
            {jobsNoInvoice.map(function(j){
              const c=customers.find(function(x){return x.id===j.customerId;})||{};
              const calc=calcJob(j);
              return(
                <button key={j.id} onClick={function(){setPickJob(false);onCreateFrom(j.id);}} style={{textAlign:"left",background:"var(--s3)",border:"1px solid var(--bdr)",borderRadius:"var(--r2)",padding:"10px 12px",cursor:"pointer"}}>
                  <div style={{display:"flex",justifyContent:"space-between",gap:8}}>
                    <div>
                      <div style={{fontFamily:"var(--fd)",fontSize:13,fontWeight:800}}>{fullName(c)||"Client"}</div>
                      <div style={{fontSize:10,color:"var(--txt3)"}}>{dispJobId(j.jobId)} &middot; {fmtD(j.scheduledDate)}</div>
                    </div>
                    <span className="mono" style={{color:"var(--grn)",fontSize:13}}>{fmt$(calc.total)}</span>
                  </div>
                </button>
              );
            })}
          </div>
        </Modal>
      )}
      <div className="no-print">
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:14,flexWrap:"wrap",gap:8}}>
          <div>
            <div style={{fontFamily:"var(--fd)",fontSize:26,fontWeight:900}}>INVOICE <span style={{color:"var(--acc)"}}>HISTORY</span></div>
            <div style={{fontSize:11,color:"var(--txt3)",marginTop:2}}>{filtered.length} of {invoices.length} invoice{invoices.length!==1?"s":""}</div>
          </div>
          <Btn v="primary" sz="sm" onClick={function(){setPickJob(true);}}>+ New Invoice</Btn>
        </div>
        {/* Summary stats */}
        <div style={{display:"flex",gap:7,marginBottom:12,flexWrap:"wrap"}}>
          <Card style={{flex:1,minWidth:100}}><Lbl>Invoiced</Lbl><div style={{fontFamily:"var(--fd)",fontSize:19,fontWeight:900,color:"var(--cyn)"}}>{fmt$(totals.invoiced)}</div></Card>
          <Card style={{flex:1,minWidth:100}}><Lbl>Collected</Lbl><div style={{fontFamily:"var(--fd)",fontSize:19,fontWeight:900,color:"var(--grn)"}}>{fmt$(totals.collected)}</div></Card>
          <Card style={{flex:1,minWidth:100}}><Lbl>Outstanding</Lbl><div style={{fontFamily:"var(--fd)",fontSize:19,fontWeight:900,color:totals.due>0?"var(--acc)":"var(--grn)"}}>{fmt$(totals.due)}</div></Card>
        </div>
        {/* Filters */}
        <Card style={{marginBottom:12}}>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:8}}>
            <input value={fSearch} onChange={function(e){setFSearch(e.target.value);}} placeholder="Search invoice #, client, service, warranty ID..."/>
            <select value={fClient} onChange={function(e){setFClient(e.target.value);}}>
              <option value="all">All Clients</option>
              {customers.map(function(c){return <option key={c.id} value={c.id}>{fullName(c)}</option>;})}
            </select>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr auto",gap:8,alignItems:"center"}}>
            <input type="date" value={fFrom} onChange={function(e){setFFrom(e.target.value);}} title="From date"/>
            <input type="date" value={fTo} onChange={function(e){setFTo(e.target.value);}} title="To date"/>
            <select value={fStatus} onChange={function(e){setFStatus(e.target.value);}}>
              <option value="all">All Statuses</option>
              <option value="draft">Draft</option><option value="issued">Issued</option>
              <option value="partial">Partially Paid</option><option value="paid">Paid</option><option value="void">Void</option>
            </select>
            <label style={{display:"flex",gap:5,alignItems:"center",fontSize:11,fontFamily:"var(--fd)",fontWeight:700,color:fWar?"var(--grn)":"var(--txt3)",cursor:"pointer",whiteSpace:"nowrap"}}>
              <input type="checkbox" checked={fWar} onChange={function(e){setFWar(e.target.checked);}} style={{accentColor:"var(--grn)"}}/>
              Has Warranty
            </label>
          </div>
        </Card>
        {selIds.length>0&&(
          <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:10,background:"var(--acc)10",border:"1px solid var(--acc)44",borderRadius:"var(--r2)",padding:"8px 13px"}}>
            <span style={{fontSize:12,fontFamily:"var(--fd)",fontWeight:800,color:"var(--acc)"}}>{selIds.length} selected</span>
            <Btn v="primary" sz="sm" onClick={printSelected}>Print / Export Selected</Btn>
            <Btn v="ghost" sz="sm" onClick={function(){setSelSet({});}}>Clear</Btn>
          </div>
        )}
        {invoices.length===0&&<Card><div style={{textAlign:"center",padding:"24px 0",color:"var(--txt3)",fontSize:13}}>No invoices yet. Create one from a completed job.</div></Card>}
        <div style={{display:"flex",flexDirection:"column",gap:7}}>
          {filtered.map(function(inv){
            const c=customers.find(function(x){return x.id===inv.customerId;})||{};
            const v=vehicles.find(function(x){return x.id===inv.vehicleId;})||{};
            const t=invTotals(inv);
            return(
              <div key={inv.id} style={{display:"flex",gap:10,alignItems:"center",background:"var(--s2)",border:"1px solid var(--bdr)",borderRadius:12,padding:"11px 13px"}}>
                <input type="checkbox" checked={!!selSet[inv.id]} onChange={function(e){var ch=e.target.checked;setSelSet(function(p){var n=Object.assign({},p);n[inv.id]=ch;return n;});}} style={{accentColor:"var(--acc)",flexShrink:0}}/>
                <div style={{flex:1,minWidth:0,cursor:"pointer"}} onClick={function(){onOpen(inv.id);}}>
                  <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap",marginBottom:2}}>
                    <span className="mono" style={{fontSize:11,color:"var(--acc)"}}>{inv.invId}</span>
                    <Chip label={inv.status.toUpperCase()} color={STAT_COLORS[inv.status]} small/>
                    <span style={{fontSize:10,color:"var(--txt3)"}}>{fmtD(inv.issuedDate||inv.createdAt.slice(0,10))}</span>
                  </div>
                  <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:800}}>{fullName(c)||"Client"}{v.make?<span style={{fontWeight:400,color:"var(--txt3)",fontSize:11}}> &middot; {v.year} {v.make} {v.model}</span>:null}</div>
                  <div style={{fontSize:10,color:"var(--txt3)",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{(inv.laborItems||[]).map(function(l){return l.name;}).join(", ")}</div>
                </div>
                <div style={{textAlign:"right",flexShrink:0}}>
                  <div className="mono" style={{fontSize:14,fontWeight:700}}>{fmt$(t.total)}</div>
                  <div style={{fontSize:10,color:t.due<=0.005?"var(--grn)":"var(--acc)"}} className="mono">{t.due<=0.005?"PAID":"Due "+fmt$(t.due)}</div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
      {/* Hidden print area for bulk export */}
      <div className="print-bulk" style={{display:"none"}}>
        {filtered.filter(function(inv){return !!selSet[inv.id];}).map(function(inv){
          const c=customers.find(function(x){return x.id===inv.customerId;})||{};
          const t=invTotals(inv);
          return(
            <div key={inv.id} style={{pageBreakAfter:"always",padding:"20px 0",borderBottom:"2px solid #000"}}>
              <div style={{fontSize:18,fontWeight:900}}>{inv.invId} &middot; {fullName(c)}</div>
              <div style={{fontSize:12}}>Date: {fmtD(inv.issuedDate||inv.createdAt.slice(0,10))} &middot; Status: {inv.status}</div>
              <div style={{fontSize:12,marginTop:8}}>{(inv.laborItems||[]).map(function(l){return l.name+" ("+l.hours+"h @ "+fmt$(l.rate)+")";}).join("; ")}</div>
              <div style={{fontSize:13,marginTop:8,fontWeight:700}}>Total: {fmt$(t.total)} &middot; Paid: {fmt$(t.paid)} &middot; Due: {fmt$(Math.max(0,t.due))}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
};


// ── AUDIT LOG PAGE ──
const AuditPage=({auditLog})=>{
  const[tab,setTab]=useState("actions");
  const[entFilter,setEntFilter]=useState("all");
  const[search,setSearch]=useState("");
  const[expanded,setExpanded]=useState({});
  const ENTS=["all","client","vehicle","job","invoice","payment","estimate","expense","block","account"];
  const ENT_COLORS={client:"var(--blu)",vehicle:"var(--grn)",job:"var(--acc)",invoice:"var(--cyn)",payment:"var(--grn)",estimate:"var(--pur)",expense:"var(--red)",block:"var(--ylw)",account:"var(--txt3)"};
  const q=search.toLowerCase();
  const filtered=auditLog.filter(function(e){
    if(entFilter!=="all"&&e.entity!==entFilter)return false;
    if(tab==="fields"&&(!e.fields||e.fields.length===0))return false;
    if(q&&(e.summary.toLowerCase().indexOf(q)<0&&(e.entityId||"").toLowerCase().indexOf(q)<0))return false;
    return true;
  });
  const exportCSV=function(){
    var rows=[["Timestamp","Action","Entity","Entity ID","Summary","Field","From","To","User"]];
    filtered.forEach(function(e){
      if(e.fields&&e.fields.length){e.fields.forEach(function(fd){rows.push([e.timestamp,e.action,e.entity,e.entityId,e.summary,fd.field,String(fd.from),String(fd.to),e.user]);});}
      else rows.push([e.timestamp,e.action,e.entity,e.entityId,e.summary,"","","",e.user]);
    });
    var csv=rows.map(function(r){return r.map(function(c){return '"'+String(c).split('"').join('""')+'"';}).join(",");}).join("\n");
    var a=document.createElement("a");a.href="data:text/csv;charset=utf-8,"+encodeURIComponent(csv);a.download="audit-log.csv";document.body.appendChild(a);a.click();document.body.removeChild(a);
  };
  return(
    <div className="fade" style={{paddingBottom:24}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:14,flexWrap:"wrap",gap:8}}>
        <div>
          <div style={{fontFamily:"var(--fd)",fontSize:26,fontWeight:900}}>AUDIT <span style={{color:"var(--acc)"}}>LOG</span></div>
          <div style={{fontSize:11,color:"var(--txt3)",marginTop:2}}>{auditLog.length} recorded action{auditLog.length!==1?"s":""} &middot; Complete activity history</div>
        </div>
        <Btn v="subtle" sz="sm" onClick={exportCSV}>Export CSV</Btn>
      </div>
      <div style={{display:"flex",gap:0,borderBottom:"1px solid var(--bdr)",marginBottom:12}}>
        {[["actions","Action Feed"],["fields","Field Changes"]].map(function(t){return(
          <button key={t[0]} onClick={function(){setTab(t[0]);}} style={{background:"none",border:"none",borderBottom:tab===t[0]?"2px solid var(--acc)":"2px solid transparent",padding:"8px 16px",fontFamily:"var(--fd)",fontSize:13,fontWeight:800,color:tab===t[0]?"var(--acc)":"var(--txt3)",cursor:"pointer",letterSpacing:".05em"}}>{t[1]}</button>
        );})}
      </div>
      <div style={{display:"flex",gap:8,marginBottom:12,flexWrap:"wrap"}}>
        <input value={search} onChange={function(e){setSearch(e.target.value);}} placeholder="Search summary or ID..." style={{flex:1,minWidth:160}}/>
        <select value={entFilter} onChange={function(e){setEntFilter(e.target.value);}} style={{width:130}}>
          {ENTS.map(function(en){return <option key={en} value={en}>{en==="all"?"All Entities":en[0].toUpperCase()+en.slice(1)}</option>;})}
        </select>
      </div>
      {filtered.length===0&&<Card><div style={{textAlign:"center",padding:"20px 0",color:"var(--txt3)",fontSize:13}}>No log entries match.</div></Card>}
      <div style={{display:"flex",flexDirection:"column",gap:6}}>
        {filtered.map(function(e){
          const ec=ENT_COLORS[e.entity]||"var(--txt3)";
          const isExp=expanded[e.id];
          const hasFields=e.fields&&e.fields.length>0;
          return(
            <div key={e.id} style={{background:"var(--s2)",border:"1px solid var(--bdr)",borderLeft:"3px solid "+ec,borderRadius:10,padding:"10px 13px",cursor:hasFields?"pointer":"default"}} onClick={function(){if(hasFields)setExpanded(function(p){var n=Object.assign({},p);n[e.id]=!n[e.id];return n;});}}>
              <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}>
                <span className="mono" style={{fontSize:10,color:"var(--txt3)",flexShrink:0}}>{fmtDT(e.timestamp)}</span>
                <span style={{background:ec+"22",color:ec,fontSize:9,fontFamily:"var(--fd)",fontWeight:800,padding:"1px 8px",borderRadius:10,letterSpacing:".05em",flexShrink:0}}>{e.entity.toUpperCase()}</span>
                {e.entityId&&<span className="mono" style={{fontSize:10,color:"var(--acc)",flexShrink:0}}>{e.entityId}</span>}
                {hasFields&&<span style={{fontSize:9,color:"var(--txt3)",marginLeft:"auto",flexShrink:0}}>{isExp?"Hide":e.fields.length+" change"+(e.fields.length!==1?"s":"")}</span>}
              </div>
              <div style={{fontSize:12.5,color:"var(--txt)",marginTop:4}}>{e.summary}</div>
              {isExp&&hasFields&&(
                <div style={{marginTop:8,borderTop:"1px solid var(--bdr)",paddingTop:8,display:"flex",flexDirection:"column",gap:4}}>
                  {e.fields.map(function(fd,fi){return(
                    <div key={fi} style={{display:"flex",gap:8,alignItems:"center",fontSize:11,flexWrap:"wrap"}}>
                      <span style={{fontFamily:"var(--fd)",fontWeight:700,color:"var(--txt2)",minWidth:90}}>{fd.field}</span>
                      <span style={{background:"var(--red)14",color:"var(--red)",padding:"1px 8px",borderRadius:6,fontFamily:"var(--fm)",fontSize:10}}>{String(fd.from)||"(empty)"}</span>
                      <span style={{color:"var(--txt3)"}}>to</span>
                      <span style={{background:"var(--grn)14",color:"var(--grn)",padding:"1px 8px",borderRadius:6,fontFamily:"var(--fm)",fontSize:10}}>{String(fd.to)||"(empty)"}</span>
                    </div>
                  );})}
                </div>
              )}
              <div style={{fontSize:9,color:"var(--txt3)",marginTop:4}}>by {e.user}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

// ── SETTINGS PAGE ──
const SettingsPage=({settings,setSettings,onExport,onImport,logAction})=>{
  const[legalTab,setLegalTab]=useState(null);
  const set=function(k){return function(e){var val=e.target.value;setSettings(function(p){var n=Object.assign({},p);n[k]=val;return n;});};};
  const handleLogo=function(e){var file=e.target.files[0];if(!file)return;var r=new FileReader();r.onload=function(ev){setSettings(function(p){var n=Object.assign({},p);n.logo=ev.target.result;return n;});logAction("settings_updated","account","","Shop logo updated");};r.readAsDataURL(file);};
  return(
    <div className="fade" style={{paddingBottom:24,maxWidth:640}}>
      <div style={{marginBottom:16}}>
        <div style={{fontFamily:"var(--fd)",fontSize:26,fontWeight:900}}>SHOP <span style={{color:"var(--acc)"}}>SETTINGS</span></div>
        <div style={{fontSize:11,color:"var(--txt3)",marginTop:2}}>Business profile, defaults, and data management</div>
      </div>
      <Card style={{marginBottom:12}}>
        <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900,marginBottom:12}}>BUSINESS PROFILE</div>
        <div style={{display:"grid",gap:11}}>
          <FG label="Shop Name"><input value={settings.shopName} onChange={set("shopName")} placeholder="Hillside Auto Repair"/></FG>
          <FG label="Address"><input value={settings.address} onChange={set("address")} placeholder="123 Main St, Conway, SC 29526"/></FG>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
            <FG label="Phone"><input value={settings.phone} onChange={set("phone")} placeholder="843-555-0100"/></FG>
            <FG label="Email"><input value={settings.email} onChange={set("email")} placeholder="shop@email.com"/></FG>
          </div>
          <div>
            <Lbl>Shop Logo (appears on invoices)</Lbl>
            <div style={{display:"flex",gap:12,alignItems:"center",padding:"10px 12px",background:"var(--s3)",border:"1px solid var(--bdr)",borderRadius:"var(--r2)"}}>
              <div style={{width:52,height:52,borderRadius:10,background:"var(--s1)",border:"1px solid var(--bdr)",display:"flex",alignItems:"center",justifyContent:"center",overflow:"hidden",flexShrink:0}}>
                {settings.logo?<img src={settings.logo} style={{width:"100%",height:"100%",objectFit:"contain"}} alt=""/>:<span style={{fontSize:20,opacity:.4}}>🏪</span>}
              </div>
              <div>
                <label htmlFor="shop-logo-input" style={{display:"inline-block",cursor:"pointer",background:"var(--s4)",border:"1px solid var(--bdr)",borderRadius:"var(--r)",padding:"5px 11px",fontSize:12,fontFamily:"var(--fd)",fontWeight:800,color:"var(--txt2)"}}>
                  {settings.logo?"Change Logo":"Upload Logo"}
                </label>
                <input id="shop-logo-input" type="file" accept="image/*" style={{display:"none"}} onChange={handleLogo}/>
              </div>
            </div>
          </div>
        </div>
      </Card>
      <Card style={{marginBottom:12}}>
        <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900,marginBottom:12}}>DEFAULTS</div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
          <FG label="Default Labor Rate ($/hr)"><input type="number" min="0" value={settings.laborRate} onChange={set("laborRate")}/></FG>
          <FG label="Parts Tax Rate (%)"><input type="number" step="0.1" min="0" max="100" value={settings.taxRate} onChange={set("taxRate")}/></FG>
        </div>
        <div style={{fontSize:10,color:"var(--txt3)",marginTop:8}}>Default 7.5% = 6% SC state + 1.5% Horry County local option. Applied to parts only; labor is exempt under SC Code 12-36-910. Verify current rates with the SC Department of Revenue.</div>
      </Card>
      <Card style={{marginBottom:12}}>
        <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900,marginBottom:6}}>AI ASSISTANT</div>
        <div style={{fontSize:11,color:"var(--txt3)",marginBottom:12}}>The AI Repair Planner works automatically in the hosted app. If you are running the downloadable local copy, paste an Anthropic API key here to enable it. It is stored only in your own workspace and sent directly to Anthropic.</div>
        <FG label="Anthropic API Key (optional)"><input type="password" value={settings.aiKey||""} onChange={set("aiKey")} placeholder="sk-ant-..." autoComplete="off"/></FG>
        <div style={{fontSize:10,color:"var(--txt3)",marginTop:6}}>Get a key at console.anthropic.com. Leave blank when using the hosted app.</div>
      </Card>
      <Card>
        <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900,marginBottom:6}}>DATA BACKUP &amp; RESTORE</div>
        <div style={{fontSize:11,color:"var(--txt3)",marginBottom:12}}>Your workspace saves to this device automatically and reloads when you sign back in. Export a backup file regularly as an extra safeguard, and import it to restore or move your data to another device.</div>
        <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
          <Btn v="primary" sz="md" onClick={onExport}>Download Backup (.json)</Btn>
          <label htmlFor="backup-import-input" style={{display:"inline-flex",alignItems:"center",cursor:"pointer",background:"var(--s3)",border:"1px solid var(--bdr)",borderRadius:"var(--r)",padding:"8px 16px",fontSize:13,fontFamily:"var(--fd)",fontWeight:800,color:"var(--txt2)"}}>
            Import Backup
          </label>
          <input id="backup-import-input" type="file" accept=".json,application/json" style={{display:"none"}} onChange={onImport}/>
        </div>
      </Card>
      <Card style={{marginTop:14,borderLeft:"3px solid var(--sand)"}}>
        <div style={{display:"flex",gap:12,alignItems:"center",marginBottom:8}}>
          <img src={MM_BRAND} alt="DB monogram" style={{width:38,height:38,objectFit:"contain",flexShrink:0,opacity:.92}}/>
          <div>
            <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900}}>ABOUT</div>
            <div style={{fontSize:12,color:"var(--txt2)"}}>Mobile Mechanic Open Source <span className="mono" style={{color:"var(--acc)"}}>v{APP_VERSION}</span></div>
          </div>
        </div>
        <div style={{fontSize:11,color:"var(--txt3)",lineHeight:1.65,marginBottom:10}}>Shop management built for independent mobile mechanics. All of your data lives only on this device {"\u2014"} nothing is uploaded, synced, or tracked. The optional AI Repair Planner and VIN Decode contact their services only at the moment you use them.</div>
        <div style={{fontSize:11,color:"var(--txt3)",lineHeight:1.7}}>
          <span style={{fontFamily:"var(--fd)",fontWeight:800,color:"var(--txt2)"}}>What&apos;s new in v{APP_VERSION}:</span> communication logs with follow-up reminders, Business Planner and Playbook, VIN decode, day routing, parts sourcing with quote comparison, guided first-run setup, and hardened local security (hashed passwords, storage-failure alerts, protected backup restore).
        </div>
      </Card>
      <Card style={{marginTop:14}}>
        <div style={{fontFamily:"var(--fd)",fontSize:14,fontWeight:900,marginBottom:6}}>LEGAL &amp; PRIVACY</div>
        <div style={{fontSize:11,color:"var(--txt3)",marginBottom:10}}>You accepted the Terms when this account was created (recorded in the Audit Log). The current documents are always available here.</div>
        <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
          <Btn v="subtle" sz="sm" onClick={function(){setLegalTab("terms");}}>Terms of Service</Btn>
          <Btn v="subtle" sz="sm" onClick={function(){setLegalTab("privacy");}}>Privacy Policy</Btn>
          <Btn v="subtle" sz="sm" onClick={function(){setLegalTab("disclaimer");}}>Disclaimers</Btn>
          <Btn v="subtle" sz="sm" onClick={function(){setLegalTab("licenses");}}>Open-Source Licenses</Btn>
        </div>
        {legalTab&&<LegalModal tab={legalTab} setTab={setLegalTab} onClose={function(){setLegalTab(null);}}/>}
      </Card>
    </div>
  );
};

// ── ESTIMATES PAGE ──
const EstimatesPage=({estimates,setEstimates,customers,vehicles,onConvert,logAction,defaultRate})=>{
  const[showNew,setShowNew]=useState(false);
  const[f,setF]=useState({customerId:"",vehicleId:"",services:[],notes:""});
  const custVehs=vehicles.filter(function(v){return v.customerId===f.customerId;});
  const addSvc=function(){setF(function(p){return Object.assign({},p,{services:[...p.services,{id:uid(),name:"",laborHours:1,laborRate:defaultRate||95,partsEst:0}]});});};
  const setSvc=function(id,k,val){setF(function(p){return Object.assign({},p,{services:p.services.map(function(s){if(s.id!==id)return s;var n=Object.assign({},s);n[k]=(k==="name")?val:+val;return n;})});});};
  const delSvc=function(id){setF(function(p){return Object.assign({},p,{services:p.services.filter(function(s){return s.id!==id;})});});};
  const estTotal=function(est){return(est.services||[]).reduce(function(s,sv){return s+sv.laborHours*sv.laborRate+(+sv.partsEst||0);},0);};
  const saveEst=function(){
    if(!f.customerId||f.services.length===0)return;
    var est={id:uid(),estId:genEstId(f.customerId,estimates),customerId:f.customerId,vehicleId:f.vehicleId,services:f.services,notes:f.notes,status:"open",createdAt:new Date().toISOString()};
    setEstimates(function(p){return[est,...p];});
    logAction("estimate_created","estimate",est.estId,"Estimate "+est.estId+" created for "+(fullName(customers.find(function(c){return c.id===f.customerId;})||{})||"client"));
    setF({customerId:"",vehicleId:"",services:[],notes:""});setShowNew(false);
  };
  return(
    <div className="fade" style={{paddingBottom:24}}>
      {showNew&&(
        <Modal title="NEW ESTIMATE" onClose={function(){setShowNew(false);}}>
          <div style={{display:"grid",gap:11}}>
            <FG label="Client *">
              <select value={f.customerId} onChange={function(e){setF(function(p){return Object.assign({},p,{customerId:e.target.value,vehicleId:""});});}}>
                <option value="">Select client...</option>
                {customers.map(function(c){return <option key={c.id} value={c.id}>{fullName(c)}</option>;})}
              </select>
            </FG>
            {f.customerId&&<FG label="Vehicle">
              <select value={f.vehicleId} onChange={function(e){setF(function(p){return Object.assign({},p,{vehicleId:e.target.value});});}}>
                <option value="">Select vehicle...</option>
                {custVehs.map(function(v){return <option key={v.id} value={v.id}>{v.year} {v.make} {v.model}</option>;})}
              </select>
            </FG>}
            <div>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}>
                <Lbl>Estimated Services</Lbl>
                <Btn v="subtle" sz="sm" onClick={addSvc}>+ Add Line</Btn>
              </div>
              {f.services.map(function(s){return(
                <div key={s.id} style={{display:"grid",gridTemplateColumns:"3fr 60px 60px 70px 26px",gap:5,marginBottom:5,alignItems:"center"}}>
                  <input value={s.name} onChange={function(e){setSvc(s.id,"name",e.target.value);}} placeholder="Service description"/>
                  <input type="number" step="0.5" min="0" value={s.laborHours} onChange={function(e){setSvc(s.id,"laborHours",e.target.value);}} title="Hours"/>
                  <input type="number" min="0" value={s.laborRate} onChange={function(e){setSvc(s.id,"laborRate",e.target.value);}} title="Rate"/>
                  <input type="number" value={s.partsEst} onChange={function(e){setSvc(s.id,"partsEst",e.target.value);}} title="Parts est." min="0" placeholder="Parts $"/>
                  <button aria-label="Remove" title="Remove" onClick={function(){delSvc(s.id);}} style={{background:"none",border:"none",color:"var(--red)",cursor:"pointer",fontSize:13}}>x</button>
                </div>
              );})}
              {f.services.length>0&&<div style={{textAlign:"right",fontFamily:"var(--fm)",fontSize:13,color:"var(--grn)",marginTop:6}}>Estimate Total: {fmt$(f.services.reduce(function(s,sv){return s+sv.laborHours*sv.laborRate+(+sv.partsEst||0);},0))}</div>}
            </div>
            <FG label="Notes"><textarea rows={2} value={f.notes} onChange={function(e){setF(function(p){return Object.assign({},p,{notes:e.target.value});});}} placeholder="Scope, exclusions, validity period..."/></FG>
            <Btn v="primary" full disabled={!f.customerId||f.services.length===0} onClick={saveEst}>Save Estimate</Btn>
          </div>
        </Modal>
      )}
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:14,flexWrap:"wrap",gap:8}}>
        <div>
          <div style={{fontFamily:"var(--fd)",fontSize:26,fontWeight:900}}>ESTIMATES <span style={{color:"var(--acc)"}}>&amp; QUOTES</span></div>
          <div style={{fontSize:11,color:"var(--txt3)",marginTop:2}}>{estimates.filter(function(e){return e.status==="open";}).length} open &middot; {estimates.length} total</div>
        </div>
        <Btn v="primary" sz="sm" onClick={function(){setShowNew(true);}}>+ New Estimate</Btn>
      </div>
      {estimates.length===0&&<Card><div style={{textAlign:"center",padding:"24px 0",color:"var(--txt3)",fontSize:13}}>No estimates yet. Create a quote, send it to your client, then convert it to a job with one tap when approved.</div></Card>}
      <div style={{display:"flex",flexDirection:"column",gap:8}}>
        {estimates.map(function(est){
          const c=customers.find(function(x){return x.id===est.customerId;})||{};
          const v=vehicles.find(function(x){return x.id===est.vehicleId;});
          const total=estTotal(est);
          const open=est.status==="open";
          return(
            <Card key={est.id}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",gap:8,flexWrap:"wrap"}}>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:3,flexWrap:"wrap"}}>
                    <span className="mono" style={{fontSize:11,color:"var(--acc)"}}>{est.estId}</span>
                    <Chip label={open?"Open":est.status==="converted"?"Converted to Job":"Declined"} color={open?"var(--blu)":est.status==="converted"?"var(--grn)":"var(--txt3)"} small/>
                  </div>
                  <div style={{fontFamily:"var(--fd)",fontSize:15,fontWeight:900}}>{fullName(c)||"Client"}</div>
                  {v&&<div style={{fontSize:11,color:"var(--txt3)"}}>{v.year} {v.make} {v.model}</div>}
                  <div style={{fontSize:11,color:"var(--txt2)",marginTop:4}}>{(est.services||[]).map(function(s){return s.name;}).join(", ")}</div>
                  <div style={{fontSize:9,color:"var(--txt3)",marginTop:3}}>{fmtDT(est.createdAt)}</div>
                </div>
                <div style={{textAlign:"right",flexShrink:0}}>
                  <div className="mono" style={{fontSize:16,fontWeight:700,color:"var(--grn)",marginBottom:8}}>{fmt$(total)}</div>
                  {open&&<div style={{display:"flex",gap:5,flexDirection:"column"}}>
                    <Btn v="primary" sz="sm" onClick={function(){onConvert(est);}}>Convert to Job</Btn>
                    <Btn v="ghost" sz="sm" onClick={function(){setEstimates(function(p){return p.map(function(x){return x.id===est.id?Object.assign({},x,{status:"declined"}):x;});});logAction("estimate_declined","estimate",est.estId,"Estimate "+est.estId+" marked declined");}}>Mark Declined</Btn>
                  </div>}
                </div>
              </div>
            </Card>
          );
        })}
      </div>
    </div>
  );
};

/* ── BUSINESS PLANNER — manual project & goal tracking ── */
const PROJECT_CATS=["Growth","Marketing","Equipment","Operations","Training","Other"];
const PlannerPage=({projects=[],setProjects,logAction})=>{
  const[showNew,setShowNew]=useState(false);
  const[nf,setNf]=useState({name:"",cat:"Growth",targetDate:"",notes:""});
  const[taskInputs,setTaskInputs]=useState({});
  const setNfK=function(k){return function(e){var v=e.target.value;setNf(function(p){var n=Object.assign({},p);n[k]=v;return n;});};};
  const addProject=function(){
    if(!nf.name.trim())return;
    var pr={id:uid(),name:nf.name.trim(),cat:nf.cat,status:"active",targetDate:nf.targetDate||"",notes:nf.notes||"",tasks:[],createdAt:new Date().toISOString()};
    setProjects(function(p){return [pr].concat(p);});
    if(logAction)logAction("project_created","project","","Project created: "+pr.name);
    setNf({name:"",cat:"Growth",targetDate:"",notes:""});setShowNew(false);
  };
  const patchProject=function(id,patch){setProjects(function(p){return p.map(function(x){return x.id===id?Object.assign({},x,patch):x;});});};
  const delProject=function(id){if(!window.confirm("Delete this project and its tasks?"))return;setProjects(function(p){return p.filter(function(x){return x.id!==id;});});};
  const addTask=function(pid){
    var label=(taskInputs[pid]||"").trim();if(!label)return;
    setProjects(function(p){return p.map(function(x){if(x.id!==pid)return x;var n=Object.assign({},x);n.tasks=(x.tasks||[]).concat([{id:uid(),label:label,done:false}]);return n;});});
    setTaskInputs(function(p){var n=Object.assign({},p);n[pid]="";return n;});
  };
  const toggleTask=function(pid,tid){setProjects(function(p){return p.map(function(x){if(x.id!==pid)return x;var n=Object.assign({},x);n.tasks=(x.tasks||[]).map(function(t){return t.id===tid?Object.assign({},t,{done:!t.done}):t;});return n;});});};
  const delTask=function(pid,tid){setProjects(function(p){return p.map(function(x){if(x.id!==pid)return x;var n=Object.assign({},x);n.tasks=(x.tasks||[]).filter(function(t){return t.id!==tid;});return n;});});};
  var sorted=projects.slice().sort(function(a,b){var ra=a.status==="done"?1:0;var rb=b.status==="done"?1:0;if(ra!==rb)return ra-rb;return (a.createdAt||"")<(b.createdAt||"")?1:-1;});
  var STARTERS=["Get 10 Google reviews","Land 3 fleet accounts","Buy a pro scan tool","Set up card payments"];
  return(
    <div className="fade" style={{paddingBottom:24}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:14,flexWrap:"wrap",gap:10}}>
        <div>
          <div style={{fontFamily:"var(--fd)",fontSize:26,fontWeight:900}}>BUSINESS <span style={{color:"var(--acc)"}}>PLANNER</span></div>
          <div style={{fontSize:11,color:"var(--txt3)",marginTop:2}}>Projects and goals you set, tasks you check off. Pairs with the Playbook.</div>
        </div>
        <Btn v="primary" sz="sm" onClick={function(){setShowNew(function(s){return !s;});}}>{showNew?"Close":"+ New Project"}</Btn>
      </div>
      {showNew&&<Card style={{marginBottom:14}}>
        <div style={{display:"grid",gridTemplateColumns:"2fr 1fr 1fr",gap:10,marginBottom:10}}>
          <FG label="Project Name" required><input value={nf.name} onChange={setNfK("name")} placeholder="e.g. Land 3 fleet accounts" autoFocus onKeyDown={function(e){if(e.key==="Enter")addProject();}}/></FG>
          <FG label="Category"><select value={nf.cat} onChange={setNfK("cat")}>{PROJECT_CATS.map(function(c2){return <option key={c2} value={c2}>{c2}</option>;})}</select></FG>
          <FG label="Target Date"><input type="date" value={nf.targetDate} onChange={setNfK("targetDate")}/></FG>
        </div>
        <FG label="Why it matters / notes"><input value={nf.notes} onChange={setNfK("notes")} placeholder="Optional context"/></FG>
        <div style={{display:"flex",justifyContent:"flex-end",gap:8,marginTop:12}}>
          <Btn v="ghost" onClick={function(){setShowNew(false);}}>Cancel</Btn>
          <Btn v="primary" onClick={addProject} disabled={!nf.name.trim()}>Create Project</Btn>
        </div>
      </Card>}
      {projects.length===0&&!showNew&&(
        <Card style={{textAlign:"center",padding:"30px 16px"}}>
          <div style={{fontSize:32,marginBottom:8}}>🗂</div>
          <div style={{fontFamily:"var(--fd)",fontSize:15,fontWeight:800,color:"var(--txt2)",marginBottom:4}}>No Projects Yet</div>
          <div style={{fontSize:12,color:"var(--txt3)",marginBottom:14}}>Break business goals into checkable tasks. A few ideas to steal:</div>
          <div style={{display:"flex",gap:7,justifyContent:"center",flexWrap:"wrap"}}>
            {STARTERS.map(function(s){return <button key={s} onClick={function(){setNf(function(p){return Object.assign({},p,{name:s});});setShowNew(true);}} style={{background:"var(--s3)",border:"1px solid var(--bdr)",borderRadius:20,padding:"5px 14px",fontSize:12,fontFamily:"var(--fd)",fontWeight:700,color:"var(--txt2)",cursor:"pointer"}}>{s}</button>;})}
          </div>
        </Card>
      )}
      <div style={{display:"grid",gridTemplateColumns:"repeat(auto-fill,minmax(300px,1fr))",gap:12}}>
        {sorted.map(function(pr){
          var tasks=pr.tasks||[];
          var doneN=tasks.filter(function(t){return t.done;}).length;
          var pct=tasks.length>0?Math.round(doneN/tasks.length*100):0;
          var late=pr.targetDate&&pr.targetDate<TODAY&&pr.status!=="done";
          var stCol=pr.status==="done"?"var(--blu)":pr.status==="hold"?"var(--ylw)":"var(--grn)";
          return(
            <Card key={pr.id} style={pr.status==="done"?{opacity:.65}:{}}>
              <div style={{display:"flex",alignItems:"flex-start",gap:8,marginBottom:8}}>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{fontFamily:"var(--fd)",fontSize:16,fontWeight:900,lineHeight:1.2}}>{pr.name}</div>
                  <div style={{display:"flex",gap:6,alignItems:"center",marginTop:5,flexWrap:"wrap"}}>
                    <span style={{background:"var(--acc)18",border:"1px solid var(--acc)44",color:"var(--acc)",fontSize:9,fontFamily:"var(--fd)",fontWeight:800,padding:"1px 8px",borderRadius:10}}>{(pr.cat||"").toUpperCase()}</span>
                    {pr.targetDate&&<span className="mono" style={{fontSize:10,color:late?"var(--red)":"var(--txt3)"}}>{late?"PAST DUE ":"Target "}{fmtD(pr.targetDate)}</span>}
                  </div>
                </div>
                <select value={pr.status} onChange={function(e){var v=e.target.value;patchProject(pr.id,{status:v});if(v==="done"&&logAction)logAction("project_completed","project","","Project completed: "+pr.name);}} style={{width:96,fontSize:11,color:stCol,fontFamily:"var(--fd)",fontWeight:800,padding:"4px 6px"}}>
                  <option value="active">Active</option><option value="hold">On Hold</option><option value="done">Done</option>
                </select>
              </div>
              {pr.notes&&<div style={{fontSize:11,color:"var(--txt3)",marginBottom:8,lineHeight:1.4}}>{pr.notes}</div>}
              <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
                <div style={{flex:1,height:6,background:"var(--s3)",borderRadius:4,overflow:"hidden"}}><div style={{width:pct+"%",height:"100%",background:pct===100?"var(--grn)":"var(--acc)",transition:"width .25s"}}/></div>
                <span className="mono" style={{fontSize:10,color:"var(--txt3)",flexShrink:0}}>{doneN}/{tasks.length}</span>
              </div>
              <div style={{display:"flex",flexDirection:"column",gap:4,marginBottom:8}}>
                {tasks.map(function(t){
                  return(
                    <div key={t.id} style={{display:"flex",alignItems:"center",gap:7}}>
                      <label className="cb" style={t.done?{flex:1,textDecoration:"line-through",color:"var(--txt3)"}:{flex:1}}>
                        <input type="checkbox" checked={!!t.done} onChange={function(){toggleTask(pr.id,t.id);}}/>{t.label}
                      </label>
                      <button aria-label="Remove" title="Remove" onClick={function(){delTask(pr.id,t.id);}} style={{background:"none",border:"none",color:"var(--txt3)",cursor:"pointer",fontSize:14,padding:"4px 9px"}}>x</button>
                    </div>
                  );
                })}
              </div>
              <div style={{display:"flex",gap:6}}>
                <input value={taskInputs[pr.id]||""} onChange={function(e){var v=e.target.value;setTaskInputs(function(p){var n=Object.assign({},p);n[pr.id]=v;return n;});}} onKeyDown={function(e){if(e.key==="Enter")addTask(pr.id);}} placeholder="Add a task and press Enter" style={{flex:1,fontSize:12,padding:"5px 9px"}}/>
                <Btn v="subtle" sz="sm" onClick={function(){addTask(pr.id);}}>Add</Btn>
              </div>
              <div style={{marginTop:9,textAlign:"right"}}><span onClick={function(){delProject(pr.id);}} style={{fontSize:10,color:"var(--txt3)",cursor:"pointer"}}>Delete project</span></div>
            </Card>
          );
        })}
      </div>
    </div>
  );
};

/* ── BUSINESS PLAYBOOK — static, field-tested guides (no AI) ── */
const PLAYBOOK=[
  {id:"gbp",cat:"Marketing",title:"Own Your Google Business Profile",goal:"Be the mechanic who shows up when neighbors search.",steps:[
    "Create or claim your profile as a Service-Area Business \u2014 hide your home address and list the ZIP codes you cover.",
    "Set the primary category to Mobile Mechanic, with Auto Repair as a secondary.",
    "List your top 8-10 services with starting prices \u2014 'from $89' beats a blank every time.",
    "Add 3-5 photos weekly: before/after parts, your setup at a job, the work van.",
    "Reply to every review within 24 hours \u2014 replies are ranking fuel and social proof."]},
  {id:"reviews",cat:"Marketing",title:"The 5-Star Review Engine",goal:"50+ reviews is page-one gravity in most towns.",steps:[
    "Ask at the moment of relief: the car starts, the brakes are quiet, the bill was fair.",
    "Text the direct review link before you leave the driveway (save it as a phone shortcut).",
    "Aim for 2 new reviews a week \u2014 steady beats bursts.",
    "Reply to every one, good or bad, in a calm professional voice.",
    "Log the ask in the client's Communication Log so you never double-ask."],
   template:"Hey {first name}, thanks for trusting me with the {vehicle} today! If you have 30 seconds, a quick Google review really helps a small mobile shop like mine: {your review link}"},
  {id:"fleet",cat:"Marketing",title:"Fleet & Small-Business Outreach",goal:"Five fleet accounts can be half your monthly base.",steps:[
    "List 20 local outfits that drive for a living: landscapers, realtors, property managers, couriers, contractors.",
    "Pitch the one thing shops can't: you come to their lot, so trucks never sit in a waiting room.",
    "Offer a standing maintenance day (say, first Tuesday) plus net-15 invoicing.",
    "Track each prospect as a Planner project: contact found, pitch sent, follow-up, won or lost.",
    "After the first job, get the fleet manager's cell \u2014 texting beats office phones."],
   template:"Hi {name}, I'm {your name}, a mobile mechanic serving {area}. I service work trucks and fleet vehicles on-site \u2014 your crews keep working while I handle oil, brakes, and repairs in your lot. Could I drop off a fleet rate sheet this week?"},
  {id:"referral",cat:"Marketing",title:"A Referral Loop That Runs Itself",goal:"Your happiest clients are a free sales team.",steps:[
    "Offer $25 off for both sides \u2014 the referrer and the new client.",
    "Say it out loud after every good job, and print it on the invoice footer.",
    "Record the referral source in the new client's notes so credits never get missed.",
    "Text a thank-you the day a referral books \u2014 that's what triggers the next one."]},
  {id:"content",cat:"Marketing",title:"Before/After Content That Sells",goal:"Proof beats promises \u2014 and it's free.",steps:[
    "Shoot the worn part next to the new one on a clean fender towel \u2014 one photo, instant trust.",
    "Post 3x a week to Facebook, Instagram, and Nextdoor \u2014 Nextdoor is gold for mobile work.",
    "Always name the town and vehicle: 'Wheel bearing, 2014 F-150, Conway driveway.'",
    "Answer every 'anyone know a good mechanic?' thread fast, friendly, never pushy.",
    "Get permission before posting anything that identifies a client's home or plate."]},
  {id:"pricing",cat:"How-To",title:"Price Jobs Profitably",goal:"Price to the value of driveway service \u2014 not to beat shops.",steps:[
    "Know your true cost per billable hour: insurance, fuel, tools, phone, and taxes divided by the hours you actually wrench.",
    "Formula: (labor hours \u00d7 your rate) + (parts cost \u00f7 0.6 for a 40% margin) + a travel fee by zone.",
    "Quote ranges on diagnostic work ('$150-250 depending on findings') and confirm before exceeding.",
    "Revisit your labor rate every quarter in Settings \u2014 supplies inflate, so should the rate.",
    "Never apologize for a fair price. You bring the shop to them."]},
  {id:"payment",cat:"How-To",title:"Deposits, Payment & No-Shows",goal:"Cash-flow discipline is what keeps mobile shops alive.",steps:[
    "Parts over $150? Collect the parts cost up front \u2014 every time, no exceptions.",
    "Send the estimate first (Estimates page) and get a written 'yes' by text before ordering.",
    "Payment is due on completion, before you pack up \u2014 card, cash, or instant transfer.",
    "Confirm every appointment the evening before with a one-line text.",
    "One free reschedule; repeat no-shows prepay or wait."]},
  {id:"comeback",cat:"How-To",title:"Handle Comebacks & Warranty Right",goal:"A comeback handled well creates a client for life.",steps:[
    "Respond the same day and inspect free \u2014 speed defuses frustration.",
    "Your part or labor? Fix it free, fast, no argument. It's the cheapest marketing alive.",
    "Unrelated failure? Show-and-tell with photos so they see it, then quote it as new work.",
    "Document everything in the job's notes and photos \u2014 memory fades, records don't.",
    "Your invoices already print parts and shop warranty terms \u2014 point to them calmly."]},
  {id:"admin",cat:"How-To",title:"The 20-Minute Daily Admin Routine",goal:"Paperwork done daily never becomes a pile.",steps:[
    "Morning (5 min): Schedule \u2192 Agenda view, tap Route for the day's stops, confirm parts on hand.",
    "After each job (5 min, still in the driveway): photos, job notes, invoice sent, payment logged.",
    "Evening (7 min): log calls and texts in Communication Logs, set follow-ups, build tomorrow's parts list.",
    "Friday (3 min): Reports page \u2014 revenue vs expenses, top clients, what to repeat next week."]},
  {id:"scale",cat:"How-To",title:"Scale Without Breaking",goal:"Grow deliberately \u2014 capacity first, then people.",steps:[
    "You're ready when you've been booked 2+ weeks out for 6 straight weeks and decline work weekly.",
    "The ladder: raise rates 10-15% \u2192 add a distance fee for far zones \u2192 part-time helper on brake/oil days \u2192 second van.",
    "Fleet accounts are your base load \u2014 protect them with reliability before chasing one-offs.",
    "Every helper works from a checklist (Templates page) \u2014 your reputation rides in their hands.",
    "Update insurance before the first helper turns a wrench, not after."]}
];
const PlaybookPage=()=>{
  const[cat,setCat]=useState("All");
  const[open,setOpen]=useState({});
  var cats=["All","Marketing","How-To"];
  var list=PLAYBOOK.filter(function(g){return cat==="All"||g.cat===cat;});
  const toggle=function(id){setOpen(function(p){var n=Object.assign({},p);n[id]=!p[id];return n;});};
  return(
    <div className="fade" style={{paddingBottom:24,maxWidth:780}}>
      <div style={{marginBottom:12}}>
        <div style={{fontFamily:"var(--fd)",fontSize:26,fontWeight:900}}>BUSINESS <span style={{color:"var(--acc)"}}>PLAYBOOK</span></div>
        <div style={{fontSize:11,color:"var(--txt3)",marginTop:2}}>Field-tested marketing plays and how-to guides {"\u2014"} general business information, not legal, tax, or financial advice. Read a play, then turn it into tasks in the Planner.</div>
      </div>
      <div style={{display:"flex",gap:6,marginBottom:14,flexWrap:"wrap"}}>
        {cats.map(function(c2){var a=cat===c2;return <button key={c2} onClick={function(){setCat(c2);}} style={{padding:"5px 15px",borderRadius:20,border:"1px solid "+(a?"var(--acc)":"var(--bdr)"),background:a?"var(--acc)18":"var(--s3)",color:a?"var(--acc)":"var(--txt3)",fontSize:12,fontFamily:"var(--fd)",fontWeight:800,cursor:"pointer"}}>{c2}</button>;})}
      </div>
      <div style={{display:"flex",flexDirection:"column",gap:10}}>
        {list.map(function(g){
          var isOpen=!!open[g.id];
          var catCol=g.cat==="Marketing"?"var(--acc)":"var(--blu)";
          return(
            <Card key={g.id}>
              <div style={{display:"flex",alignItems:"flex-start",gap:10,cursor:"pointer"}} onClick={function(){toggle(g.id);}}>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap"}}>
                    <span style={{background:catCol+"18",border:"1px solid "+catCol+"44",color:catCol,fontSize:9,fontFamily:"var(--fd)",fontWeight:800,padding:"1px 8px",borderRadius:10}}>{g.cat.toUpperCase()}</span>
                    <span style={{fontFamily:"var(--fd)",fontSize:16,fontWeight:900}}>{g.title}</span>
                  </div>
                  <div style={{fontSize:12,color:"var(--txt3)",marginTop:4}}>{g.goal}</div>
                </div>
                <span style={{fontFamily:"var(--fd)",fontSize:11,fontWeight:800,color:"var(--acc)",flexShrink:0,paddingTop:3}}>{isOpen?"CLOSE":"READ THE PLAY"}</span>
              </div>
              {isOpen&&<div className="fade" style={{marginTop:12,borderTop:"1px solid var(--bdr)",paddingTop:12}}>
                <div style={{display:"flex",flexDirection:"column",gap:8}}>
                  {g.steps.map(function(s,i){
                    return(
                      <div key={i} style={{display:"flex",gap:10,alignItems:"flex-start"}}>
                        <span style={{background:"var(--s3)",border:"1px solid var(--bdr)",color:"var(--acc)",fontFamily:"var(--fm)",fontSize:11,width:22,height:22,borderRadius:"50%",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{i+1}</span>
                        <span style={{fontSize:13,color:"var(--txt2)",lineHeight:1.55}}>{s}</span>
                      </div>
                    );
                  })}
                </div>
                {g.template&&<div style={{marginTop:12}}>
                  <Lbl>Copy-and-personalize template</Lbl>
                  <textarea readOnly value={g.template} onFocus={function(e){e.target.select();}} style={{minHeight:74,fontFamily:"var(--fm)",fontSize:11,lineHeight:1.6}}/>
                  <div style={{fontSize:10,color:"var(--txt3)",marginTop:4}}>Tap the box to select it all, then copy and swap the {"{placeholders}"}.</div>
                </div>}
              </div>}
            </Card>
          );
        })}
      </div>
    </div>
  );
};

function AppInner(){
  const[user,setUser]=useState(null);
  const[accounts,setAccounts]=useState([]);
  const[lastEmail,setLastEmail]=useState("");
  const[page,setPage]=useState("dashboard");
  const[customers,setCust]=useState([]);
  const[vehicles,setVeh]=useState([]);
  const[jobs,setJobs]=useState([]);
  const[selJob,setSelJob]=useState(null);
  const[showNewJob,setNewJob]=useState(false);
  const[newJobPrefill,setNewJobPrefill]=useState({});
  const[sideOpen,setSideOpen]=useState(false);
  const[archClients,setArchClients]=useState([]);
  const[archVehicles,setArchVehicles]=useState([]);
  const[archJobs,setArchJobs]=useState([]);
  const[blocks,setBlocks]=useState([]);
  const[invoices,setInvoices]=useState([]);
  const[selInvoice,setSelInvoice]=useState(null);
  const[estimates,setEstimates]=useState([]);
  const[expenses,setExpenses]=useState([]);
  const[auditLog,setAuditLog]=useState([]);
  const[dismissedRem,setDismissedRem]=useState({});
  const[comms,setComms]=useState([]);
  const[projects,setProjects]=useState([]);
  const[partQuotes,setPartQuotes]=useState([]);
  const[booting,setBooting]=useState(false);
  const[saveWarn,setSaveWarn]=useState(false);
  const[showSearch,setShowSearch]=useState(false);
  const[settings,setSettings]=useState(Object.assign({},MM_EMPTY_SETTINGS));
  const hydrating=useRef(false);
  const accountsRef=useRef([]);
  const lastEmailRef=useRef("");
  const[isMobile,setIsMobile]=useState((typeof window!=="undefined")&&window.innerWidth<820);
  const[moreOpen,setMoreOpen]=useState(false);

  const logAction=function(action,entity,entityId,summary,fields){
    setAuditLog(function(prev){return[{id:uid(),timestamp:new Date().toISOString(),action:action,entity:entity,entityId:entityId||"",summary:summary,fields:fields||[],user:(user&&user.name)||"User"},...prev];});
  };

  // Load a data blob into every working-state slice (empty defaults when absent).
  const hydrateWorkspace=function(d){
    d=d||{};
    setCust(d.customers||[]);setVeh(d.vehicles||[]);setJobs(d.jobs||[]);setBlocks(d.blocks||[]);
    setInvoices(d.invoices||[]);setEstimates(d.estimates||[]);setExpenses(d.expenses||[]);
    setAuditLog(d.auditLog||[]);setDismissedRem(d.dismissedRem||{});
    setComms(d.comms||[]);setProjects(d.projects||[]);setPartQuotes(d.partQuotes||[]);
    setArchClients(d.archClients||[]);setArchVehicles(d.archVehicles||[]);setArchJobs(d.archJobs||[]);
    setSettings(Object.assign({},MM_EMPTY_SETTINGS,d.settings||{}));
  };
  // Wipe the working state so nothing from one account is visible to the next.
  const resetWorkspace=function(){hydrateWorkspace({});setSelJob(null);setSelInvoice(null);setNewJob(false);setNewJobPrefill({});setShowSearch(false);setMoreOpen(false);};

  // On first mount, restore the saved accounts registry (so logins survive a refresh).
  useEffect(function(){
    mmLoad("mm:accounts").then(function(d){
      if(d&&d.accounts){accountsRef.current=d.accounts;setAccounts(d.accounts);}
      if(d&&d.lastEmail){lastEmailRef.current=d.lastEmail;setLastEmail(d.lastEmail);}
    });
  },[]);

  // Expose the optional AI key (used only when self-hosting) to the planner fetch.
  useEffect(function(){try{if(typeof window!=="undefined")window.MM_ANTHROPIC_KEY=(settings&&settings.aiKey)?settings.aiKey:"";}catch(e){}},[settings]);

  // Track viewport for the mobile-first / desktop layout switch.
  useEffect(function(){
    var onR=function(){setIsMobile(window.innerWidth<820);};
    window.addEventListener("resize",onR);onR();
    return function(){window.removeEventListener("resize",onR);};
  },[]);

  // Persist the current account's workspace on every change (skipped while a
  // login is hydrating, and skipped entirely when signed out — the signed-out
  // reset therefore never overwrites a stored account's data).
  useEffect(function(){
    if(!user)return;if(hydrating.current)return;
    mmSave("mm:data:"+user.id,{customers:customers,vehicles:vehicles,jobs:jobs,blocks:blocks,invoices:invoices,estimates:estimates,expenses:expenses,auditLog:auditLog,dismissedRem:dismissedRem,archClients:archClients,archVehicles:archVehicles,archJobs:archJobs,settings:settings,comms:comms,projects:projects,partQuotes:partQuotes}).then(function(ok){setSaveWarn(!ok);});
  },[user,customers,vehicles,jobs,blocks,invoices,estimates,expenses,auditLog,dismissedRem,archClients,archVehicles,archJobs,settings,comms,projects,partQuotes]);

  const persistAccounts=function(list,le){mmSave("mm:accounts",{accounts:list,lastEmail:(le!==undefined?le:lastEmailRef.current)});};

  const handleLogin=function(acct){
    hydrating.current=true;setBooting(true);
    setUser(acct);setLastEmail(acct.email);lastEmailRef.current=acct.email;setPage("dashboard");
    persistAccounts(accountsRef.current,acct.email);
    mmLoad("mm:data:"+acct.id).then(function(d){
      if(d){hydrateWorkspace(d);}
      else{hydrateWorkspace({});setSettings(function(p){return Object.assign({},p,{shopName:acct.company||acct.name,email:acct.email,logo:acct.pic||null});});}
      hydrating.current=false;setBooting(false);
    }).catch(function(){hydrateWorkspace({});hydrating.current=false;setBooting(false);});
    // One-time transparent upgrade: legacy plaintext password -> SHA-256 hash.
    if(acct.password&&String(acct.password).indexOf("sha256:")!==0){
      mmHash(acct.password).then(function(h){
        if(!h)return;
        var upd=accountsRef.current.map(function(a){return a.id===acct.id?Object.assign({},a,{password:h}):a;});
        accountsRef.current=upd;setAccounts(upd);persistAccounts(upd,acct.email);
      });
    }
  };
  const handleRegister=function(acct){
    var next=accountsRef.current.concat([acct]);
    accountsRef.current=next;setAccounts(next);
    persistAccounts(next,acct.email);
    // Seed a fresh, isolated data blob for the new account immediately.
    mmSave("mm:data:"+acct.id,{customers:[],vehicles:[],jobs:[],blocks:[],invoices:[],estimates:[],expenses:[],auditLog:[{id:uid(),timestamp:new Date().toISOString(),action:"account_created",entity:"account",entityId:"",summary:"Account created: "+acct.name+" — Terms of Use accepted",fields:[],user:acct.name}],dismissedRem:{},comms:[],projects:[],partQuotes:[],archClients:[],archVehicles:[],archJobs:[],settings:Object.assign({},MM_EMPTY_SETTINGS,{shopName:acct.company||acct.name,email:acct.email,logo:acct.pic||null})});
  };
  const handleSignOut=function(){setUser(null);setSideOpen(false);setMoreOpen(false);resetWorkspace();};

  // ── Invoice creation from a job ──
  const createInvoiceFromJob=function(jobId){
    var j=jobs.find(function(x){return x.id===jobId;});if(!j)return;
    var laborItems=(j.services||[]).map(function(s){return{name:s.name,hours:s.laborHours,rate:s.laborRate};});
    var partItems=(j.parts||[]).map(function(p){return{name:p.name,qty:p.qty,sell:p.sell};});
    var invId=genInvId(j.customerId||"0000XX000",invoices);
    var uniqueSvcs=[];
    (j.services||[]).forEach(function(s){if(uniqueSvcs.indexOf(s.name)<0)uniqueSvcs.push(s.name);});
    var shopWarranties=uniqueSvcs.map(function(name,i){var w=svcWarranty(name);return{service:name,dur:w.dur,term:w.term,checked:false,warId:genWarId(invId,i)};});
    var inv={id:uid(),invId:invId,jobId:j.id,jobDisplayId:dispJobId(j.jobId),customerId:j.customerId,vehicleId:j.vehicleId,odometer:j.odometer||"",createdAt:new Date().toISOString(),issuedDate:TODAY,status:"issued",laborItems:laborItems,partItems:partItems,taxRate:(+settings.taxRate||7.5)/100,payments:[],partsWarranties:{},shopWarranties:shopWarranties,notes:""};
    setInvoices(function(p){return[inv,...p];});
    logAction("invoice_created","invoice",invId,"Invoice "+invId+" created from job "+dispJobId(j.jobId)+" — "+fmt$(invTotals(inv).total));
    setSelInvoice(inv.id);setPage("invoice-detail");
  };
  const updateInvoice=function(inv){setInvoices(function(p){return p.map(function(x){return x.id===inv.id?inv:x;});});};

  // ── Estimate conversion ──
  const convertEstimate=function(est){
    var newJob={id:uid(),jobId:genJobId(est.vehicleId||"V00-0000XX000",jobs.concat(archJobs)),customerId:est.customerId,vehicleId:est.vehicleId,scheduledDate:TODAY,scheduledTime:"09:00",status:"upcoming",loggedVia:"estimate",services:(est.services||[]).map(function(s){return{id:uid(),name:s.name,laborHours:s.laborHours,laborRate:s.laborRate};}),parts:[],notes:est.notes?"From estimate "+est.estId+": "+est.notes:"From estimate "+est.estId,photos:[]};
    setJobs(function(p){return[...p,newJob];});
    setEstimates(function(p){return p.map(function(x){return x.id===est.id?Object.assign({},x,{status:"converted"}):x;});});
    logAction("estimate_converted","estimate",est.estId,"Estimate "+est.estId+" converted to job "+dispJobId(newJob.jobId));
    setSelJob(newJob.id);setPage("job-detail");
  };

  // ── Backup export / import ──
  const exportBackup=function(){
    var exportSettings=Object.assign({},settings);delete exportSettings.aiKey; // never write secrets into backup files
    var data={version:1,exportedAt:new Date().toISOString(),customers:customers,vehicles:vehicles,jobs:jobs,blocks:blocks,invoices:invoices,estimates:estimates,expenses:expenses,comms:comms,projects:projects,partQuotes:partQuotes,auditLog:auditLog,settings:exportSettings,archClients:archClients,archVehicles:archVehicles,archJobs:archJobs};
    var json=JSON.stringify(data);
    var a=document.createElement("a");a.href="data:application/json;charset=utf-8,"+encodeURIComponent(json);a.download="mobile-mechanic-backup-"+TODAY+".json";document.body.appendChild(a);a.click();document.body.removeChild(a);
    logAction("backup_exported","account","","Workspace backup downloaded");
  };
  const importBackup=function(e){
    var file=e.target.files[0];if(!file)return;
    var r=new FileReader();
    r.onload=function(ev){
      try{
        var d=JSON.parse(ev.target.result);
        if(!d||typeof d!=="object"||(!Array.isArray(d.customers)&&!Array.isArray(d.jobs))){window.alert("That file doesn't look like a Mobile Mechanic backup (.json). Nothing was changed.");return;}
        if(!window.confirm("Restore this backup?\n\nIt will REPLACE everything currently in this workspace with the backup contents.")){return;}
        if(d.customers)setCust(d.customers);if(d.vehicles)setVeh(d.vehicles);if(d.jobs)setJobs(d.jobs);
        if(d.blocks)setBlocks(d.blocks);if(d.invoices)setInvoices(d.invoices);if(d.estimates)setEstimates(d.estimates);
        if(d.expenses)setExpenses(d.expenses);if(d.auditLog)setAuditLog(d.auditLog);if(d.settings)setSettings(d.settings);
        if(d.comms)setComms(d.comms);if(d.projects)setProjects(d.projects);if(d.partQuotes)setPartQuotes(d.partQuotes);
        if(d.archClients)setArchClients(d.archClients);if(d.archVehicles)setArchVehicles(d.archVehicles);if(d.archJobs)setArchJobs(d.archJobs);
        logAction("backup_imported","account","","Workspace restored from backup file");
        window.alert("Backup restored successfully.");
      }catch(err){window.alert("Could not read that backup file. Make sure it is an unmodified Mobile Mechanic backup .json.");}
    };
    r.readAsText(file);
  };

  if(!user) return <LoginScreen onLogin={handleLogin} accounts={accounts} onRegister={handleRegister} lastEmail={lastEmail}/>;

  const go=p=>{setPage(p);setSelJob(null)};
  const selectJob=id=>{setSelJob(id);setPage("job-detail")};
  const updateJob=function(j){
    var old=jobs.find(function(x){return x.id===j.id;});
    setJobs(prev=>prev.map(x=>x.id===j.id?j:x));
    if(old){
      var fields=[];
      var watch=["status","scheduledDate","scheduledTime","location","notes","odometer"];
      watch.forEach(function(k){if(String(old[k]||"")!==String(j[k]||""))fields.push({field:k,from:old[k]||"",to:j[k]||""});});
      if((old.services||[]).length!==(j.services||[]).length)fields.push({field:"services count",from:(old.services||[]).length,to:(j.services||[]).length});
      if((old.parts||[]).length!==(j.parts||[]).length)fields.push({field:"parts count",from:(old.parts||[]).length,to:(j.parts||[]).length});
      if(fields.length)logAction("job_updated","job",dispJobId(j.jobId),"Job "+dispJobId(j.jobId)+" updated",fields);
    }
  };
  const activeCount=jobs.filter(j=>j.scheduledDate===TODAY&&j.status==="in-progress").length;
  const archCount=archClients.length+archVehicles.length+archJobs.length;
  const archiveJob=id=>{const j=jobs.find(x=>x.id===id);if(!j)return;setArchJobs(p=>[...p,j]);setJobs(p=>p.filter(x=>x.id!==id));logAction("job_archived","job",dispJobId(j.jobId),"Job "+dispJobId(j.jobId)+" archived");if(selJob===id){setSelJob(null);setPage("jobs");}};
  const archiveClient=id=>{const c=customers.find(x=>x.id===id);if(!c)return;setArchClients(p=>[...p,c]);setCust(p=>p.filter(x=>x.id!==id));logAction("client_archived","client",dispCustId(c.id),"Client "+fullName(c)+" archived");};
  const updateClient=function(updated){
    var old=customers.find(function(x){return x.id===updated.id;});
    setCust(function(prev){return prev.map(function(x){return x.id===updated.id?updated:x;});});
    if(old){
      var fields=[];
      ["firstName","lastName","phone","phoneType","email","street","city","state","zip","notes"].forEach(function(k){if(String(old[k]||"")!==String(updated[k]||""))fields.push({field:k,from:old[k]||"",to:updated[k]||""});});
      if(fields.length)logAction("client_updated","client",dispCustId(updated.id),"Client "+fullName(updated)+" details updated",fields);
    }
  };
  const addComm=function(entry){setComms(function(p){return [entry].concat(p);});var c=customers.find(function(x){return x.id===entry.customerId;});logAction("comm_logged","client",dispCustId(entry.customerId),(entry.channel||"Note")+" logged"+(c?" for "+fullName(c):""));};
  const updateComm=function(id,patch){setComms(function(p){return p.map(function(cm){return cm.id===id?Object.assign({},cm,patch):cm;});});};
  const deleteComm=function(id){setComms(function(p){return p.filter(function(cm){return cm.id!==id;});});};
  const restoreItems=(type,ids)=>{const s=new Set(ids);if(type==="clients"){const r=archClients.filter(c=>s.has(c.id));setCust(p=>[...p,...r]);setArchClients(p=>p.filter(c=>!s.has(c.id)));}else if(type==="vehicles"){const r=archVehicles.filter(v=>s.has(v.id));setVeh(p=>[...p,...r]);setArchVehicles(p=>p.filter(v=>!s.has(v.id)));}else{const r=archJobs.filter(j=>s.has(j.id));setJobs(p=>[...p,...r]);setArchJobs(p=>p.filter(j=>!s.has(j.id)));}};
  const openNewJob=(prefill={})=>{setNewJobPrefill(prefill);setNewJob(true);};

  const openInvCount=invoices.filter(function(inv){return inv.status==="issued"||inv.status==="partial";}).length;
  const dueFollowUps=comms.filter(function(cm){return cm.followUp&&!cm.done&&cm.followUpDate&&cm.followUpDate<=TODAY;}).length;
  const NAV=[
    {id:"dashboard",icon:"⊞",label:"Dashboard"},
    {id:"search",icon:"🔎",label:"Search",isSearch:true},
    {id:"schedule",icon:"📅",label:"Schedule",badge:jobs.filter(j=>j.scheduledDate===TODAY).length||null},
    {id:"jobs",icon:"🔧",label:"Jobs",badge:activeCount||null},
    {id:"estimates",icon:"📝",label:"Estimates",badge:estimates.filter(function(e){return e.status==="open";}).length||null},
    {id:"invoices",icon:"🧾",label:"Invoices",badge:openInvCount||null},
    {id:"reminders",icon:"🔔",label:"Reminders",badge:dueFollowUps||null},
    {id:"clients",icon:"👤",label:"Clients",badge:customers.length||null},
    {id:"parts",icon:"🔍",label:"Parts Lookup"},
    {id:"templates",icon:"📋",label:"Templates"},
    {id:"planner",icon:"🗂",label:"Planner",badge:projects.filter(function(p){return p.status==="active";}).length||null},
    {id:"playbook",icon:"📖",label:"Playbook"},
    {id:"reports",icon:"📊",label:"Reports"},
    {id:"audit",icon:"🕐",label:"Audit Log"},
    {id:"settings",icon:"⚙",label:"Settings"},
    {id:"archive",icon:"🗄",label:"Archive",badge:archCount||null,accent:true},
  ];
  const primaryIds=["dashboard","schedule","jobs","clients"];
  const mobileTabs=[
    {id:"dashboard",icon:"⊞",label:"Home"},
    {id:"schedule",icon:"📅",label:"Schedule",badge:jobs.filter(j=>j.scheduledDate===TODAY).length||null},
    {id:"jobs",icon:"🔧",label:"Jobs",badge:activeCount||null},
    {id:"clients",icon:"👤",label:"Clients",badge:customers.length||null},
    {id:"more",icon:"☰",label:"More"}
  ];
  var curNavItem=NAV.find(function(n){return n.id===page;});
  var pageTitle="Mobile Mechanic";
  if(curNavItem)pageTitle=curNavItem.label;
  else if(page==="job-detail")pageTitle="Job Detail";
  else if(page==="invoice-detail")pageTitle="Invoice";

  return(
    <div style={{position:"relative",height:"100vh",overflow:"hidden",background:"var(--bg)"}}>
      <GS/>
      {saveWarn&&<div role="alert" style={{position:"fixed",top:0,left:0,right:0,zIndex:4000,background:"var(--red)",color:"#fff",fontSize:12,fontFamily:"var(--fd)",fontWeight:800,letterSpacing:".03em",textAlign:"center",padding:"7px 12px"}}>DEVICE STORAGE FULL OR UNAVAILABLE {"\u2014"} recent changes may not be saving. Export a backup now (Settings {"\u2192"} Data Backup) and remove large photos.</div>}
      {booting&&<div style={{position:"fixed",inset:0,zIndex:3500,background:"#07090b",display:"flex",alignItems:"center",justifyContent:"center"}}><div style={{textAlign:"center"}}><HexSpinner/><div style={{marginTop:14,fontFamily:"var(--fd)",fontSize:13,fontWeight:800,color:"var(--txt3)",letterSpacing:".1em"}}>LOADING YOUR SHOP...</div></div></div>}
      {showSearch&&<SearchModal onClose={function(){setShowSearch(false);}} customers={customers} vehicles={vehicles} jobs={jobs} invoices={invoices} onSelectJob={selectJob} onGoClients={function(){go("clients");}} onOpenInvoice={function(id){setSelInvoice(id);setPage("invoice-detail");}}/>}
      {/* SIDEBAR OVERLAY backdrop (desktop only) */}
      {!isMobile&&sideOpen&&<div onClick={()=>setSideOpen(false)} style={{position:"fixed",inset:0,zIndex:150,background:"transparent"}}/>}
      {/* DESKTOP SIDEBAR */}
      {!isMobile&&(
      <div style={{position:"fixed",left:0,top:0,height:"100vh",zIndex:160,display:"flex",flexDirection:"column",width:sideOpen?172:46,transition:"width .2s ease",background:sideOpen?"rgba(10,14,17,0.94)":"var(--s1)",backdropFilter:sideOpen?"blur(14px)":"none",borderRight:"1px solid var(--bdr)",boxShadow:sideOpen?"6px 0 28px #000c":"none"}}>
        {/* Profile — always visible, never hidden */}
        <div style={{padding:"10px 5px 8px",borderBottom:"1px solid var(--bdr)",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,minHeight:58,overflow:"hidden"}}>
          {/* Avatar always shown */}
          <div style={{flexShrink:0,cursor:"pointer"}} onClick={()=>setSideOpen(o=>!o)}>
            <div className="hex-glow" style={{width:sideOpen?34:28,height:sideOpen?34:28,transition:"width .2s,height .2s",position:"relative"}}>
              <div style={{position:"absolute",inset:0,clipPath:"polygon(50% 0%,100% 25%,100% 75%,50% 100%,0% 75%,0% 25%)",background:"linear-gradient(145deg,#8a9aaa,#4a5568,#1a2332,#5a6a7a)"}}/>
              <div style={{position:"absolute",inset:"8%",clipPath:"polygon(50% 0%,100% 25%,100% 75%,50% 100%,0% 75%,0% 25%)",background:"#1e2a36",overflow:"hidden"}}>
                {user.pic?<img src={user.pic} style={{width:"100%",height:"100%",objectFit:"cover"}} alt=""/>:null}
              </div>
              {!user.pic&&<div style={{position:"absolute",width:"46%",height:"46%",top:"50%",left:"50%",transform:"translate(-50%,-50%)",borderRadius:"50%",background:"var(--acc)",display:"flex",alignItems:"center",justifyContent:"center"}}>
                <span style={{fontFamily:"var(--fd)",fontWeight:900,fontSize:sideOpen?12:10,color:"#fff"}}>{((user.name&&user.name[0]&&user.name[0].toUpperCase())||"M")}</span>
              </div>}
            </div>
          </div>
          {/* Name — only when expanded */}
          {sideOpen&&<div style={{flex:1,minWidth:0,marginLeft:9}}>
            <div style={{fontFamily:"var(--fd)",fontSize:13,fontWeight:900,lineHeight:1.1,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{user.name||"My Shop"}</div>
            {user.company&&<div style={{fontSize:9,color:"var(--txt3)",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{user.company}</div>}
          </div>}
        </div>
        {/* Nav items */}
        <nav style={{padding:"6px 4px",flex:1,overflowY:"auto"}}>
          {NAV.map(function(n){const active=page===n.id||(page==="job-detail"&&n.id==="jobs");return(
            <button key={n.id} onClick={function(){if(n.isSearch){setShowSearch(true);setSideOpen(false);return;}go(n.id);setSideOpen(false);}} title={!sideOpen?n.label:undefined}
              style={{width:"100%",display:"flex",alignItems:"center",justifyContent:sideOpen?"space-between":"center",padding:sideOpen?"7px 10px":"8px 0",borderRadius:"var(--r)",background:active?"var(--s3)":"transparent",color:active?(n.accent?"var(--ylw)":"var(--acc)"):n.accent?"var(--txt3)":"var(--txt2)",border:"none",cursor:"pointer",fontSize:12,fontFamily:"var(--fd)",fontWeight:800,letterSpacing:".06em",textAlign:"left",marginBottom:2,transition:".15s",position:"relative"}}>
              <span style={{display:"flex",gap:sideOpen?7:0,alignItems:"center"}}><span style={{fontSize:sideOpen?13:17}}>{n.icon}</span>{sideOpen&&n.label}</span>
              {sideOpen&&n.badge&&<span style={{background:n.accent?"var(--ylw)":"var(--acc)",color:n.accent?"#000":"#fff",fontSize:9,fontFamily:"var(--fm)",padding:"1px 5px",borderRadius:8,fontWeight:700}}>{n.badge}</span>}
              {!sideOpen&&n.badge&&<span style={{position:"absolute",top:4,right:2,background:n.accent?"var(--ylw)":"var(--acc)",color:n.accent?"#000":"#fff",fontSize:7,fontFamily:"var(--fm)",padding:"0 3px",borderRadius:6,fontWeight:700,lineHeight:"12px"}}>{n.badge}</span>}
            </button>
          );})}
        </nav>
        {/* Footer — time/version when expanded, collapse toggle always at bottom */}
        <div style={{borderTop:"1px solid var(--bdr)",flexShrink:0}}>
          {sideOpen&&<div style={{padding:"7px 12px"}}>
            <div style={{display:"flex",justifyContent:"space-between",fontSize:9,color:"var(--txt3)"}}><span className="mono">{new Date().toLocaleTimeString("en-US",{hour:"2-digit",minute:"2-digit"})}</span><span>v1.0.0</span></div>
            <div style={{fontSize:9,color:"var(--txt3)",marginTop:1}}>{customers.length} clients · {vehicles.length} vehicles</div>
            <div style={{marginTop:6,fontSize:10,color:"var(--txt3)",cursor:"pointer"}} onClick={handleSignOut}>Sign Out</div>
          </div>}
          {/* Collapse / expand arrow — always at bottom */}
          <button onClick={function(){setSideOpen(function(o){return !o;});}} style={{width:"100%",display:"flex",alignItems:"center",justifyContent:"center",padding:"8px 0",background:"none",border:"none",borderTop:"1px solid var(--bdr)",cursor:"pointer",color:"var(--txt3)",fontSize:11,fontFamily:"var(--fd)",fontWeight:800,transition:".15s"}}
            onMouseEnter={function(e){e.currentTarget.style.color="var(--acc)";e.currentTarget.style.background="var(--s3)";}}
            onMouseLeave={function(e){e.currentTarget.style.color="var(--txt3)";e.currentTarget.style.background="none";}}>
            {sideOpen?"« CLOSE":"»"}
          </button>
        </div>
      </div>
      )}
      {/* MOBILE TOP BAR */}
      {isMobile&&(
        <div style={{position:"fixed",top:0,left:0,right:0,height:52,zIndex:140,background:"var(--s1)",borderBottom:"1px solid var(--bdr)",display:"flex",alignItems:"center",gap:8,padding:"0 10px"}}>
          <button onClick={function(){setMoreOpen(true);}} aria-label="Menu" style={{background:"none",border:"none",color:"var(--txt)",width:36,height:36,display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer"}}>
            <svg width="20" height="14" viewBox="0 0 20 14"><rect width="20" height="2" rx="1" fill="currentColor"/><rect y="6" width="20" height="2" rx="1" fill="currentColor"/><rect y="12" width="20" height="2" rx="1" fill="currentColor"/></svg>
          </button>
          <div style={{flex:1,minWidth:0,fontFamily:"var(--fd)",fontSize:16,fontWeight:900,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{pageTitle}</div>
          <button onClick={function(){setShowSearch(true);}} aria-label="Search" style={{background:"none",border:"none",color:"var(--txt2)",width:36,height:36,display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer"}}>
            <svg width="17" height="17" viewBox="0 0 17 17" fill="none"><circle cx="7" cy="7" r="5.2" stroke="currentColor" strokeWidth="1.8"/><line x1="11" y1="11" x2="16" y2="16" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round"/></svg>
          </button>
        </div>
      )}
      {/* MAIN — full width; padding adapts to sidebar (desktop) or bars (mobile) */}
      <div style={isMobile?{marginLeft:0,height:"100vh",overflowY:"auto",padding:"62px 12px 78px",WebkitOverflowScrolling:"touch"}:{marginLeft:46,height:"100vh",overflowY:"auto",padding:"18px 20px"}}>
        {page==="dashboard"  &&<Dashboard jobs={jobs} customers={customers} vehicles={vehicles} onSelectJob={selectJob} onNewJob={()=>openNewJob()} goClients={()=>go("clients")} goVehicles={()=>go("clients")} user={user} settings={settings} goSettings={()=>go("settings")} goPlaybook={()=>go("playbook")}/>}
        {page==="schedule"   &&<SchedulePage jobs={jobs} customers={customers} vehicles={vehicles} onSelectJob={selectJob} onNewJob={openNewJob} blocks={blocks} setBlocks={function(fn){setBlocks(function(prev){var next=typeof fn==="function"?fn(prev):fn;if(next.length>prev.length){var nb=next[next.length-1];logAction("block_created","block","","Time block saved: "+nb.label+" ("+fmtD(nb.date)+")");}else if(next.length<prev.length){logAction("block_deleted","block","","Time block removed");}return next;});}}/>}
        {page==="jobs"       &&<JobsBoard jobs={jobs} customers={customers} vehicles={vehicles} onSelectJob={selectJob} onNewJob={()=>openNewJob()} onArchiveJob={archiveJob}/>}
        {page==="job-detail" &&selJob&&<JobDetail job={jobs.find(j=>j.id===selJob)} customers={customers} vehicles={vehicles} onBack={()=>go("jobs")} onUpdate={updateJob} onArchive={archiveJob} onCreateInvoice={createInvoiceFromJob} hasInvoice={invoices.some(function(inv){return inv.jobId===selJob;})} settings={settings}/>}
        {page==="parts"      &&<PartsLookup vehicles={vehicles} customers={customers} quotes={partQuotes} setQuotes={setPartQuotes} logAction={logAction}/>}
        {page==="clients"    &&<CustomersPage customers={customers} vehicles={vehicles} jobs={jobs} archVehicles={archVehicles} setCust={function(fn){setCust(function(prev){var next=typeof fn==="function"?fn(prev):fn;if(next.length>prev.length){var nc=next[next.length-1];logAction("client_created","client",dispCustId(nc.id),"Client "+fullName(nc)+" added");}return next;});}} setVeh={function(fn){setVeh(function(prev){var next=typeof fn==="function"?fn(prev):fn;if(next.length>prev.length){var nv=next[next.length-1];logAction("vehicle_created","vehicle",dispVehId(nv.vehicleId),(nv.year||"")+" "+(nv.make||"")+" "+(nv.model||"")+" added");}return next;});}} onSelectJob={selectJob} onArchiveClient={archiveClient} onNewJob={openNewJob} settings={settings} onUpdateClient={updateClient} comms={comms} onAddComm={addComm} onUpdateComm={updateComm} onDeleteComm={deleteComm}/>}
        {page==="templates"  &&<TemplatesPage onNewJob={()=>openNewJob()} customers={customers} vehicles={vehicles} jobs={jobs}/>}
        {page==="planner"    &&<PlannerPage projects={projects} setProjects={setProjects} logAction={logAction}/>}
        {page==="playbook"   &&<PlaybookPage/>}
        {page==="archive"    &&<ArchivePage archivedClients={archClients} archivedVehicles={archVehicles} archivedJobs={archJobs} onRestore={restoreItems}/>}
        {page==="invoices"   &&<InvoiceHistoryPage invoices={invoices} customers={customers} vehicles={vehicles} jobs={jobs} onOpen={function(id){setSelInvoice(id);setPage("invoice-detail");}} onCreateFrom={createInvoiceFromJob}/>}
        {page==="invoice-detail"&&selInvoice&&<InvoiceDetail inv={invoices.find(function(x){return x.id===selInvoice;})} customers={customers} vehicles={vehicles} settings={settings} onBack={function(){setPage("invoices");}} onUpdate={updateInvoice} logAction={logAction}/>}
        {page==="estimates"  &&<EstimatesPage estimates={estimates} setEstimates={setEstimates} customers={customers} vehicles={vehicles} onConvert={convertEstimate} logAction={logAction} defaultRate={+settings.laborRate||95}/>}
        {page==="reports"    &&<ReportsPage jobs={jobs} customers={customers} invoices={invoices} expenses={expenses} setExpenses={setExpenses} logAction={logAction}/>}
        {page==="reminders"  &&<RemindersPage jobs={jobs} customers={customers} vehicles={vehicles} dismissed={dismissedRem} setDismissed={setDismissedRem} onNewJob={openNewJob} comms={comms} onUpdateComm={updateComm}/>}
        {page==="audit"      &&<AuditPage auditLog={auditLog}/>}
        {page==="settings"   &&<SettingsPage settings={settings} setSettings={setSettings} onExport={exportBackup} onImport={importBackup} logAction={logAction}/>}
      </div>
      {showNewJob&&<NewJobModal onClose={()=>{setNewJob(false);setNewJobPrefill({});}} onSave={function(j){setJobs(prev=>[j,...prev]);var c=customers.find(function(x){return x.id===j.customerId;});logAction("job_created","job",dispJobId(j.jobId),"Job "+dispJobId(j.jobId)+" created"+(c?" for "+fullName(c):j.isPersonal?" (personal time)":""));setNewJob(false);setNewJobPrefill({});}} customers={customers} vehicles={vehicles} allJobs={jobs} archJobs={archJobs} prefill={newJobPrefill} settings={settings}/>}
      {/* MOBILE BOTTOM NAV */}
      {isMobile&&(
        <div className="mm-bnav" style={{position:"fixed",bottom:0,left:0,right:0,height:62,zIndex:140,background:"var(--s1)",borderTop:"1px solid var(--bdr)",display:"flex"}}>
          {mobileTabs.map(function(t){
            var active=(t.id==="more")?(primaryIds.indexOf(page)<0&&page!=="job-detail"):(page===t.id||(t.id==="jobs"&&page==="job-detail"));
            return(
              <button key={t.id} onClick={function(){if(t.id==="more"){setMoreOpen(true);return;}go(t.id);}} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:3,background:"none",border:"none",cursor:"pointer",color:active?"var(--acc)":"var(--txt3)",position:"relative"}}>
                <span style={{fontSize:19,lineHeight:1}}>{t.icon}</span>
                <span style={{fontFamily:"var(--fd)",fontSize:9.5,fontWeight:800,letterSpacing:".02em"}}>{t.label}</span>
                {t.badge?<span style={{position:"absolute",top:7,left:"calc(50% + 6px)",background:"var(--acc)",color:"#fff",fontSize:8,fontFamily:"var(--fm)",padding:"0 4px",borderRadius:6,fontWeight:700,lineHeight:"13px"}}>{t.badge}</span>:null}
              </button>
            );
          })}
        </div>
      )}
      {/* MOBILE MORE DRAWER */}
      {isMobile&&moreOpen&&(
        <div style={{position:"fixed",inset:0,zIndex:300,background:"#000b"}} onClick={function(e){if(e.target===e.currentTarget)setMoreOpen(false);}}>
          <div className="pop" style={{width:"84%",maxWidth:320,height:"100%",background:"var(--s1)",borderRight:"1px solid var(--bdr)",display:"flex",flexDirection:"column"}}>
            <div style={{padding:"16px 16px 14px",borderBottom:"1px solid var(--bdr)",display:"flex",gap:11,alignItems:"center"}}>
              <div style={{width:40,height:40,position:"relative",flexShrink:0}}>
                <div style={{position:"absolute",inset:0,clipPath:"polygon(50% 0%,100% 25%,100% 75%,50% 100%,0% 75%,0% 25%)",background:"linear-gradient(145deg,#8a9aaa,#4a5568,#1a2332,#5a6a7a)"}}/>
                <div style={{position:"absolute",inset:"8%",clipPath:"polygon(50% 0%,100% 25%,100% 75%,50% 100%,0% 75%,0% 25%)",background:"#1e2a36",overflow:"hidden"}}>{user.pic?<img src={user.pic} style={{width:"100%",height:"100%",objectFit:"cover"}} alt=""/>:null}</div>
                {!user.pic&&<div style={{position:"absolute",width:"46%",height:"46%",top:"50%",left:"50%",transform:"translate(-50%,-50%)",borderRadius:"50%",background:"var(--acc)",display:"flex",alignItems:"center",justifyContent:"center"}}><span style={{fontFamily:"var(--fd)",fontWeight:900,fontSize:13,color:"#fff"}}>{((user.name&&user.name[0]&&user.name[0].toUpperCase())||"M")}</span></div>}
              </div>
              <div style={{flex:1,minWidth:0}}>
                <div style={{fontFamily:"var(--fd)",fontSize:15,fontWeight:900,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{user.name||"My Shop"}</div>
                {user.company&&<div style={{fontSize:10,color:"var(--txt3)",overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{user.company}</div>}
              </div>
              <button onClick={function(){setMoreOpen(false);}} aria-label="Close" style={{background:"none",border:"none",color:"var(--txt3)",width:32,height:32,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>
                <svg width="15" height="15" viewBox="0 0 15 15"><line x1="2" y1="2" x2="13" y2="13" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round"/><line x1="13" y1="2" x2="2" y2="13" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round"/></svg>
              </button>
            </div>
            <div style={{flex:1,overflowY:"auto",padding:"8px"}}>
              {NAV.map(function(n){
                var active=page===n.id;
                return(
                  <button key={n.id} onClick={function(){if(n.isSearch){setShowSearch(true);setMoreOpen(false);return;}go(n.id);setMoreOpen(false);}} style={{width:"100%",display:"flex",alignItems:"center",gap:11,padding:"11px 12px",borderRadius:"var(--r2)",background:active?"var(--s3)":"transparent",color:active?(n.accent?"var(--ylw)":"var(--acc)"):n.accent?"var(--txt3)":"var(--txt2)",border:"none",cursor:"pointer",fontFamily:"var(--fd)",fontSize:14,fontWeight:800,letterSpacing:".04em",textAlign:"left",marginBottom:2}}>
                    <span style={{fontSize:18,width:22,textAlign:"center"}}>{n.icon}</span>
                    <span style={{flex:1}}>{n.label}</span>
                    {n.badge?<span style={{background:n.accent?"var(--ylw)":"var(--acc)",color:n.accent?"#000":"#fff",fontSize:9,fontFamily:"var(--fm)",padding:"1px 6px",borderRadius:8,fontWeight:700}}>{n.badge}</span>:null}
                  </button>
                );
              })}
            </div>
            <div style={{padding:"10px 14px",borderTop:"1px solid var(--bdr)",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
              <span className="mono" style={{fontSize:9,color:"var(--txt3)"}}>{customers.length} clients &middot; {vehicles.length} vehicles</span>
              <Btn v="ghost" sz="sm" onClick={handleSignOut}>Sign Out</Btn>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

class EB extends Component {
  constructor(p){super(p);this.state={err:null};}
  static getDerivedStateFromError(e){return{err:e};}
  render(){
    if(this.state.err){
      return(
        <div style={{minHeight:"100vh",background:"#0e1214",color:"#e2e8ec",display:"flex",alignItems:"center",justifyContent:"center",padding:24,fontFamily:"sans-serif"}}>
          <div style={{maxWidth:560,width:"100%",background:"#161c20",border:"1px solid #2a343b",borderRadius:14,padding:"26px 24px"}}>
            <div style={{fontSize:19,fontWeight:800,marginBottom:8}}>Something went wrong</div>
            <div style={{fontSize:13,color:"#9fb0ba",lineHeight:1.6,marginBottom:18}}>The app hit an unexpected error. Your data is saved on this device and will be right here when you reload.</div>
            <button onClick={function(){try{window.location.reload();}catch(e2){}}} style={{background:"#f97316",color:"#fff",border:"none",borderRadius:10,padding:"10px 22px",fontSize:14,fontWeight:800,cursor:"pointer"}}>Reload App</button>
            <details style={{marginTop:18}}>
              <summary style={{cursor:"pointer",fontSize:11,color:"#5c6b74"}}>Technical details</summary>
              <pre style={{fontSize:10,whiteSpace:"pre-wrap",wordBreak:"break-all",color:"#8b9aa4",marginTop:8,lineHeight:1.5}}>{String(this.state.err)}{"\n"}{this.state.err&&this.state.err.stack?this.state.err.stack:""}</pre>
            </details>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}
export default function App(){return <EB><AppInner/></EB>;}
